41afa38e-5772-4c4b-a629-060345807514	\N	9dbf1e7b-4b2e-4c83-b5a1-cbcb529ddf4e	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mahasiswa mampu menjelaskan konsep dasar gaya, beban, momen, keseimbangan, dan sifat mekanis elemen struktur yang relevan dalam rekayasa bangunan.", "selected_cpls": ["CPL-03", "CPL-06"]}, {"code": "CPMK-2", "description": "Mahasiswa mampu menghitung reaksi tumpuan, gaya dalam, dan momen pada elemen struktur sederhana menggunakan metode analitis dasar.", "selected_cpls": ["CPL-03", "CPL-06"]}, {"code": "CPMK-3", "description": "Mahasiswa mampu menganalisis perilaku elemen struktur (balok, kolom, rangka sederhana) berdasarkan hubungan antara bentuk, material, dan sistem pembebanan.", "selected_cpls": ["CPL-03", "CPL-06"]}, {"code": "CPMK-4", "description": "Mahasiswa mampu menerapkan prinsip mekanika teknik untuk memecahkan kasus sederhana dalam perancangan struktur bangunan arsitektur.", "selected_cpls": ["CPL-03", "CPL-06"]}, {"code": "CPMK-5", "description": "Mahasiswa mampu menyajikan hasil perhitungan dan analisis mekanika teknik dalam format laporan atau grafik perhitungan secara sistematis dan akurat.", "selected_cpls": ["CPL-08", "CPL-03", "CPL-06"]}], "course": {"id": "9dbf1e7b-4b2e-4c83-b5a1-cbcb529ddf4e", "code": "CW6232012104", "title": "Mekanika Teknik", "credits": 2, "semester": 1}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu mendefinisikan dan menggambarkan berbagai jenis gaya yang bekerja pada elemen struktur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menghitung beban yang diterima oleh struktur berdasarkan kondisi nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menjelaskan konsep momen dan bagaimana momen mempengaruhi keseimbangan elemen struktur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menghitung reaksi tumpuan pada balok sederhana dengan menggunakan metode keseimbangan statis.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menentukan gaya dalam pada elemen struktur sederhana seperti balok dan rangka menggunakan metode potongan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menghitung momen pada titik tertentu dari elemen struktur sederhana dengan menggunakan diagram bebas.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu menghitung momen inersia dan kekuatan maksimum balok berdasarkan bentuk penampang dan material yang digunakan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu menganalisis distribusi gaya internal pada kolom akibat beban eksentrik dan beban aksial.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu merancang sistem rangka sederhana dengan mempertimbangkan faktor keamanan dan efisiensi material.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menghitung gaya dan momen pada struktur sederhana menggunakan hukum Newton dan prinsip keseimbangan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menganalisis beban yang bekerja pada struktur bangunan arsitektur dan menentukan reaksi pendukung.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menerapkan metode analisis struktural sederhana untuk menentukan deformasi pada elemen struktur.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu mengidentifikasi dan mengumpulkan data yang relevan untuk analisis mekanika teknik dari sumber yang terpercaya.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu melakukan perhitungan mekanika teknik menggunakan metode analisis yang sesuai dan mencatat langkah-langkahnya secara sistematis.", "relatedCpmk": "CPMK-5"}], "semester": "1", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu mendefinisikan dan menggambarkan berbagai jenis gaya yang bekerja pada elemen struktur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menghitung beban yang diterima oleh struktur berdasarkan kondisi nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menjelaskan konsep momen dan bagaimana momen mempengaruhi keseimbangan elemen struktur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menghitung reaksi tumpuan pada balok sederhana dengan menggunakan metode keseimbangan statis.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menentukan gaya dalam pada elemen struktur sederhana seperti balok dan rangka menggunakan metode potongan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menghitung momen pada titik tertentu dari elemen struktur sederhana dengan menggunakan diagram bebas.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu menghitung momen inersia dan kekuatan maksimum balok berdasarkan bentuk penampang dan material yang digunakan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu menganalisis distribusi gaya internal pada kolom akibat beban eksentrik dan beban aksial.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu merancang sistem rangka sederhana dengan mempertimbangkan faktor keamanan dan efisiensi material.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menghitung gaya dan momen pada struktur sederhana menggunakan hukum Newton dan prinsip keseimbangan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menganalisis beban yang bekerja pada struktur bangunan arsitektur dan menentukan reaksi pendukung.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menerapkan metode analisis struktural sederhana untuk menentukan deformasi pada elemen struktur.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu mengidentifikasi dan mengumpulkan data yang relevan untuk analisis mekanika teknik dari sumber yang terpercaya.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu melakukan perhitungan mekanika teknik menggunakan metode analisis yang sesuai dan mencatat langkah-langkahnya secara sistematis.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Mekanika Teknik ini bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dasar mekanika yang berkaitan dengan analisis dan desain struktur teknik. Materi yang akan dibahas meliputi gaya, momen, keseimbangan, dan deformasi pada berbagai jenis material, serta penerapan hukum Newton dan teori elastisitas. Selain itu, mahasiswa akan diperkenalkan pada metode analisis statis dan dinamis yang penting dalam rekayasa. Melalui mata kuliah ini, diharapkan mahasiswa mampu menerapkan konsep-konsep mekanika dalam menyelesaikan permasalahan teknik yang kompleks, serta meningkatkan kemampuan analitis dan kritis dalam merancang struktur yang aman dan efisien.", "referensi": [], "bahanKajian": ["", "", ""], "description": "Mata kuliah Mekanika Teknik ini bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dasar mekanika yang berkaitan dengan analisis dan