19715139-875f-4070-859a-7f5f9d6ffbd8	\N	4c286e09-b9b5-4a97-a246-9febe628a339	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas konsep dasar struktur dan sifat bahan teknik, termasuk logam, polimer, keramik, dan komposit. Materi meliputi struktur atom, ikatan kimia, struktur kristal, cacat kristal, sifat mekanik bahan, difusi, diagram fasa, serta perilaku material terhadap panas, beban, dan lingkungan. Mahasiswa dibekali dasar-dasar sains material yang diperlukan untuk memahami pemilihan dan karakterisasi bahan dalam sistem teknik tanpa berfokus pada proses manufaktur lanjutan.", "selected_cpls": ["CPL-01", "CPL-03"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan struktur atom, ikatan kimia, struktur kristal, dan cacat kristal pada berbagai jenis material teknik.", "selected_cpls": ["CPL-01", "CPL-03"]}, {"code": "CPMK-3", "description": "Mampu menganalisis hubungan antara struktur mikroskopis material dengan sifat mekanik, termal, dan listriknya.", "selected_cpls": ["CPL-01", "CPL-03", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu menerapkan prinsip dasar ilmu bahan untuk mengevaluasi perilaku material terhadap beban, suhu, dan lingkungan pada kasus teknik sederhana.", "selected_cpls": ["CPL-01", "CPL-03", "CPL-04"]}, {"code": "CPMK-5", "description": "Mampu mengevaluasi kesesuaian material dasar (logam, polimer, keramik, komposit) berdasarkan sifat fisik dan mekaniknya untuk kebutuhan teknik tingkat dasar.", "selected_cpls": ["CPL-01", "CPL-03", "CPL-04"]}], "course": {"id": "4c286e09-b9b5-4a97-a246-9febe628a339", "code": "CW6202012103", "title": "Ilmu Bahan", "credits": 2, "semester": 1}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menjelaskan struktur atom dan ikatan kimia serta pengaruhnya terhadap sifat mekanik bahan teknik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat mengidentifikasi dan menganalisis berbagai jenis