84077cd0-4b64-4bbc-bfe3-b21e451e5d14	\N	dc71a37a-1ac7-4564-8873-4d08fd373f2a	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mahasiswa mampu menjelaskan konsep arsitektur inklusif dan desain universal serta relevansinya dalam perancangan ruang.", "selected_cpls": ["CPL-02", "CPL-01"]}, {"code": "CPMK-2", "description": "Mahasiswa mampu menganalisis kebutuhan pengguna dari berbagai latar belakang, usia, dan kemampuan fisik.", "selected_cpls": ["CPL-02", "CPL-01"]}, {"code": "CPMK-3", "description": "Mahasiswa mampu menerapkan prinsip desain inklusif pada perancangan bangunan dan lingkungan binaan sesuai standar aksesibilitas.", "selected_cpls": ["CPL-02", "CPL-01"]}, {"code": "CPMK-4", "description": "Mahasiswa mampu memilih material, teknologi, dan detail konstruksi yang mendukung kenyamanan, keamanan, dan kemudahan akses bagi semua pengguna.", "selected_cpls": ["CPL-06", "CPL-07", "CPL-02"]}, {"code": "CPMK-5", "description": "Mahasiswa mampu menyajikan rancangan arsitektur inklusif dalam bentuk gambar, model, dan dokumen teknis secara profesional.", "selected_cpls": ["CPL-02", "CPL-05", "CPL-08"]}], "course": {"id": "dc71a37a-1ac7-4564-8873-4d08fd373f2a", "code": "CP6232012503", "title": "Arsitektur Inklusif (Pilihan)", "credits": 2, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu mengidentifikasi elemen-elemen desain yang mendukung arsitektur inklusif dalam berbagai proyek arsitektur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menganalisis studi kasus terkait penerapan desain universal dalam arsitektur publik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu merancang ruang yang memenuhi prinsip arsitektur inklusif dengan mempertimbangkan kebutuhan pengguna yang beragam.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat melakukan survei untuk mengidentifikasi kebutuhan pengguna dari berbagai kelompok usia dalam konteks arsitektur inklusif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menyusun profil pengguna yang mencakup latar belakang, usia, dan kemampuan fisik untuk mendukung desain arsitektur inklusif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat menganalisis data yang diperoleh dari pengguna untuk menentukan fitur desain yang diperlukan dalam ruang publik yang inklusif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu menganalisis dan mengidentifikasi elemen desain yang mendukung aksesibilitas dalam bangunan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu merancang layout bangunan dengan mempertimbangkan kebutuhan pengguna dengan disabilitas.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu mengevaluasi dan merekomendasikan perbaikan pada desain bangunan yang sudah ada agar memenuhi standar aksesibilitas.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menganalisis dan memilih material yang ramah lingkungan dan berkelanjutan untuk digunakan dalam desain arsitektur inklusif.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu merancang solusi teknologi bangunan yang meningkatkan aksesibilitas bagi penyandang disabilitas.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu mengembangkan detail konstruksi yang memastikan keamanan pengguna, termasuk penggunaan elemen desain yang mendukung keselamatan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu mengidentifikasi dan menganalisis kebutuhan pengguna dalam merancang ruang arsitektur yang inklusif.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu membuat sketsa awal dan diagram alur yang menggambarkan konsep arsitektur inklusif.", "relatedCpmk": "CPMK-5"}], "semester": "5", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu mengidentifikasi elemen-elemen desain yang mendukung arsitektur inklusif dalam berbagai proyek arsitektur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menganalisis studi kasus terkait penerapan desain universal dalam arsitektur publik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu merancang ruang yang memenuhi prinsip arsitektur inklusif dengan mempertimbangkan kebutuhan pengguna yang beragam.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat melakukan survei untuk mengidentifikasi kebutuhan pengguna dari berbagai kelompok usia dalam konteks arsitektur inklusif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu menyusun profil pengguna yang mencakup latar belakang, usia, dan kemampuan fisik untuk mendukung desain arsitektur inklusif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat menganalisis data yang diperoleh dari pengguna untuk menentukan fitur desain yang diperlukan dalam ruang publik yang inklusif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu menganalisis dan mengidentifikasi elemen desain yang mendukung aksesibilitas dalam bangunan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu merancang layout bangunan dengan mempertimbangkan kebutuhan pengguna dengan disabilitas.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu mengevaluasi dan merekomendasikan perbaikan pada desain bangunan yang sudah ada agar memenuhi standar aksesibilitas.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menganalisis dan memilih material yang ramah lingkungan dan berkelanjutan untuk digunakan dalam desain arsitektur inklusif.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu merancang solusi teknologi bangunan yang meningkatkan aksesibilitas bagi penyandang disabilitas.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu mengembangkan detail konstruksi yang memastikan keamanan pengguna, termasuk penggunaan elemen desain yang mendukung keselamatan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu mengidentifikasi dan menganalisis kebutuhan pengguna dalam merancang ruang arsitektur yang inklusif.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mahasiswa mampu membuat sketsa awal dan diagram alur yang menggambarkan konsep arsitektur inklusif.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Arsitektur Inklusif bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dan praktik desain arsitektur yang dapat diakses oleh semua individu, termasuk mereka yang memiliki kebutuhan khusus. Materi yang dibahas meliputi teori aksesibilitas, analisis pengguna, desain universal, serta regulasi dan standar terkait arsitektur inklusif. Melalui studi kasus dan proyek praktis, mahasiswa akan belajar untuk menerapkan konsep-konsep tersebut dalam merancang ruang yang ramah bagi semua kalangan. Manfaat dari mata kuliah ini tidak hanya mencakup peningkatan keterampilan teknis dan kreatif mahasiswa, tetapi juga penanaman nilai sosial yang menghargai keberagaman dan kesetaraan dalam li