b9b26a63-9008-4c2d-b31f-66fa5305d0ea	\N	72d1704d-5319-453c-8750-bb293eded7de	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep dan arsitektur dasar Generative AI dan LLM", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-2", "description": "Mengimplementasikan model generatif menggunakan framework", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-3", "description": "Melakukan pre-training dan fine-tuning model LLM untuk domain spesifik", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-4", "description": "Mengevaluasi kinerja model generatif berdasarkan metrik", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-5", "description": "Mengoptimalkan model melalui teknik prompt engineering, transfer learning, dan parameter-efficient fine-tuning", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-6", "description": "Menerapkan prinsip etika dan keamanan AI dalam pembangunan sistem berbasis LLM", "selected_cpls": ["CPL-04", "CPL-03"]}], "course": {"id": "72d1704d-5319-453c-8750-bb293eded7de", "code": "CW6552021669", "title": "Praktikum Generative AI and Large Language Models", "credits": 1, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan komponen utama dalam arsitektur Generative AI dan LLM, termasuk encoder, decoder, dan attention mechanism.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis perbedaan antara berbagai model Generative AI, seperti GPT, BERT, dan lainnya, serta aplikasinya dalam berbagai domain.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menerapkan teknik dasar dalam pengembangan model Generative AI menggunakan pustaka pemrograman yang relevan, seperti TensorFlow atau PyTorch.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan konsep dasar model generatif dan framework yang digunakan dalam pengembangannya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Dapat mengimplementasikan model generatif sederhana menggunakan salah satu framework yang tersedia.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu melakukan evaluasi terhadap hasil keluaran model generatif dan memberikan analisis perbaikan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan memilih dataset yang relevan untuk pre-training model LLM pada domain spesifik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Dapat melakukan pre-processing data untuk mempersiapkan dataset sebelum tahap pre-training model LLM.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menjelaskan metrik yang digunakan untuk mengevaluasi kinerja model generatif.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Dapat menerapkan metrik evaluasi untuk menilai kinerja model generatif dalam berbagai konteks aplikasi.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-5", "description": "Mahasiswa dapat menjelaskan konsep dasar prompt engineering dan penerapannya dalam model generatif.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-5", "description": "Mahasiswa dapat menerapkan teknik transfer learning untuk meningkatkan performa model pada dataset yang berbeda.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-6", "description": "Menganalisis dan mengidentifikasi potensi risiko etika dalam penggunaan LLM di berbagai aplikasi.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-6", "description": "Menerapkan protokol keamanan data saat mengembangkan aplikasi berbasis LLM untuk melindungi privasi pengguna.", "relatedCpmk": "CPMK-6"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan komponen utama dalam arsitektur Generative AI dan LLM, termasuk encoder, decoder, dan attention mechanism.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis perbedaan antara berbagai model Generative AI, seperti GPT, BERT, dan lainnya, serta aplikasinya dalam berbagai domain.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menerapkan teknik dasar dalam pengembangan model Generative AI menggunakan pustaka pemrograman yang relevan, seperti TensorFlow atau PyTorch.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan konsep dasar model generatif dan framework yang digunakan dalam pengembangannya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Dapat mengimplementasikan model generatif sederhana menggunakan salah satu framework yang tersedia.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu melakukan evaluasi terhadap hasil keluaran model generatif dan memberikan analisis perbaikan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan memilih dataset yang relevan untuk pre-training model LLM pada domain spesifik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Dapat melakukan pre-processing data untuk mempersiapkan dataset sebelum tahap pre-training model LLM.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menjelaskan metrik yang digunakan untuk mengevaluasi kinerja model generatif.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Dapat menerapkan metrik evaluasi untuk menilai kinerja model generatif dalam berbagai konteks aplikasi.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-5", "description": "Mahasiswa dapat menjelaskan konsep dasar prompt engineering dan penerapannya dalam model generatif.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-5", "description": "Mahasiswa dapat menerapkan teknik transfer learning untuk meningkatkan performa model pada dataset yang berbeda.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-6", "description": "Menganalisis dan mengidentifikasi potensi risiko etika dalam penggunaan LLM di berbagai aplikasi.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-6", "description": "Menerapkan protokol keamanan data saat mengembangkan aplikasi berbasis LLM untuk melindungi privasi pengguna.", "relatedCpmk": "CPMK-6"}], "deskripsi": "Mata kuliah Praktikum Generative AI and Large Language Models bertujuan untuk memberikan pemahaman dan keterampilan praktis dalam mengembangkan dan menerapkan model AI generatif serta model bahasa besar. Dalam perkuliahan ini, mahasiswa akan mempelajari konsep dasar dan teknik terkini dalam generative AI, termasuk arsitektur model, pelatihan, dan evaluasi. Materi yang diajarkan mencakup penggunaan alat dan pustaka yang relevan, serta studi kasus yang menggambarkan aplikasi nyata dari teknologi ini dalam berbagai bidang, seperti pemrosesan bahasa alami, seni, dan desain. Melalui praktikum, mahasiswa diharapkan dapat mengembangkan proyek yang mengintegrasikan teori dan praktik, sehingga meningkatkan kemampuan analitis dan kreatif mereka dalam menghadapi tantangan di era digital.", "referensi": ["David Foster (2021). Generative Deep Learning: Teaching Machines to Paint, Write, Compose, and Play. O'Reilly Media.", "Lewis Tunstall, Leandro von Werra, Thomas Wolf (2022). Natural Language Processing with Transformers: Building Language Applications with Hugging Face. O'Reilly Media.", "Aur├⌐lien G├⌐ron (2022). Hands-On Machine Learning with Scikit-Learn, Keras, and TensorFlow. O'Reilly Media.", "Palash Goyal, et al. (2023). Deep Learning for Natural Language Processing: Creating Neural Networks with Python. Springer.", "Emilia Smith (2021). Building Machine Learning Powered Applications: Going from Idea to Product. O'Reilly Media.", "Zhang, Y., et al. (2021). A Survey on Generative Adversarial Networks: Challenges and Applications. IEEE Transactions on Neural Networks and Learning Systems.", "Gururangan, S., et al. (2020). Fine-tuning Pre-trained Language Models: Weight Initializations, Data Orders, and Early Stopping. Proceedings of the 58th Annual Meeting of the Association for Computational Linguistics.", "Vincent C. M├╝ller (2020). Ethics of AI and Robotics. Stanford Encyclopedia of Philosophy.", "Holtzman, A., et al. (2020). Understanding the Limitations of Generative Language Models. Proceedings of the 37th International Conference on Machine Learning.", "Karras, T., et al. (2022). Trends in Generative Models: A Survey. ACM Computing Surveys."], "bahanKajian": ["Topik 1: Pengenalan Generative AI dan Large Language Models - Menjelaskan konsep dasar dan arsitektur Generative AI dan LLM, termasuk model-model terkenal seperti GPT dan BERT.", "Topik 2: Framework untuk Implementasi Model Generatif - Menggunakan framework seperti TensorFlow dan PyTorch untuk mengimplementasikan model generatif, serta memahami cara kerja di baliknya.", "Topik 3: Pre-training dan Fine-tuning LLM - Memahami proses pre-training dan fine-tuning model LLM untuk aplikasi domain spesifik, serta tantangan yang dihadapi.", "Topik 4: Evaluasi Kinerja Model Generatif - Mengidentifikasi metrik yang digunakan untuk mengevaluasi kinerja model generatif dan bagaimana cara menganalisis hasil evaluasi.", "Topik 5: Teknik Optimasi Model - Mempelajari teknik-teknik seperti prompt engineering, transfer learning, dan parameter-efficient fine-tuning untuk mengoptimalkan performa model.", "Topik 6: Etika dan Keamanan dalam AI - Menerapkan prinsip etika dan keamanan dalam pengembangan sistem berbasis LLM, serta membahas isu-isu terkait privasi dan bias dalam AI.", "Topik 7: Studi Kasus Implementasi LLM - Menganalisis studi kasus nyata tentang penerapan LLM dalam industri, termasuk tantangan dan solusi yang diterapkan.", "Topik 8: Tren dan Masa Depan Generative AI - Membahas perkembangan terbaru dalam Generative AI dan LLM, serta prediksi mengenai masa depan teknologi ini."], "description": "Mata kuliah Praktikum Generative AI and Large Language Models bertujuan untuk memberikan pemahaman dan keterampilan praktis dalam mengembangkan dan menerapkan model AI generatif serta model bahasa besar. Dalam perkuliahan ini, mahasiswa akan mempelajari konsep dasar dan teknik terkini dalam generative AI, termasuk arsitektur model, pelatihan, dan evaluasi. Materi yang diajarkan mencakup penggunaan alat dan pustaka yang relevan, serta studi kasus yang menggambarkan aplikasi nyata dari teknologi ini dalam berbagai bidang, seperti pemrosesan bahasa alami, seni, dan desain. Melalui praktikum, mahasiswa diharapkan dapat mengembangkan proyek yang mengintegrasikan teori dan praktik, sehingga meningkatkan kemampuan analitis dan kreatif mereka dalam menghadapi tantangan di era digital.", "bahan_kajian": ["Topik 1: Pengenalan Generative AI dan Large Language Models - Menjelaskan konsep dasar dan arsitektur Generative AI dan LLM, termasuk model-model terkenal seperti GPT dan BERT.", "Topik 2: Framework untuk Implementasi Model Generatif - Menggunakan framework seperti TensorFlow dan PyTorch untuk mengimplementasikan model generatif, serta memahami cara kerja di baliknya.", "Topik 3: Pre-training dan Fine-tuning LLM - Memahami proses pre-training dan fine-tuning model LLM untuk aplikasi domain spesifik, serta tantangan yang dihadapi.", "Topik 4: Evaluasi Kinerja Model Generatif - Mengidentifikasi metrik yang digunakan untuk mengevaluasi kinerja model generatif dan bagaimana cara menganalisis hasil evaluasi.", "Topik 5: Teknik Optimasi Model - Mempelajari teknik-teknik seperti prompt engineering, transfer learning, dan parameter-efficient fine-tuning untuk mengoptimalkan performa model.", "Topik 6: Etika dan Keamanan dalam AI - Menerapkan prinsip etika dan keamanan dalam pengembangan sistem berbasis LLM, serta membahas isu-isu terkait privasi dan bias dalam AI.", "Topik 7: Studi Kasus Implementasi LLM - Menganalisis studi kasus nyata tentang penerapan LLM dalam industri, termasuk tantangan dan solusi yang diterapkan.", "Topik 8: Tren dan Masa Depan Generative AI - Membahas perkembangan terbaru dalam Generative AI dan LLM, serta prediksi mengenai masa depan teknologi ini."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "ba