b2cd333b-b25a-4deb-96ca-d7e12ce349ec	\N	52f9e0ce-9ece-4d14-a2e2-73365f491e9d	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "menjelaskan komponen dasar sistem komputer, termasuk perangkat keras, perangkat lunak, sistem operasi, penyimpanan data", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-2", "description": "mengoperasikan sistem operasi (Windows/Linux) untuk melakukan manajemen file, pengaturan dasar, instalasi sederhana, dan navigasi perangkat komputer secara efektif", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-3", "description": "menggunakan aplikasi perkantoran dasar (word processing, spreadsheet, dan presentation) untuk membuat dokumen tekstual, tabel data, grafik sederhana, dan presentasi sesuai standar akademik", "selected_cpls": ["CPL-06", "CPL-01"]}, {"code": "CPMK-4", "description": "Menggunakan internet, mesin pencari, email, dan platform digital secara efektif serta memahami etika digital, keamanan siber dasar, dan penggunaan teknologi secara bertanggung jawab", "selected_cpls": ["CPL-09", "CPL-06", "CPL-10"]}], "course": {"id": "52f9e0ce-9ece-4d14-a2e2-73365f491e9d", "code": "CW6220202102", "title": "Komputer 1", "credits": 2, "semester": 1}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "mengidentifikasi dan menjelaskan fungsi masing-masing komponen perangkat keras dalam sistem komputer", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "membedakan jenis-jenis perangkat lunak dan menjelaskan peranannya dalam sistem komputer", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "menjelaskan fungsi dan jenis-jenis sistem operasi serta cara kerjanya dalam mengelola perangkat keras", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-1", "description": "menggambarkan berbagai metode penyimpanan data dan cara akses data dalam sistem komputer", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menggunakan perintah dasar untuk navigasi file di Windows dan Linux.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Dapat melakukan manajemen file dengan efektif, termasuk membuat, menghapus, dan memindahkan file dan folder.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-2", "description": "Mampu mengatur pengaturan dasar sistem operasi, termasuk pengaturan tampilan dan aksesibilitas.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-2", "description": "Dapat melakukan instalasi perangkat lunak sederhana di Windows dan Linux dengan mengikuti langkah-langkah yang benar.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu membuat dokumen teks dengan format yang benar menggunakan aplikasi pengolah kata, termasuk pengaturan margin, spasi, dan pemformatan paragraf.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-3", "description": "Dapat membuat dan mengelola tabel data sederhana di spreadsheet, termasuk penginputan data, penggunaan formula dasar, dan pengaturan format sel.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-3", "description": "Mampu membuat grafik sederhana di spreadsheet berdasarkan data yang telah diolah, serta mampu menambahkan label dan legend yang sesuai.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu melakukan pencarian informasi secara efektif menggunakan berbagai mesin pencari dengan teknik pencarian lanjutan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-4", "description": "Mampu membuat dan mengelola akun email, serta memahami fitur-fitur dasar yang ada dalam layanan email.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menerapkan prinsip-prinsip etika digital dalam penggunaan internet dan media sosial.", "relatedC