f445ad45-6cbf-4c6e-9bea-d7934293bd5c	\N	e0dc5153-d192-4d5c-a6e4-b75aa827948b	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep dasar Natural Language Processing dan representasi data teks.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-2", "description": "Mengimplementasikan teknik preprocessing teks seperti tokenisasi, stemming, dan stopword removal.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-3", "description": "Membangun model NLP berbasis machine learning dan deep learning sederhana.", "selected_cpls": ["CPL-05", "CPL-01", "CPL-02"]}, {"code": "CPMK-4", "description": "Menggunakan embedding modern seperti Word2Vec, GloVe, dan Transformer embeddings untuk representasi", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-5", "description": "Mengevaluasi performa model NLP menggunakan metrik seperti F1-score, BLEU, dan perplexity", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-6", "description": "Menerapkan teknik fine-tuning model pra-latih (BERT, GPT, T5) untuk aplikasi NLP spesifik", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-7", "description": "Menunjukkan kemampuan kerja tim, etika profesional, dan tanggung jawab dalam proyek NLP", "selected_cpls": ["CPL-03", "CPL-04", "CPL-05"]}], "course": {"id": "e0dc5153-d192-4d5c-a6e4-b75aa827948b", "code": "CW6552021672", "title": "Praktikum Natural Language Processing (NLP)", "credits": 1, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan komponen utama dalam Natural Language Processing seperti tokenisasi, stemming, dan lemmatization.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menerapkan teknik representasi teks seperti Bag of Words dan TF-IDF dalam analisis data teks.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu melakukan tokenisasi pada teks menggunakan metode berbasis aturan dan pembelajaran mesin", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Dapat menerapkan algoritma stemming untuk mengubah kata ke bentuk dasarnya dan mengevaluasi hasilnya", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mengumpulkan dataset teks yang relevan untuk pengembangan model NLP.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Dapat menerapkan teknik preprocessing data teks, seperti tokenisasi, stemming, dan stopword removal.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan Word2Vec untuk menghasilkan representasi vektor dari kumpulan data teks sederhana", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Mampu menggunakan GloVe untuk mendapatkan representasi vektor kata dan menganalisis kualitas representasi tersebut", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Menghitung dan menganalisis nilai F1-score dari model NLP pada dataset tertentu untuk menilai keseimbangan antara precision dan recall.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Menggunakan metrik BLEU untuk mengevaluasi kualitas terjemahan model NLP dengan membandingkan hasil terjemahan dengan referensi terjemahan yang sudah ada.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Mampu mengidentifikasi dataset yang sesuai untuk fine-tuning model BERT dalam tugas klasifikasi teks.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Dapat melakukan preprocessing data teks dengan menggunakan teknik tokenisasi yang tepat untuk model GPT.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu berkontribusi secara aktif dalam diskusi kelompok mengenai permasalahan yang dihadapi dalam proyek NLP.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Menunjukkan kemampuan untuk mengambil peran kepemimpinan dalam tim untuk menyelesaikan tugas tertentu dalam proyek NLP.", "relatedCpmk": "CPMK-7"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan komponen utama dalam Natural Language Processing seperti tokenisasi, stemming, dan lemmatization.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menerapkan teknik representasi teks seperti Bag of Words dan TF-IDF dalam analisis data teks.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu melakukan tokenisasi pada teks menggunakan metode berbasis aturan dan pembelajaran mesin", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Dapat menerapkan algoritma stemming untuk mengubah kata ke bentuk dasarnya dan mengevaluasi hasilnya", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mengumpulkan dataset teks yang relevan untuk pengembangan model NLP.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Dapat menerapkan teknik preprocessing data teks, seperti tokenisasi, stemming, dan stopword removal.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan Word2Vec untuk menghasilkan representasi vektor dari kumpulan data teks sederhana", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Mampu menggunakan GloVe untuk mendapatkan representasi vektor kata dan menganalisis kualitas representasi tersebut", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Menghitung dan menganalisis nilai F1-score dari model NLP pada dataset tertentu untuk menilai keseimbangan antara precision dan recall.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Menggunakan metrik BLEU untuk mengevaluasi kualitas terjemahan model NLP dengan membandingkan hasil terjemahan dengan referensi terjemahan yang sudah ada.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Mampu mengidentifikasi dataset yang sesuai untuk fine-tuning model BERT dalam tugas klasifikasi teks.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Dapat melakukan preprocessing data teks dengan menggunakan teknik tokenisasi yang tepat untuk model GPT.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu berkontribusi secara aktif dalam diskusi kelompok mengenai permasalahan yang dihadapi dalam proyek NLP.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Menunjukkan kemampuan untuk mengambil peran kepemimpinan dalam tim untuk menyelesaikan tugas tertentu dalam proyek NLP.", "relatedCpmk": "CPMK-7"}], "deskripsi": "Mata kuliah Praktikum Natural Language Processing (NLP) bertujuan untuk memberikan pemahaman praktis mengenai teknik dan algoritma yang digunakan dalam pengolahan bahasa alami. Dalam mata kuliah ini, mahasiswa akan mempelajari berbagai metode seperti tokenisasi, stemming, lemmatization, dan analisis sentimen, serta aplikasi NLP dalam konteks dunia nyata. Mahasiswa akan melakukan eksperimen menggunakan bahasa pemrograman dan alat bantu yang relevan untuk mengembangkan keterampilan praktis dalam menangani data teks. Manfaat dari mata kuliah ini termasuk peningkatan kemampuan analisis data, pemahaman mendalam tentang interaksi manusia-komputer, serta kesiapan untuk berkontribusi dalam proyek-proyek yang melibatkan teknologi bahasa dan AI di industri.", "referensi": ["Daniel Jurafsky, James H. Martin (2023). Speech and Language Processing: An Introduction to Natural Language Processing, Computational Linguistics, and Speech Recognition. Prentice Hall.", "Lewis Tunstall, Leandro von Werra, Thomas Wolf (2022). Natural Language Processing with Transformers: Building Language Applications with Hugging Face. O'Reilly Media.", "Rajesh Arumugam, Rajalingappaa Shanmugamani (2021). Hands-On Natural Language Processing with R: Build applications with the latest NLP techniques. Packt Publishing.", "Hobson Lane, Hannes Hapke, Cole Howard (2021). Natural Language Processing in Action: How to Use NLP to Build Powerful Language Applications. Manning Publications.", "Palash Goyal, et al. (2020). Deep Learning for Natural Language Processing: Creating Neural Networks with Python. Springer.", "Kumar, A., & Tiwari, P. (2021). A Survey on Deep Learning Techniques for Natural Language Processing. Journal of Natural Language Engineering.", "Sanh, V., et al. (2020). Fine-tuning Pre-trained Language Models: Weight Initializations, Data Orders, and Early Stopping. Proceedings of the 58th Annual Meeting of the Association for Computational Linguistics.", "Mishra, A., & Sinha, A. (2022). An Overview of Natural Language Processing in Healthcare: Applications and Challenges. International Journal of Medical Informatics.", "Patel, R., & Desai, A. (2023). Evaluating the Performance of NLP Models: A Comprehensive Review. Journal of Artificial Intelligence Research.", "Zhang, Y., et al. (2022). Natural Language Processing: A Comprehensive Survey. IEEE Transactions on Neural Networks and Learning Systems."], "bahanKajian": ["Topik 1: Pengenalan Natural Language Processing - Menjelaskan konsep dasar NLP, sejarah, dan aplikasinya dalam berbagai bidang.", "Topik 2: Representasi Data Teks - Menggali berbagai metode representasi teks seperti bag-of-words, TF-IDF, dan embedding.", "Topik 3: Teknik Preprocessing Teks - Mengimplementasikan teknik dasar seperti tokenisasi, stemming, lemmatization, dan penghapusan stopwords.", "Topik 4: Machine Learning untuk NLP - Membangun model NLP sederhana menggunakan algoritma machine learning seperti Naive Bayes, SVM, dan Decision Trees.", "Topik 5: Deep Learning dalam NLP - Mempelajari arsitektur model deep learning seperti LSTM dan CNN untuk aplikasi NLP.", "Topik 6: Penggunaan Embedding Modern - Menggunakan teknik embedding seperti Word2Vec, GloVe, dan Transformer embeddings dalam representasi teks.", "Topik 7: Evaluasi Model NLP - Menerapkan metrik evaluasi seperti F1-score, BLEU, dan perplexity untuk menilai performa model.", "Topik 8: Fine-tuning Model Pra-latih - Menerapkan teknik fine-tuning untuk model BERT, GPT, dan T5 dalam konteks aplikasi NLP spesifik."], "description": "Mata kuliah Praktikum Natural Language Processing (NLP) bertujuan untuk memberikan pemahaman praktis mengenai teknik dan algoritma yang digunakan dalam pengolahan bahasa alami. Dalam mata kuliah ini, mahasiswa akan mempelajari berbagai metode seperti tokenisasi, stemming, lemmatization, dan analisis sentimen, serta aplikasi NLP dalam konteks dunia nyata. Mahasiswa akan melakukan eksperimen menggunakan bahasa pemrograman dan alat bantu yang relevan untuk mengembangkan keterampilan praktis dalam menangani data teks. Manfaat dari mata kuliah ini termasuk peningkatan kemampuan analisis data, pemahaman mendalam tentang interaksi manusia-komputer, serta kesiapan untuk berkontribusi dalam proyek-proyek yang melibatkan teknologi bahasa dan AI di industri.", "bahan_kajian": ["Topik 1: Pengenalan Natural Language Processing - Menjelaskan konsep dasar NLP, sejarah, dan aplikasinya dalam berbagai bidang.", "Topik 2: Representasi Data Teks - Menggali berbagai metode representasi teks seperti bag-of-words, TF-IDF, dan embedding.", "Topik 3: Teknik Preprocessing Teks - Mengimplementasikan teknik dasar seperti tokenisasi, stemming, lemmatization, dan penghapusan stopwords.", "Topik 4: Machine Learning untuk NLP - Membangun model NLP sederhana menggunakan algoritma machine learning seperti Naive Bayes, SVM, dan Decision Trees.", "Topik 5: Deep Learning dalam NLP - Mempelajari arsitektur model deep learning seperti LSTM dan CNN untuk aplikasi NLP.", "Topik 6: Penggunaan Embedding Modern - Menggunakan teknik embedding seperti Word2Vec, GloVe, dan Transformer embeddings dalam representasi teks.", "Topik 7: Evaluasi Model NLP - Menerapkan metrik evaluasi seperti F1-score, BLEU, dan perplexity untuk menilai performa model.", "Topik 8: Fine-tuning Model Pra-latih - Menerapkan teknik fine-tuning untuk model BERT, GPT, dan T5 dalam konteks aplikasi NLP spesifik."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "t