630d6df2-3c4d-494c-a331-f59f62e9f7c9	\N	48a15618-2aa2-4fea-82d3-1841d364186f	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "menjelaskan konsep dasar sistem Bumi, termasuk geosfer , proses internal-eksternal Bumi, dan keterkaitannya dengan fenomena alam", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-2", "description": "mengidentifikasi jenis batuan, mineral, tanah, serta struktur geologi berdasarkan karakteristik fisik dan proses pembentukannya, baik melalui pengamatan langsung maupun literatur", "selected_cpls": ["CPL-01", "CPL-03"]}, {"code": "CPMK-3", "description": "menganalisis proses geologi (vulkanisme, tektonik, pelapukan, erosi, sedimentasi) dan mendeksripsikan bentuklahan (geomorfologi) serta implikasinya terhadap lingkungan dan pembangunan", "selected_cpls": ["CPL-01", "CPL-03", "CPL-04"]}, {"code": "CPMK-4", "description": "menjelaskan keterkaitan proses kebumian dengan sumber daya alam (air, mineral, energi) dan potensi kebencanaan geologi seperti gempa, longsor, banjir, serta upaya mitigasinya", "selected_cpls": ["CPL-01", "CPL-02", "CPL-04"]}, {"code": "CPMK-5", "description": "menerapkan konsep sains kebumian dalam analisis awal untuk perencanaan teknik, termasuk penentuan kondisi tanah, tata air, kestabilan lereng, dan evaluasi lingkungan pada suatu wilayah", "selected_cpls": ["CPL-01", "CPL-04", "CPL-03"]}], "course": {"id": "48a15618-2aa2-4fea-82d3-1841d364186f", "code": "CW6220202207", "title": "Sains Kebumian (Hidrologi I)", "credits": 2, "semester": 2}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan komponen utama geosfer Bumi dan karakteristik masing-masing komponen", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis proses internal Bumi, seperti tektonik lempeng dan vulkanisme, serta dampaknya terhadap permukaan Bumi", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan proses eksternal Bumi, seperti erosi dan sedimentasi, serta peranannya dalam membentuk lanskap", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mengklasifikasikan jenis batuan berdasarkan sifat fisik seperti warna, tekstur, dan kepadatan", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi dan menjelaskan proses pembentukan mineral melalui pengamatan mikroskopis", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Menganalisis sampel tanah berdasarkan komposisi dan struktur lapisan tanah", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Menganalisis faktor-faktor yang mempengaruhi proses vulkanisme dan dampaknya terhadap lingkungan sekitar.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Menjelaskan mekanisme tektonik dan hubungannya dengan pembentukan bentuk lahan serta implikasinya terhadap risiko bencana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mengidentifikasi jenis-jenis pelapukan dan erosi serta dampaknya terhadap kualitas tanah dan penggunaan lahan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "menganalisis siklus hidrologi dan pengaruhnya terhadap ketersediaan sumber daya air", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "menjelaskan proses pembentukan mineral dan kaitannya dengan eksplorasi sumber daya mineral", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "mengidentifikasi jenis-jenis energi terbarukan dan potensi pemanfaatannya di daerah rawan bencana", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Menganalisis sifat fisik dan mekanik tanah untuk menentukan kesesuaian lahan dalam perencanaan teknik sipil", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mengidentifikasi dan mengevaluasi pola aliran air permukaan serta dampaknya terhadap perencanaan drainase", "relatedCpmk": "CPMK-5"}], "semester": "2", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan komponen utama geosfer Bumi dan karakteristik masing-masing komponen", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis proses internal Bumi, seperti tektonik lempeng dan vulkanisme, serta dampaknya terhadap permukaan Bumi", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan proses eksternal Bumi, seperti erosi dan sedimentasi, serta peranannya dalam membentuk lanskap", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mengklasifikasikan jenis batuan berdasarkan sifat fisik seperti warna, tekstur, dan kepadatan", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi dan menjelaskan proses pembentukan mineral melalui pengamatan mikroskopis", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Menganalisis sampel tanah berdasarkan komposisi dan struktur lapisan tanah", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Menganalisis faktor-faktor yang mempengaruhi proses vulkanisme dan dampaknya terhadap lingkungan sekitar.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Menjelaskan mekanisme tektonik dan hubungannya dengan pembentukan bentuk lahan serta implikasinya terhadap risiko bencana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mengidentifikasi jenis-jenis pelapukan dan erosi serta dampaknya terhadap kualitas tanah dan penggunaan lahan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "menganalisis siklus hidrologi dan pengaruhnya terhadap ketersediaan sumber daya air", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "menjelaskan proses pembentukan mineral dan kaitannya dengan eksplorasi sumber daya mineral", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "mengidentifikasi jenis-jenis energi terbarukan dan potensi pemanfaatannya di daerah rawan bencana", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Menganalisis sifat fisik dan mekanik tanah untuk menentukan kesesuaian lahan dalam perencanaan teknik sipil", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mengidentifikasi dan mengevaluasi pola aliran air permukaan serta dampaknya terhadap perencanaan drainase", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Sains Kebumian (Hidrologi I) bertujuan untuk memberikan pemahaman mendalam mengenai siklus hidrologi, distribusi air, serta interaksi antara atmosfer, daratan, dan tubuh air. Materi yang dibahas mencakup konsep dasar hidrologi, pengukuran dan analisis data hidrologi, serta dampak perubahan iklim terhadap sumber daya air. Melalui pendekatan teoritis dan praktis, mahasiswa akan diajarkan untuk menerapkan metode ilmiah dalam studi hidrologi, yang berperan penting dalam pengelolaan sumber daya air, mitigasi bencana, dan perencanaan pembangunan berkelanjutan. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan analitis dan kritis yang diperlukan untuk menghadapi tantangan terkait pengelolaan air di era modern.", "referensi": ["M. A. J. Huinink (2022). Hydrology: An Introduction. Springer.", "W. A. P. A. Stauffer (2021). Fundamentals of Hydrology. Wiley.", "D. R. K. J. L. B. K. P. J. M. A. B. B. L. B. G. T. R. T. F. O. C. R. K. J. (2023). Introduction to Water Resources: Management and Strategies. Elsevier.", "V. P. Singh (2020). Applied Hydrology. McGraw-Hill.", "A. S. D. K. M. S. M. R. Y. (2024). Hydrology and Water Resources Management. Springer.", "K. A. M. S. J. R. M. G. K. (2021). Impacts of Climate Change on Hydrological Processes. Journal of Hydrology.", "L. R. C. P. M. S. Y. G. (2023). Hydrological Response to Climate Variability in Tropical Regions. Water Resources Research.", "S. T. J. W. A. R. E. L. (2022). Assessing the Impact of Land Use Changes on Hydrology. Hydrological Sciences Journal.", "M. Z. R. T. A. S. (2023). Geosystem Dynamics: Interactions Between Geology and Hydrology. Geophysical Research Letters."], "bahanKajian": ["Topik 1: Konsep Dasar Sistem Bumi - Memahami geosfer, atmosfer, hidrosfer, dan biosfer serta interaksi di antara mereka, serta proses internal dan eksternal Bumi yang mempengaruhi fenomena alam.", "Topik 2: Jenis Batuan dan Mineral - Identifikasi dan karakteristik fisik berbagai jenis batuan (magmatik, sedimen, metamorf) dan mineral serta proses pembentukannya melalui pengamatan dan literatur.", "Topik 3: Proses Geologi dan Bentuk Lahan - Analisis proses geologi seperti vulkanisme, tektonik, pelapukan, erosi, dan sedimentasi serta deskripsi bentuk lahan (geomorfologi) dan dampaknya terhadap lingkungan.", "Topik 4: Keterkaitan Proses Kebumian dan Sumber Daya Alam - Menjelaskan hubungan antara proses kebumian dengan sumber daya alam seperti air, mineral, dan energi, serta potensi kebencanaan geologi dan langkah mitigasinya.", "Topik 5: Teknik Analisis Sains Kebumian - Penerapan konsep sains kebumian dalam perencanaan teknik, termasuk analisis kondisi tanah, tata air, kestabilan lereng, dan evaluasi lingkungan.", "Topik 6: Siklus Hidrologi - Memahami siklus hidrologi, peran air dalam sistem Bumi, dan implikasinya terhadap sumber daya air dan bencana seperti banjir.", "Topik 7: Dampak Perubahan Iklim terhadap Kebumian - Analisis bagaimana perubahan iklim mempengaruhi proses geologi dan kebumian serta strategi mitigasi yang dapat diterapkan.", "Topik 8: Teknik Pemantauan dan Pengelolaan Sumber Daya Alam - Metode dan teknologi dalam pemantauan sumber daya alam dan manajemen risiko bencana geologi."], "description": "Mata kuliah Sains Kebumian (Hidrologi I) bertujuan untuk memberikan pemahaman mendalam mengenai siklus hidrologi, distribusi air, serta interaksi antara atmosfer, daratan, dan tubuh air. Materi yang dibahas mencakup konsep dasar hidrologi, pengukuran dan analisis data hidrologi, serta dampak perubahan iklim terhadap sumber daya air. Melalui pendekatan teoritis dan praktis, mahasiswa akan diajarkan untuk menerapkan metode ilmiah dalam studi hidrologi, yang berperan penting dalam pengelolaan sumber daya air, mitigasi bencana, dan perencanaan pembangunan berkelanjutan. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan analitis dan kritis yang diperlukan untuk menghadapi tantangan terkait pengelolaan air di era modern.", "bahan_kajian": ["Topik 1: Konsep Dasar Sistem Bumi - Memahami geosfer, atmosfer, hidrosfer, dan biosfer serta interaksi di antara mereka, serta proses internal dan eksternal Bumi yang mempengaruhi fenomena alam.", "Topik 2: Jenis Batuan dan Mineral - Identifikasi dan karakteristik fisik berbagai jenis batuan (magmatik, sedimen, metamorf) dan mineral serta proses pembentukannya melalui pengamatan dan literatur.", "Topik 3: Proses Geologi dan Bentuk Lahan - Analisis proses geologi seperti vulkanisme, tektonik, pelapukan, erosi, dan sedimentasi serta deskripsi bentuk lahan (geomorfologi) dan dampaknya terhadap lingkungan.", "Topik 4: Keterkaitan Proses Kebumian dan Sumber Daya Alam - Menjelaskan hubungan antara proses kebumian dengan sumber daya alam seperti air, mineral, dan energi, serta potensi kebencanaan geologi dan langkah mitigasinya.", "Topik 5: Teknik Analisis Sains Kebumian - Penerapan konsep sains kebumian dalam perencanaan teknik, termasuk analisis kondisi tanah, tata air, kestabilan lereng, dan evaluasi lingkungan.", "Topik 6: Siklus Hidrologi - Memahami siklus hidrologi, peran air dalam sistem Bumi, dan implikasinya terhadap sumber daya air dan bencana seperti banjir.", "Topik 7: Dampak Perubahan Iklim terhadap Kebumian - Analisis bagaimana perubahan iklim mempengaruhi proses geologi dan kebumian serta strategi mitigasi yang dapat diterapkan.", "Topik 8: Teknik Pemantauan dan Pengelolaan Sumber Daya Alam - Metode dan teknologi dalam pemantauan sumber daya alam dan manajemen risiko bencana geologi."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugas