d1c16117-0101-4e4d-bfdf-002fc6f9bb37	\N	112a8048-59f8-40b8-a550-62f16534f7c6	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas prinsip, teknologi, dan standar komunikasi nirkabel yang digunakan dalam sistem telekomunikasi modern.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan konsep dasar komunikasi nirkabel, karakteristik kanal radio, standar teknologi nirkabel, serta teknik modulasi dan multiple access.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis model kanal nirkabel, termasuk path loss, multipath, dan fading, serta mengevaluasi performa sistem berdasarkan parameter kualitas sinyal.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu merancang link komunikasi nirkabel sederhana hingga menengah, termasuk pemilihan modulasi, perhitungan daya pancar, jangkauan, dan kapasitas kanal.", "selected_cpls": ["CPL-01", "CPL-02", "CPL-04", "CPL-05"]}, {"code": "CPMK-5", "description": "Mampu melakukan pengukuran, simulasi, dan evaluasi performa sinyal nirkabel menggunakan alat ukur dan perangkat lunak yang relevan.", "selected_cpls": ["CPL-01", "CPL-03", "CPL-05"]}], "course": {"id": "112a8048-59f8-40b8-a550-62f16534f7c6", "code": "CW62020135004T", "title": "Komunikasi Nirkabel", "credits": 3, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan prinsip dasar modulasi dan demodulasi dalam komunikasi nirkabel.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menganalisis berbagai teknologi komunikasi nirkabel seperti LTE, 5G, dan Wi-Fi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menerapkan standar internasional dalam perancangan sistem komunikasi nirkabel.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan perbedaan antara komunikasi nirkabel analog dan digital", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan mendeskripsikan karakteristik utama kanal radio seperti frekuensi, bandwidth, dan interferensi", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu membandingkan berbagai standar teknologi nirkabel seperti Wi-Fi, Bluetooth, dan LTE", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan konsep dan faktor-faktor yang mempengaruhi path loss dalam model kanal nirkabel.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis dampak multipath terhadap kualitas sinyal dalam komunikasi nirkabel.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu mendemonstrasikan berbagai teknik untuk mengatasi fading pada sistem komunikasi nirkabel.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan berbagai jenis modulasi yang digunakan dalam komunikasi nirkabel dan pemilihannya berdasarkan karakteristik sinyal dan lingkungan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu melakukan perhitungan daya pancar yang diperlukan untuk mencapai jangkauan tertentu dalam komunikasi nirkabel.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menghitung jangkauan maksimum dari sistem komunikasi nirkabel berdasarkan parameter lingkungan dan spesifikasi teknis.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Menggunakan alat ukur untuk melakukan pengukuran kekuatan sinyal nirkabel pada berbagai frekuensi.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Melakukan simulasi propagasi sinyal nirkabel menggunakan 