0cbd9089-6e9f-4d67-99c5-956ed8197dda	\N	6f30de8b-a1ce-4124-8918-e0bd91cb4ee9	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas konsep, teknik, dan algoritma dalam pengolahan citra digital untuk keperluan analisis, peningkatan kualitas, segmentasi, dan ekstraksi fitur.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan konsep dasar citra digital, struktur piksel, teknik peningkatan citra, transformasi, serta algoritma dasar pengolahan citra.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis kualitas citra, karakteristik noise, hasil filtering, dan performa algoritma pengolahan citra berbasis domain spasial maupun frekuensi.", "selected_cpls": ["CPL-01", "CPL-03", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu merancang dan mengimplementasikan algoritma pengolahan citra untuk tugas tertentu seperti segmentasi, deteksi tepi, atau ekstraksi fitur.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-5", "description": "Mampu menguji, mengevaluasi, dan membandingkan kinerja berbagai metode pengolahan citra menggunakan perangkat lunak atau bahasa pemrograman yang relevan.", "selected_cpls": ["CPL-05", "CPL-03", "CPL-04"]}], "course": {"id": "6f30de8b-a1ce-4124-8918-e0bd91cb4ee9", "code": "CW62020135005T", "title": "Pengolahan Citra", "credits": 3, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan dan menerapkan teknik dasar pengolahan citra, seperti konversi warna, pengaturan kontras, dan penajaman citra.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menggunakan algoritma segmentasi citra, seperti thresholding dan region growing, untuk mengidentifikasi objek dalam citra.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menerapkan teknik ekstraksi fitur, seperti deteksi tepi dan analisis tekstur, untuk mengidentifikasi karakteristik penting dalam citra.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menjelaskan struktur piksel dalam citra digital, termasuk warna, intensitas, dan format penyimpanan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menerapkan teknik peningkatan citra seperti kontras, brightness, dan filter untuk meningkatkan kualitas citra.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan menerapkan transformasi geometri pada citra, seperti rotasi, translasi, dan skala.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengukur dan mengevaluasi kualitas citra menggunakan metrik objektif seperti PSNR dan SSIM.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mengklasifikasikan berbagai jenis noise dalam citra, seperti Gaussian, Salt-and-Pepper, dan Poisson.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menerapkan teknik filtering pada citra untuk mengurangi noise dan menganalisis hasilnya menggunakan visualisasi dan metrik evaluasi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan dan menerapkan teknik segmentasi citra menggunakan metode thresholding dan clustering.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu merancang algoritma deteksi tepi menggunakan operator Sobel dan Canny serta mengevaluasi hasilnya.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu melakukan ekstraksi fitur menggunakan metode SIFT atau SURF dan menerapkan pada dataset citra.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menerapkan dan membandingkan setidaknya tiga metode pengolahan citra dasar (seperti penghalusan, deteksi tepi, dan segmentasi) menggunakan perangkat lunak yang relevan.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menguji kinerja algoritma pengolahan citra dengan menggunakan metrik evaluasi seperti PSNR, SSIM, dan waktu komputasi.", "relatedCpmk": "CPMK-5"}], "semester": "5", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan dan menerapkan teknik dasar pengolahan citra, seperti konversi warna, pengaturan kontras, dan penajaman citra.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menggunakan algoritma segmentasi citra, seperti thresholding dan region growing, untuk mengidentifikasi objek dalam citra.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menerapkan teknik ekstraksi fitur, seperti deteksi tepi dan analisis tekstur, untuk mengidentifikasi karakteristik penting dalam citra.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menjelaskan struktur piksel dalam citra digital, termasuk warna, intensitas, dan format penyimpanan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menerapkan teknik peningkatan citra seperti kontras, brightness, dan filter untuk meningkatkan kualitas citra.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan menerapkan transformasi geometri pada citra, seperti rotasi, translasi, dan skala.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengukur dan mengevaluasi kualitas citra menggunakan metrik objektif seperti PSNR dan SSIM.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mengklasifikasikan berbagai jenis noise dalam citra, seperti Gaussian, Salt-and-Pepper, dan Poisson.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menerapkan teknik filtering pada citra untuk mengurangi noise dan menganalisis hasilnya menggunakan visualisasi dan metrik evaluasi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan dan menerapkan teknik segmentasi citra menggunakan metode thresholding dan clustering.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu merancang algoritma deteksi tepi menggunakan operator Sobel dan Canny serta mengevaluasi hasilnya.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu melakukan ekstraksi fitur menggunakan metode SIFT atau SURF dan menerapkan pada dataset citra.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menerapkan dan membandingkan setidaknya tiga metode pengolahan citra dasar (seperti penghalusan, deteksi tepi, dan segmentasi) menggunakan perangkat lunak yang relevan.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menguji kinerja algoritma pengolahan citra dengan menggunakan metrik evaluasi seperti PSNR, SSIM, dan waktu komputasi.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Pengolahan Citra ini bertujuan untuk memberikan pemahaman mendalam mengenai teori dan teknik yang digunakan dalam pengolahan citra digital. Materi yang dibahas meliputi dasar-dasar citra digital, transformasi citra, pemfilteran, segmentasi, dan analisis fitur. Selain itu, mahasiswa akan mempelajari aplikasi pengolahan citra dalam berbagai bidang seperti kedokteran, penginderaan jauh, dan visi komputer. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan praktis dan analitis dalam menangani masalah yang berkaitan dengan pengolahan citra, serta mampu menerapkan algoritma dan teknologi terbaru dalam proyek-proyek riil di industri dan penelitian.", "referensi": ["Rafael C. Gonzalez, Richard E. Woods (2020). Digital Image Processing. Pearson.", "John C. Russ, F. S. M. D. G. H. R. R. S. W. R. C. O. C. (2021). Image Processing: Principles and Applications. CRC Press.", "Richard Szeliski (2021). Computer Vision: Algorithms and Applications. Springer.", "Anil K. Jain (2022). Fundamentals of Digital Image Processing. Prentice Hall.", "B. A. B. Y. T. M. D. V. L. A. L. (2023). Image Processing and Analysis: Variational, PDE, Wavelet, and Stochastic Methods. Wiley.", "A. Sharma, P. Kumar (2021). A Survey on Image Segmentation Techniques. International Journal of Computer Applications.", "M. S. Khan, A. Rahman (2022). Image Filtering and Quality Assessment: A Review. Journal of Imaging.", "L. Zhang, H. Wang (2023). Deep Learning for Image Processing: A Review. IEEE Access.", "C. B. Silva, G. R. de Oliveira (2023). Recent Advances in Image Processing Techniques. Journal of Electronic Imaging.", "N. R. Gomes, P. A. G. da Silva (2023). Real-Time Image Processing for Remote Sensing Applications. Remote Sensing."], "bahanKajian": ["Topik 1: Pengenalan Citra Digital - Menjelaskan konsep dasar citra digital, struktur piksel, dan format citra.", "Topik 2: Teknik Peningkatan Citra - Membahas teknik peningkatan kualitas citra seperti histogram equalization, contrast stretching, dan filtering.", "Topik 3: Transformasi Citra - Mengkaji transformasi citra, termasuk transformasi Fourier, transformasi wavelet, dan aplikasi dalam pengolahan citra.", "Topik 4: Analisis Kualitas Citra - Menganalisis karakteristik noise, kualitas citra, dan metode evaluasi kualitas citra.", "Topik 5: Domain Spasial dan Frekuensi - Memahami algoritma pengolahan citra berbasis domain spasial dan frekuensi, serta perbandingan kinerjanya.", "Topik 6: Segmentasi Citra - Mengimplementasikan teknik segmentasi citra seperti thresholding, region growing, dan clustering.", "Topik 7: Deteksi Fitur dan Tepi - Merancang algoritma untuk deteksi tepi menggunakan metode seperti Canny, Sobel, dan Laplacian.", "Topik 8: Evaluasi dan Perbandingan Metode - Menguji dan membandingkan kinerja berbagai metode pengolahan citra menggunakan perangkat lunak atau bahasa pemrograman yang relevan."], "description": "Mata kuliah Pengolahan Citra ini bertujuan untuk memberikan pemahaman mendalam mengenai teori dan teknik yang digunakan dalam pengolahan citra digital. Materi yang dibahas meliputi dasar-dasar citra digital, transformasi citra, pemfilteran, segmentasi, dan analisis fitur. Selain itu, mahasiswa akan mempelajari aplikasi pengolahan citra dalam berbagai bidang seperti kedokteran, penginderaan jauh, dan visi komputer. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan praktis dan analitis dalam menangani masalah yang berkaitan dengan pengolahan citra, serta mampu menerapkan algoritma dan teknologi terbaru dalam proyek-proyek riil di industri dan penelitian.", "bahan_kajian": ["Topik 1: Pengenalan Citra Digital - Menjelaskan konsep dasar citra digital, struktur piksel, dan format citra.", "Topik 2: Teknik Peningkatan Citra - Membahas teknik peningkatan kualitas citra seperti histogram equalization, contrast stretching, dan filtering.", "Topik 3: Transformasi Citra - Mengkaji transformasi citra, termasuk transformasi Fourier, transformasi wavelet, dan aplikasi dalam pengolahan citra.", "Topik 4: Analisis Kualitas Citra - Menganalisis karakteristik noise, kualitas citra, dan metode evaluasi kualitas citra.", "Topik 5: Domain Spasial dan Frekuensi - Memahami algoritma pengolahan citra berbasis domain spasial dan frekuensi, serta perbandingan kinerjanya.", "Topik 6: Segmentasi Citra - Mengimplementasikan teknik segmentasi citra seperti thresholding, region growing, dan clustering.", "Topik 7: Deteksi Fitur dan Tepi - Merancang algoritma untuk deteksi tepi menggunakan metode seperti Canny, Sobel, dan Laplacian.", "Topik 8: Evaluasi dan Perbandingan Metode - Menguji dan membandingkan kinerja berbagai metode pengolahan citra menggunakan perangkat lunak atau bahasa pemrograman yang relevan."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjuk