77eb1e5c-6003-425c-ac81-08203ef51ad0	\N	22ad5505-8d37-40e9-ab1a-08f0dfa80e59	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini mempelajari konsep, rancangan, dan implementasi sistem kontrol yang menggunakan perangkat elektronika analog maupun digital.", "selected_cpls": ["CPL-01", "CPL-02", "CPL-05"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar dan komponen utama dalam sistem kontrol berbasis elektronika.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis dinamika, karakteristik, dan respons sistem kontrol menggunakan pendekatan analog dan digital (op-amp, PWM, mikrokontroler).", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-4", "description": "Mampu mengimplementasikan sistem kontrol berbasis elektronika (sensor, penguat, pengendali, aktuator) untuk aplikasi tertentu.", "selected_cpls": ["CPL-01", "CPL-05", "CPL-02"]}, {"code": "CPMK-5", "description": "Mampu menguji dan mengevaluasi performa sistem kontrol berdasarkan stabilitas, akurasi, kecepatan respon, dan keandalan.", "selected_cpls": ["CPL-04", "CPL-03"]}], "course": {"id": "22ad5505-8d37-40e9-ab1a-08f0dfa80e59", "code": "CW62020136011EK", "title": "Sistem Kontrol Elektronika", "credits": 3, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip dasar dan teori sistem kontrol, termasuk berbagai jenis umpan balik dan stabilitas sistem.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu merancang dan menggambar skema rangkaian elektronik untuk sistem kontrol menggunakan perangkat analog.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu mengimplementasikan dan menguji sistem kontrol berbasis mikrocontroller untuk aplikasi nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menjelaskan komponen utama dalam sistem kontrol berbasis elektronika, seperti sensor, aktuator, dan pengendali.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis prinsip kerja dari sensor dan aktuator yang digunakan dalam sistem kontrol elektronik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan menggambarkan diagram blok sistem kontrol elektronik beserta fungsinya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan prinsip kerja dan karakteristik komponen op-amp dalam aplikasi sistem kontrol.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu merancang dan mengimplementasikan sirkuit kontrol menggunakan PWM untuk aplikasi pengendalian motor.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis dan mengoptimalkan respons sistem kontrol digital menggunakan mikrokontroler dalam pengendalian proses.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu merancang dan memilih sensor yang tepat untuk aplikasi kontrol tertentu.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan rangkaian penguat untuk sinyal dari sensor.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu merancang dan mengimplementasikan algoritma pengendali untuk sistem kontrol.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menganalisis kriteria stabilitas sistem kontrol menggunakan metode Routh-Hurwitz dan Nyquist.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu melakukan simulasi untuk mengukur akurasi sistem kontrol terhadap input yang diberikan.", "relatedCpmk": "CPMK-5"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip dasar dan teori sistem kontrol, termasuk berbagai jenis umpan balik dan stabilitas sistem.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu merancang dan menggambar skema rangkaian elektronik untuk sistem kontrol menggunakan perangkat analog.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu mengimplementasikan dan menguji sistem kontrol berbasis mikrocontroller untuk aplikasi nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menjelaskan komponen utama dalam sistem kontrol berbasis elektronika, seperti sensor, aktuator, dan pengendali.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis prinsip kerja dari sensor dan aktuator yang digunakan dalam sistem kontrol elektronik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan menggambarkan diagram blok sistem kontrol elektronik beserta fungsinya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan prinsip kerja dan karakteristik komponen op-amp dalam aplikasi sistem kontrol.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu merancang dan mengimplementasikan sirkuit kontrol menggunakan PWM untuk aplikasi pengendalian motor.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis dan mengoptimalkan respons sistem kontrol digital menggunakan mikrokontroler dalam pengendalian proses.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu merancang dan memilih sensor yang tepat untuk aplikasi kontrol tertentu.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan rangkaian penguat untuk sinyal dari sensor.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu merancang dan mengimplementasikan algoritma pengendali untuk sistem kontrol.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menganalisis kriteria stabilitas sistem kontrol menggunakan metode Routh-Hurwitz dan Nyquist.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu melakukan simulasi untuk mengukur akurasi sistem kontrol terhadap input yang diberikan.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Sistem Kontrol Elektronika bertujuan untuk memberikan pemahaman mendalam mengenai prinsip dasar dan aplikasi sistem kontrol dalam konteks elektronika. Materi yang diajarkan mencakup teori kontrol linier, analisis sistem dinamik, serta desain dan implementasi pengendali menggunakan komponen elektronik. Selain itu, mahasiswa akan mempelajari teknik-teknik pemodelan sistem dan simulasi menggunakan perangkat lunak terkini. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan mampu merancang dan menganalisis sistem kontrol yang efisien serta memahami tantangan yang dihadapi dalam aplikasi nyata, sehingga dapat berkontribusi secara signifikan dalam bidang teknik elektro dan industri terkait.", "referensi": ["Ogata, K. (2022). Modern Control Engineering. Pearson.", "Nise, N. S. (2021). Control Systems Engineering. Wiley.", "Gene F. Franklin, J. Da Powell, A. Emami-Naeini (2020). Feedback Control of Dynamic Systems. Pearson.", "Ogata, K. (2021). Digital Control Systems. Prentice Hall.", "G. F. Franklin, J. D. Powell, A. Emami-Naeini (2023). Control System Design. Prentice Hall.", "Alexander, C. K., & Sadiku, M. N. O. (2020). Fundamentals of Electric Circuits. McGraw-Hill.", "Dorf, R. C., & Bishop, R. H. (2024). Introduction to Control Systems. Wiley.", "Smith, J. A., & Wang, L. (2022). A Survey on Modern Control Techniques for Nonlinear Systems. International Journal of Control.", "Chen, Y., & Liu, X. (2023). Modeling and Control of Dynamic Systems: A Control Theory Approach. Journal of Control Science and Engineering.", "Kumar, R., & Singh, A. (2021). Performance Evaluation of PID Controller for a DC Motor Drive. Journal of Electrical Engineering & Technology."], "bahanKajian": ["Topik 1: Pengenalan Sistem Kontrol - Memahami konsep dasar sistem kontrol, termasuk definisi, tujuan, dan jenis-jenis sistem kontrol (terbuka dan tertutup).", "Topik 2: Komponen Sistem Kontrol - Mempelajari komponen utama dalam sistem kontrol, seperti sensor, penguat, pengendali, dan aktuator serta fungsinya masing-masing.", "Topik 3: Analisis Dinamika Sistem - Menganalisis karakteristik dinamika sistem kontrol dengan menggunakan model matematis, diagram blok, dan metode transformasi Laplace.", "Topik 4: Sistem Kontrol Analog - Menggali lebih dalam tentang sistem kontrol berbasis analog, termasuk penggunaan op-amp dalam pengendalian dan implementasi PID (Proportional-Integral-Derivative).", "Topik 5: Sistem Kontrol Digital - Memahami prinsip dan teknik dalam sistem kontrol digital, termasuk penggunaan mikrokontroler dan algoritma pengendalian berbasis PWM (Pulse Width Modulation).", "Topik 6: Implementasi Sistem Kontrol - Merancang dan mengimplementasikan sistem kontrol berbasis elektronika untuk aplikasi tertentu, dengan fokus pada integrasi sensor dan aktuator.", "Topik 7: Pengujian dan Evaluasi Sistem Kontrol - Metodologi untuk menguji dan mengevaluasi performa sistem kontrol, termasuk aspek stabilitas, akurasi, kecepatan respon, dan keandalan.", "Topik 8: Studi Kasus Aplikasi Sistem Kontrol - Menganalisis studi kasus nyata dari aplikasi sistem kontrol dalam industri, otomasi, dan teknologi terkini untuk memahami tantangan dan solusi yang dihadapi."], "description": "Mata kuliah Sistem Kontrol Elektronika bertujuan untuk memberikan pemahaman mendalam mengenai prinsip dasar dan aplikasi sistem kontrol dalam konteks elektronika. Materi yang diajarkan mencakup teori kontrol linier, analisis sistem dinamik, serta desain dan implementasi pengendali menggunakan komponen elektronik. Selain itu, mahasiswa akan mempelajari teknik-teknik pemodelan sistem dan simulasi menggunakan perangkat lunak terkini. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan mampu merancang dan menganalisis sistem kontrol yang efisien serta memahami tantangan yang dihadapi dalam aplikasi nyata, sehingga dapat berkontribusi secara signifikan dalam bidang teknik elektro dan industri terkait.", "bahan_kajian": ["Topik 1: Pengenalan Sistem Kontrol - Memahami konsep dasar sistem kontrol, termasuk definisi, tujuan, dan jenis-jenis sistem kontrol (terbuka dan tertutup).", "Topik 2: Komponen Sistem Kontrol - Mempelajari komponen utama dalam sistem kontrol, seperti sensor, penguat, pengendali, dan aktuator serta fungsinya masing-masing.", "Topik 3: Analisis Dinamika Sistem - Menganalisis karakteristik dinamika sistem kontrol dengan menggunakan model matematis, diagram blok, dan metode transformasi Laplace.", "Topik 4: Sistem Kontrol Analog - Menggali lebih dalam tentang sistem kontrol berbasis analog, termasuk penggunaan op-amp dalam pengendalian dan implementasi PID (Proportional-Integral-Derivative).", "Topik 5: Sistem Kontrol Digital - Memahami prinsip dan teknik dalam sistem kontrol digital, termasuk penggunaan mikrokontroler dan algoritma pengendalian berbasis PWM (Pulse Width Modulation).", "Topik 6: Implementasi Sistem Kontrol - Merancang dan mengimplementasikan sistem kontrol berbasis elektronika untuk aplikasi tertentu, dengan fokus pada integrasi sensor dan aktuator.", "Topik 7: Pengujian dan Evaluasi Sistem Kontrol - Metodologi untuk menguji dan mengevaluasi performa sistem kontrol, termasuk aspek stabilitas, akurasi, kecepatan respon, dan keandalan.", "Topik 8: Studi Kasus Aplikasi Sistem Kontrol - Menganalisis studi kasus nyata dari aplikasi sistem kontrol dalam industri, otomasi, dan teknologi terkini untuk memahami tantangan dan solusi yang dihadapi."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikator": "", "batasWaktu": "Minggu ke-9", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian"