eed9a807-d30f-4123-b358-3ced5ce7af8b	\N	f6892a03-f894-4e5c-bfa6-c1b1b012e3a5	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas prinsip kerja, karakteristik, dan penerapan sistem komunikasi berbasis serat optik.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar propagasi cahaya di dalam serat optik dan karakteristik material serat optik.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis redaman, dispersi, dan parameter performa pada sistem komunikasi serat optik.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu menjelaskan komponen sistem komunikasi optik seperti sumber cahaya, detektor, dan sambungan optik.", "selected_cpls": ["CPL-01", "CPL-02"]}, {"code": "CPMK-5", "description": "Mampu merancang sistem komunikasi serat optik sederhana berdasarkan spesifikasi teknis yang diberikan.", "selected_cpls": ["CPL-02", "CPL-01", "CPL-04"]}], "course": {"id": "f6892a03-f894-4e5c-bfa6-c1b1b012e3a5", "code": "CW62020126009T", "title": "Komunikasi Serat Optik", "credits": 2, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip dasar transmisi data melalui serat optik dan perbandingannya dengan media komunikasi lain.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu mengidentifikasi dan menjelaskan karakteristik fisik serat optik, termasuk jenis-jenis serat dan aplikasinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu menganalisis dan merancang sistem komunikasi berbasis serat optik untuk aplikasi tertentu.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Menjelaskan hukum Snellius dan aplikasinya dalam propagasi cahaya di serat optik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Menganalisis perbedaan antara serat optik single-mode dan multi-mode serta aplikasinya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi karakteristik material serat optik seperti indeks bias dan kehilangan sinyal.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan konsep redaman dalam komunikasi serat optik dan faktor-faktor yang mempengaruhinya.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menghitung nilai redaman pada serat optik menggunakan data eksperimen.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis efek dispersi modal dan dispersi chromatic pada sistem serat optik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menjelaskan fungsi berbagai jenis sumber cahaya yang digunakan dalam sistem komunikasi optik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menganalisis karakteristik dan kinerja berbagai jenis detektor yang digunakan dalam sistem komunikasi optik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menggambarkan berbagai jenis sambungan optik dan menjelaskan prinsip kerja serta aplikasinya dalam sistem komunikasi optik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi komponen-komponen utama dalam sistem komunikasi serat optik dan fungsinya.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menghitung kebutuhan bandwidth dan daya yang diperlukan untuk sistem komunikasi serat optik sederhana.", "relatedCpmk": "CPMK-5"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip dasar transmisi data melalui serat optik dan perbandingannya dengan media komunikasi lain.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu mengidentifikasi dan menjelaskan karakteristik fisik serat optik, termasuk jenis-jenis serat dan aplikasinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu menganalisis dan merancang sistem komunikasi berbasis serat optik untuk aplikasi tertentu.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Menjelaskan hukum Snellius dan aplikasinya dalam propagasi cahaya di serat optik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Menganalisis perbedaan antara serat optik single-mode dan multi-mode serta aplikasinya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi karakteristik material serat optik seperti indeks bias dan kehilangan sinyal.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan konsep redaman dalam komunikasi serat optik dan faktor-faktor yang mempengaruhinya.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menghitung nilai redaman pada serat optik menggunakan data eksperimen.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis efek dispersi modal dan dispersi chromatic pada sistem serat optik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menjelaskan fungsi berbagai jenis sumber cahaya yang digunakan dalam sistem komunikasi optik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menganalisis karakteristik dan kinerja berbagai jenis detektor yang digunakan dalam sistem komunikasi optik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menggambarkan berbagai jenis sambungan optik dan menjelaskan prinsip kerja serta aplikasinya dalam sistem komunikasi optik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi komponen-komponen utama dalam sistem komunikasi serat optik dan fungsinya.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menghitung kebutuhan bandwidth dan daya yang diperlukan untuk sistem komunikasi serat optik sederhana.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Komunikasi Serat Optik ini bertujuan untuk memberikan pemahaman mendalam mengenai prinsip dasar dan aplikasi teknologi serat optik dalam sistem komunikasi modern. Materi yang dibahas mencakup teori gelombang elektromagnetik, struktur dan jenis serat optik, serta teknik pengiriman dan penerimaan sinyal. Selain itu, mahasiswa akan mempelajari berbagai aplikasi serat optik dalam telekomunikasi, jaringan komputer, dan sistem sensor. Dengan mengikuti mata kuliah ini, diharapkan mahasiswa mampu menganalisis dan merancang sistem komunikasi berbasis serat optik yang efisien, serta memahami tantangan dan perkembangan terbaru dalam bidang ini, sehingga dapat berkontribusi secara signifikan dalam industri teknologi informasi dan komunikasi.", "referensi": ["Gerd Keiser (2023). Fiber Optic Communications. McGraw-Hill Education.", "John M. Senior (2021). Optical Fiber Communications. Pearson.", "B. E. A. Saleh and M. C. Teich (2022). Fundamentals of Photonics. Wiley.", "T. L. Koch, J. A. McMorrow, and G. M. McGowan (2021). Optical Fiber Telecommunications VI. Academic Press.", "C. A. M. Van Deventer (2020). Fiber Optics: Principles and Practices. Springer.", "M. A. Alsharif et al. (2021). A Review of Optical Fiber Communication Systems. Journal of Optical Communications.", "R. S. K. N. S. M. Abidin et al. (2022). Recent Advances in Fiber Optic Sensors. Sensors.", "L. H. Hsiao and F. C. Chang (2023). Design and Optimization of Optical Fiber Communication Systems. IEEE Transactions on Communications.", "S. Shrestha et al. (2023). Dispersion Management in Optical Fiber Communication. Optics Express.", "P. R. M. A. Reshmitha et al. (2023). Trends in Optical Fiber Technology. Journal of Lightwave Technology."], "bahanKajian": ["Topik 1: Prinsip Kerja Serat Optik - Memahami dasar-dasar prinsip propagasi cahaya dalam serat optik, termasuk hukum Snell dan fenomena total internal reflection.", "Topik 2: Karakteristik Material Serat Optik - Menjelaskan berbagai jenis material yang digunakan dalam pembuatan serat optik dan bagaimana material tersebut mempengaruhi performa sistem.", "Topik 3: Redaman dalam Serat Optik - Menganalisis faktor-faktor penyebab redaman dalam serat optik dan dampaknya terhadap kualitas sinyal yang ditransmisikan.", "Topik 4: Dispersi dan Parameter Performa - Mengkaji jenis-jenis dispersi (modal, material, dan wavelength) serta cara-cara untuk mengoptimalkan parameter performa sistem komunikasi serat optik.", "Topik 5: Komponen Sistem Komunikasi Optik - Memahami fungsi dan karakteristik komponen utama dalam sistem komunikasi serat optik, seperti sumber cahaya (laser dan LED), detektor, dan sambungan optik.", "Topik 6: Desain Sistem Komunikasi Serat Optik - Memperkenalkan teknik dan langkah-langkah dalam merancang sistem komunikasi berbasis serat optik sederhana sesuai dengan spesifikasi teknis yang diberikan.", "Topik 7: Aplikasi Sistem Komunikasi Serat Optik - Menjelaskan berbagai aplikasi praktis dari sistem komunikasi serat optik dalam berbagai bidang, seperti telekomunikasi, jaringan data, dan medis.", "Topik 8: Tren dan Inovasi dalam Teknologi Serat Optik - Mengkaji perkembangan terbaru dalam teknologi serat optik, termasuk penelitian terbaru dan inovasi yang dapat mempengaruhi masa depan komunikasi optik."], "description": "Mata kuliah Komunikasi Serat Optik ini bertujuan untuk memberikan pemahaman mendalam mengenai prinsip dasar dan aplikasi teknologi serat optik dalam sistem komunikasi modern. Materi yang dibahas mencakup teori gelombang elektromagnetik, struktur dan jenis serat optik, serta teknik pengiriman dan penerimaan sinyal. Selain itu, mahasiswa akan mempelajari berbagai aplikasi serat optik dalam telekomunikasi, jaringan komputer, dan sistem sensor. Dengan mengikuti mata kuliah ini, diharapkan mahasiswa mampu menganalisis dan merancang sistem komunikasi berbasis serat optik yang efisien, serta memahami tantangan dan perkembangan terbaru dalam bidang ini, sehingga dapat berkontribusi secara signifikan dalam industri teknologi informasi dan komunikasi.", "bahan_kajian": ["Topik 1: Prinsip Kerja Serat Optik - Memahami dasar-dasar prinsip propagasi cahaya dalam serat optik, termasuk hukum Snell dan fenomena total internal reflection.", "Topik 2: Karakteristik Material Serat Optik - Menjelaskan berbagai jenis material yang digunakan dalam pembuatan serat optik dan bagaimana material tersebut mempengaruhi performa sistem.", "Topik 3: Redaman dalam Serat Optik - Menganalisis faktor-faktor penyebab redaman dalam serat optik dan dampaknya terhadap kualitas sinyal yang ditransmisikan.", "Topik 4: Dispersi dan Parameter Performa - Mengkaji jenis-jenis dispersi (modal, material, dan wavelength) serta cara-cara untuk mengoptimalkan parameter performa sistem komunikasi serat optik.", "Topik 5: Komponen Sistem Komunikasi Optik - Memahami fungsi dan karakteristik komponen utama dalam sistem komunikasi serat optik, seperti sumber cahaya (laser dan LED), detektor, dan sambungan optik.", "Topik 6: Desain Sistem Komunikasi Serat Optik - Memperkenalkan teknik dan langkah-langkah dalam merancang sistem komunikasi berbasis serat optik sederhana sesuai dengan spesifikasi teknis yang diberikan.", "Topik 7: Aplikasi Sistem Komunikasi Serat Optik - Menjelaskan berbagai aplikasi praktis dari sistem komunikasi serat optik dalam berbagai bidang, seperti telekomunikasi, jaringan data, dan medis.", "Topik 8: Tren dan Inovasi dalam Teknologi Serat Optik - Mengkaji perkembangan terbaru dalam teknologi serat optik, termasuk penelitian terbaru dan inovasi yang dapat mempengaruhi masa depan komunikasi optik."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikator": "", "batasWa