4fa161fa-d57b-4789-ba24-2dbbd7fbe337	\N	e8f4c69c-dd40-4c21-845a-adffae669646	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas prinsip kerja sistem radar dan sistem navigasi modern untuk aplikasi sipil maupun militer", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar sistem radar dan navigasi serta komponen utamanya.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis hubungan parameter radar (daya pancar, gain antena, jangkauan, SNR) dan performa navigasi.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-03"]}, {"code": "CPMK-4", "description": "Mampu menjelaskan berbagai jenis radar (CW, Pulse, Doppler) dan sistem navigasi (GPS, INS, hybrid) beserta karakteristiknya.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-5", "description": "Mampu merancang sistem radar atau navigasi sederhana berdasarkan kebutuhan aplikasi serta melakukan simulasi/eksperimen dasarnya.", "selected_cpls": ["CPL-01", "CPL-02", "CPL-03", "CPL-04"]}], "course": {"id": "e8f4c69c-dd40-4c21-845a-adffae669646", "code": "CW62020126010T", "title": "Radar dan Navigasi", "credits": 2, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip dasar gelombang elektromagnetik dan bagaimana gelombang tersebut digunakan dalam sistem radar.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Dapat menganalisis berbagai jenis sistem radar dan aplikasinya dalam konteks sipil dan militer.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu mengidentifikasi komponen utama dalam sistem navigasi modern dan menjelaskan fungsinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar gelombang elektromagnetik yang digunakan dalam sistem radar.", "relatedCpmk": "CPMK-2"}, {"c