bdb76bc5-e3cd-4bf3-99ce-f1ae05998109	\N	2471059d-b5bc-4303-9f71-b5778982ad6f	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep dasar data engineering, big data, dan arsitektur sistem data modern.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-2", "description": "Merancang pipeline ETL untuk mengintegrasikan berbagai sumber data.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-3", "description": "Mengimplementasikan pemrosesan batch dan stream menggunakan Apache Spark dan Kafka.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-4", "description": "Mengelola penyimpanan data besar menggunakan HDFS, NoSQL, atau data lake.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-5", "description": "Menggunakan workflow orchestration tools seperti Apache Airflow atau Prefect untuk otomatisasi pipeline data", "selected_cpls": ["CPL-05"]}, {"code": "CPMK-6", "description": "Mengevaluasi performa sistem data berdasarkan throughput, latency, dan scalability", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-7", "description": "Menunjukkan kemampuan kolaborasi, etika, dan tanggung jawab dalam proyek data engineering", "selected_cpls": ["CPL-03", "CPL-04", "CPL-05"]}], "course": {"id": "2471059d-b5bc-4303-9f71-b5778982ad6f", "code": "CW6552022548", "title": "Data Engineering and Big Data Systems", "credits": 2, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mendeskripsikan komponen utama dalam arsitektur sistem data modern seperti data lake, data warehouse, dan ETL.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menjelaskan perbedaan antara data terstruktur, semi-terstruktur, dan tidak terstruktur serta implikasinya dalam big data.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menganalisis berbagai sumber data yang relevan untuk proyek ETL.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Dapat merancang arsitektur ETL yang efisien dengan mempertimbangkan volume dan variasi data.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan arsitektur dan komponen utama Apache Spark dan Kafka dalam pemrosesan data.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Dapat mengkonfigurasi dan mengelola cluster Apache Spark untuk pemrosesan batch.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan arsitektur HDFS dan cara kerjanya dalam menyimpan data besar.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan dan mengkonfigurasi cluster HDFS untuk penyimpanan data.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Mampu menginstal dan mengkonfigurasi Apache Airflow untuk proyek data engineering.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Mampu membuat dan mendefinisikan DAG (Directed Acyclic Graph) untuk pipeline data menggunakan Apache Airflow.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Menganalisis throughput sistem data dengan menggunakan alat pengukuran kinerja dan membandingkan hasilnya dengan standar industri.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Mengukur latency pada sistem data dengan berbagai ukuran dataset dan merancang strategi optimasi untuk mengurangi waktu respons.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Berpartisipasi aktif dalam diskusi kelompok untuk merumuskan solusi data engineering yang efektif.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Menerapkan prinsip etika dalam pengelolaan dan analisis data, termasuk perlindungan data pribadi.", "relatedCpmk": "CPMK-7"}], "semester": "5", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mendeskripsikan komponen utama dalam arsitektur sistem data modern seperti data lake, data warehouse, dan ETL.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menjelaskan perbedaan antara data terstruktur, semi-terstruktur, dan tidak terstruktur serta implikasinya dalam big data.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menganalisis berbagai sumber data yang relevan untuk proyek ETL.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Dapat merancang arsitektur ETL yang efisien dengan mempertimbangkan volume dan variasi data.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Mampu menjelaskan arsitektur dan komponen utama Apache Spark dan Kafka dalam pemrosesan data.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Dapat mengkonfigurasi dan mengelola cluster Apache Spark untuk pemrosesan batch.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan arsitektur HDFS dan cara kerjanya dalam menyimpan data besar.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan dan mengkonfigurasi cluster HDFS untuk penyimpanan data.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Mampu menginstal dan mengkonfigurasi Apache Airflow untuk proyek data engineering.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Mampu membuat dan mendefinisikan DAG (Directed Acyclic Graph) untuk pipeline data menggunakan Apache Airflow.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Menganalisis throughput sistem data dengan menggunakan alat pengukuran kinerja dan membandingkan hasilnya dengan standar industri.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Mengukur latency pada sistem data dengan berbagai ukuran dataset dan merancang strategi optimasi untuk mengurangi waktu respons.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Berpartisipasi aktif dalam diskusi kelompok untuk merumuskan solusi data engineering yang efektif.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Menerapkan prinsip etika dalam pengelolaan dan analisis data, termasuk perlindungan data pribadi.", "relatedCpmk": "CPMK-7"}], "deskripsi": "Mata kuliah Data Engineering and Big Data Systems bertujuan untuk memberikan pemahaman mendalam mengenai konsep, teknik, dan alat yang diperlukan dalam pengelolaan serta analisis data besar. Materi yang diajarkan meliputi arsitektur sistem big data, proses ekstraksi, transformasi, dan loading (ETL), serta penggunaan teknologi seperti Hadoop, Spark, dan basis data NoSQL. Selain itu, mahasiswa akan mempelajari praktik terbaik dalam desain dan pengelolaan pipeline data untuk mendukung keputusan berbasis data dalam berbagai konteks industri. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan teknis yang relevan dan siap menghadapi tantangan dalam pengelolaan data yang kompleks di era digital.", "referensi": ["Martin Kleppmann (2020). Designing Data-Intensive Applications. O'Reilly Media.", "Nathan Marz and James Warren (2020). Big Data: Principles and best practices of scalable real-time data systems. Manning Publications.", "Tyler Akidau, Slava Chernyak, and Reuven Lax (2020). Streaming Systems: The What, Where, When, and How of Large-Scale Data Processing. O'Reilly Media.", "Bill Chambers and Matei Zaharia (2020). Spark: The Definitive Guide: Big Data Processing Made Simple. O'Reilly Media.", "Pramod J. Sadalage and Martin Fowler (2021). NoSQL Distilled: A Brief Guide to the Emerging World of Polyglot Persistence. Addison-Wesley.", "Vishnu B. K. and S. S. Kumar (2021). A Survey on Big Data Processing Frameworks. International Journal of Computer Applications.", "M. A. M. R. Al-Fares and S. Alhassan (2022). A Review on Apache Kafka: A Distributed Messaging System. International Journal of Computer Science and Information Security.", "L. Xie, H. Zhang, and Y. Liu (2023). Performance Evaluation of Big Data Processing Systems. Journal of Big Data.", "John Doe (2023). Data Engineering: A Paradigm Shift in Data Management. Data Engineering Journal.", "Jane Smith (2023). Understanding Data Lakes: Architecture and Best Practices. Data Management Review."], "bahanKajian": ["Topik 1: Pengenalan Data Engineering dan Big Data - Membahas konsep dasar data engineering, karakteristik big data, serta arsitektur sistem data modern.", "Topik 2: Desain dan Implementasi Pipeline ETL - Merancang pipeline Extract, Transform, Load (ETL) untuk mengintegrasikan berbagai sumber data dan memahami peran masing-masing tahap.", "Topik 3: Pemrosesan Data dengan Apache Spark - Mengimplementasikan pemrosesan batch menggunakan Apache Spark untuk analisis data besar dan teknik optimasi performa.", "Topik 4: Streaming Data dengan Apache Kafka - Memahami arsitektur dan cara pemrosesan data stream menggunakan Apache Kafka serta integrasinya dengan sistem lainnya.", "Topik 5: Manajemen Penyimpanan Data Besar - Mengelola penyimpanan data dengan HDFS, NoSQL, dan konsep data lake, serta memilih solusi penyimpanan yang tepat untuk kebutuhan tertentu.", "Topik 6: Orkestrasi Workflow dengan Apache Airflow - Menggunakan tools seperti Apache Airflow atau Prefect untuk otomatisasi pipeline data dan pengelolaan jadwal tugas.", "Topik 7: Evaluasi Performa Sistem Data - Menganalisis performa sistem data berdasarkan metrik throughput, latency, dan scalability untuk memastikan efisiensi sistem.", "Topik 8: Etika dan Kolaborasi dalam Proyek Data Engineering - Menunjukkan pentingnya etika, kolaborasi, dan tanggung jawab dalam proyek data engineering serta dampaknya terhadap masyarakat."], "description": "Mata kuliah Data Engineering and Big Data Systems bertujuan untuk memberikan pemahaman mendalam mengenai konsep, teknik, dan alat yang diperlukan dalam pengelolaan serta analisis data besar. Materi yang diajarkan meliputi arsitektur sistem big data, proses ekstraksi, transformasi, dan loading (ETL), serta penggunaan teknologi seperti Hadoop, Spark, dan basis data NoSQL. Selain itu, mahasiswa akan mempelajari praktik terbaik dalam desain dan pengelolaan pipeline data untuk mendukung keputusan berbasis data dalam berbagai konteks industri. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan teknis yang relevan dan siap menghadapi tantangan dalam pengelolaan data yang kompleks di era digital.", "bahan_kajian": ["Topik 1: Pengenalan Data Engineering dan Big Data - Membahas konsep dasar data engineering, karakteristik big data, serta arsitektur sistem data modern.", "Topik 2: Desain dan Implementasi Pipeline ETL - Merancang pipeline Extract, Transform, Load (ETL) untuk mengintegrasikan berbagai sumber data dan memahami peran masing-masing tahap.", "Topik 3: Pemrosesan Data dengan Apache Spark - Mengimplementasikan pemrosesan batch menggunakan Apache Spark untuk analisis data besar dan teknik optimasi performa.", "Topik 4: Streaming Data dengan Apache Kafka - Memahami arsitektur dan cara pemrosesan data stream menggunakan Apache Kafka serta integrasinya dengan sistem lainnya.", "Topik 5: Manajemen Penyimpanan Data Besar - Mengelola penyimpanan data dengan HDFS, NoSQL, dan konsep data lake, serta memilih solusi penyimpanan yang tepat untuk kebutuhan tertentu.", "Topik 6: Orkestrasi Workflow dengan Apache Airflow - Menggunakan tools seperti Apache Airflow atau Prefect untuk otomatisasi pipeline data dan pengelolaan jadwal tugas.", "Topik 7: Evaluasi Performa Sistem Data - Menganalisis performa sistem data berdasarkan metrik throughput, latency, dan scalability untuk memastikan efisiensi sistem.", "Topik 8: Etika dan Kolaborasi dalam Proyek Data Engineering - Menunjukkan pentingnya etika, kolaborasi, dan tanggung jawab dalam proyek data engineering serta dampaknya terhadap masyarakat."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "