bfd83715-d0ef-421f-bddb-e189a79146f7	\N	50ebe22a-c2b9-4284-8cf9-161941c572a5	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep dasar matematika yang relevan untuk AI: aljabar linear, kalkulus, dan probabilitas.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-2", "description": "Menggunakan aljabar linear untuk representasi dan manipulasi data (vektor, matriks, transformasi).", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-3", "description": "Menerapkan kalkulus diferensial dan integral untuk memahami optimisasi model AI.", "selected_cpls": ["CPL-01"]}, {"code": "CPMK-4", "description": "Menggunakan konsep probabilitas dan statistik dalam inferensi dan pembelajaran mesin.", "selected_cpls": ["CPL-05"]}, {"code": "CPMK-5", "description": "Mengimplementasikan algoritma matematis dasar AI menggunakan bahasa pemrograman Python.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-6", "description": "Mengevaluasi hubungan antara teori matematis dan performa model AI.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-7", "description": "Menunjukkan kemampuan berpikir logis, kolaboratif, dan etis dalam analisis masalah berbasis matematika", "selected_cpls": ["CPL-03", "CPL-04", "CPL-05"]}], "course": {"id": "50ebe22a-c2b9-4284-8cf9-161941c572a5", "code": "CW6552022550", "title": "Mathematics for AI", "credits": 2, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan dan menerapkan konsep dasar aljabar linear, termasuk vektor, matriks, dan transformasi linier dalam konteks AI.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu memahami dan menerapkan prinsip-prinsip kalkulus, termasuk diferensiasi dan integrasi, untuk mengoptimalkan fungsi dalam algoritma AI.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan konsep dasar vektor dan operasi dasar seperti penjumlahan, pengurangan, dan perkalian skalar.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Dapat melakukan operasi matriks seperti penjumlahan, perkalian, dan invers matriks serta memahami aplikasinya dalam data.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Menghitung turunan fungsi untuk menentukan titik maksimum dan minimum pada model AI.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Menggunakan integral untuk menghitung area di bawah kurva yang merepresentasikan akurasi model AI.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Mampu menghitung dan menerapkan probabilitas dasar dalam konteks model pembelajaran mesin.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Dapat menggunakan distribusi statistik untuk analisis data dan pengambilan keputusan dalam model AI.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Mampu menjelaskan dan menerapkan konsep dasar algoritma pencarian seperti pencarian biner dan pencarian linear dalam Python.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Dapat mengimplementasikan algoritma optimasi dasar seperti algoritma gradient descent dalam menyelesaikan masalah fungsi matematis dengan Python.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Menganalisis peran teori probabilitas dalam pengembangan algoritma pembelajaran mesin.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Mengevaluasi efektivitas model regresi linier dalam memprediksi data berbasis pada prinsip-prinsip kalkulus.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu menyelesaikan masalah matematis sederhana dengan menerapkan prinsip logika dan algoritma dasar.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Bisa berkolaborasi dalam kelompok untuk menganalisis data matematis dan menyusun solusi berbasis bukti.", "relatedCpmk": "CPMK-7"}], "semester": "5", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan dan menerapkan konsep dasar aljabar linear, termasuk vektor, matriks, dan transformasi linier dalam konteks AI.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu memahami dan menerapkan prinsip-prinsip kalkulus, termasuk diferensiasi dan integrasi, untuk mengoptimalkan fungsi dalam algoritma AI.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan konsep dasar vektor dan operasi dasar seperti penjumlahan, pengurangan, dan perkalian skalar.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Dapat melakukan operasi matriks seperti penjumlahan, perkalian, dan invers matriks serta memahami aplikasinya dalam data.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Menghitung turunan fungsi untuk menentukan titik maksimum dan minimum pada model AI.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Menggunakan integral untuk menghitung area di bawah kurva yang merepresentasikan akurasi model AI.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Mampu menghitung dan menerapkan probabilitas dasar dalam konteks model pembelajaran mesin.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Dapat menggunakan distribusi statistik untuk analisis data dan pengambilan keputusan dalam model AI.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Mampu menjelaskan dan menerapkan konsep dasar algoritma pencarian seperti pencarian biner dan pencarian linear dalam Python.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Dapat mengimplementasikan algoritma optimasi dasar seperti algoritma gradient descent dalam menyelesaikan masalah fungsi matematis dengan Python.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Menganalisis peran teori probabilitas dalam pengembangan algoritma pembelajaran mesin.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Mengevaluasi efektivitas model regresi linier dalam memprediksi data berbasis pada prinsip-prinsip kalkulus.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu menyelesaikan masalah matematis sederhana dengan menerapkan prinsip logika dan algoritma dasar.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Bisa berkolaborasi dalam kelompok untuk menganalisis data matematis dan menyusun solusi berbasis bukti.", "relatedCpmk": "CPMK-7"}], "deskripsi": "Mata kuliah 'Mathematics for AI' bertujuan untuk memberikan pemahaman mendalam tentang konsep-konsep matematika yang fundamental dalam pengembangan dan penerapan kecerdasan buatan. Materi yang akan dibahas mencakup aljabar linear, kalkulus, probabilitas, dan statistik, serta teknik-teknik optimasi yang relevan dengan algoritma machine learning. Dengan mengintegrasikan teori dan praktik, mahasiswa diharapkan dapat mengaplikasikan pengetahuan matematika untuk memecahkan masalah kompleks dalam bidang AI. Manfaat dari mata kuliah ini adalah peningkatan kemampuan analitis dan pemecahan masalah, yang sangat penting dalam merancang dan mengimplementasikan solusi berbasis AI yang efektif dan efisien.", "referensi": ["Marc Peter Deisenroth, A. Aldo Faisal, Cheng Soon Ong (2020). Mathematics for Machine Learning. Cambridge University Press.", "David C. Lay (2021). Linear Algebra and Its Applications. Pearson.", "James Stewart (2020). Calculus: Early Transcendentals. Cengage Learning.", "Jay L. Devore (2021). Probability and Statistics for Engineering and Science. Cengage Learning.", "Christopher M. Bishop (2021). Pattern Recognition and Machine Learning. Springer.", "D. P. Bertsekas, J. N. Tsitsiklis (2020). Introduction to Probability. Athena Scientific.", "A. Kumar, R. Sharma (2022). A Survey on Optimization Techniques in Machine Learning. International Journal of Computer Applications.", "Y. Wang, Z. Liu (2021). Statistical Learning: A Data Mining Approach. Journal of Statistical Computation and Simulation.", "M. S. M. Mahmoud, F. B. H. Al-Masri (2023). Ethics in Artificial Intelligence: A Systematic Literature Review. AI & Society.", "N. S. D. Alavi, A. H. A. M. Y. Z. Moradi (2023). Optimization Methods in Machine Learning. Journal of Machine Learning Research."], "bahanKajian": ["Topik 1: Aljabar Linear - Memahami konsep dasar aljabar linear, termasuk vektor, matriks, dan operasi dasar yang diperlukan untuk manipulasi data dalam AI.", "Topik 2: Transformasi Matriks - Menerapkan transformasi matriks dalam konteks AI, termasuk rotasi, skala, dan transformasi linier lainnya.", "Topik 3: Kalkulus Diferensial - Menggunakan kalkulus diferensial untuk memahami gradien, turunan, dan optimisasi dalam model AI.", "Topik 4: Kalkulus Integral - Menerapkan kalkulus integral untuk menghitung area di bawah kurva dan memahami probabilitas distribusi dalam konteks pembelajaran mesin.", "Topik 5: Probabilitas dan Statistik - Memahami konsep dasar probabilitas dan statistik, serta penerapannya dalam inferensi dan pengambilan keputusan di AI.", "Topik 6: Algoritma Optimisasi - Mengimplementasikan algoritma optimisasi seperti Gradient Descent menggunakan Python untuk menyelesaikan masalah dalam model AI.", "Topik 7: Evaluasi Model AI - Mengevaluasi hubungan antara teori matematis dan performa model AI melalui analisis kesalahan dan metrik evaluasi.", "Topik 8: Etika dalam AI - Membangun kemampuan berpikir logis dan kolaboratif dalam konteks etika analisis masalah berbasis matematika dalam pengembangan AI."], "description": "Mata kuliah 'Mathematics for AI' bertujuan untuk memberikan pemahaman mendalam tentang konsep-konsep matematika yang fundamental dalam pengembangan dan penerapan kecerdasan buatan. Materi yang akan dibahas mencakup aljabar linear, kalkulus, probabilitas, dan statistik, serta teknik-teknik optimasi yang relevan dengan algoritma machine learning. Dengan mengintegrasikan teori dan praktik, mahasiswa diharapkan dapat mengaplikasikan pengetahuan matematika untuk memecahkan masalah kompleks dalam bidang AI. Manfaat dari mata kuliah ini adalah peningkatan kemampuan analitis dan pemecahan masalah, yang sangat penting dalam merancang dan mengimplementasikan solusi berbasis AI yang efektif dan efisien.", "bahan_kajian": ["Topik 1: Aljabar Linear - Memahami konsep dasar aljabar linear, termasuk vektor, matriks, dan operasi dasar yang diperlukan untuk manipulasi data dalam AI.", "Topik 2: Transformasi Matriks - Menerapkan transformasi matriks dalam konteks AI, termasuk rotasi, skala, dan transformasi linier lainnya.", "Topik 3: Kalkulus Diferensial - Menggunakan kalkulus diferensial untuk memahami gradien, turunan, dan optimisasi dalam model AI.", "Topik 4: Kalkulus Integral - Menerapkan kalkulus integral untuk menghitung area di bawah kurva dan memahami probabilitas distribusi dalam konteks pembelajaran mesin.", "Topik 5: Probabilitas dan Statistik - Memahami konsep dasar probabilitas dan statistik, serta penerapannya dalam inferensi dan pengambilan keputusan di AI.", "Topik 6: Algoritma Optimisasi - Mengimplementasikan algoritma optimisasi seperti Gradient Descent menggunakan Python untuk menyelesaikan masalah dalam model AI.", "Topik 7: Evaluasi Model AI - Mengevaluasi hubungan antara teori matematis dan performa model AI melalui analisis kesalahan dan metrik evaluasi.", "Topik 8: Etika dalam AI - Membangun kemampuan berpikir logis dan kolaboratif dalam konteks etika analisis masalah berbasis matematika dalam pengembangan AI."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikator": "", "batasWaktu": "Minggu ke-9", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "pet