99b18a2f-81a6-4ee0-90b8-14d16adba0b3	\N	dc45e8be-e7db-43d1-9c19-20b2181fe8e4	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep arsitektur cloud dan prinsip dasar keamanan cloud.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-2", "description": "Mengidentifikasi ancaman dan kerentanan (vulnerability) dalam lingkungan cloud.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-3", "description": "Merancang arsitektur keamanan cloud yang mencakup data, jaringan, dan aplikasi.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-4", "description": "Mengimplementasikan kontrol keamanan seperti IAM dan enkripsi.", "selected_cpls": ["CPL-05", "CPL-04"]}, {"code": "CPMK-5", "description": "Menerapkan kebijakan keamanan, kepatuhan, dan standar cloud (ISO, NIST, CSA).", "selected_cpls": ["CPL-04", "CPL-05"]}, {"code": "CPMK-6", "description": "Melakukan audit dan monitoring keamanan sistem berbasis cloud", "selected_cpls": ["CPL-05", "CPL-04"]}, {"code": "CPMK-7", "description": "Menunjukkan profesionalisme, etika, dan tanggung jawab dalam praktik keamanan cloud.", "selected_cpls": ["CPL-04", "CPL-03"]}], "course": {"id": "dc45e8be-e7db-43d1-9c19-20b2181fe8e4", "code": "CW6552022682", "title": "Cloud Security Architecture", "credits": 2, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi berbagai model layanan cloud (IaaS, PaaS, SaaS) dan karakteristik masing-masing.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menjelaskan komponen utama dalam arsitektur cloud dan bagaimana mereka berinteraksi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Menganalisis dan mendokumentasikan jenis-jenis ancaman yang umum terjadi pada lingkungan cloud.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi dan mengevaluasi kerentanan spesifik yang ada pada layanan cloud yang digunakan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Menganalisis risiko keamanan data di lingkungan cloud dan merancang solusi mitigasi yang sesuai.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Merancang arsitektur jaringan yang aman untuk aplikasi cloud dengan mempertimbangkan segmentasi dan kontrol akses.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Menerapkan kebijakan IAM untuk mengelola akses pengguna dan grup dalam lingkungan cloud.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Melakukan konfigurasi enkripsi data at rest dan in transit menggunakan layanan cloud.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Menganalisis dan mengevaluasi kebijakan keamanan cloud yang sesuai dengan standar ISO 27001", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Mengimplementasikan kontrol keamanan berbasis NIST SP 800-53 dalam arsitektur cloud", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Menganalisis dan mengevaluasi kebijakan keamanan yang diterapkan pada sistem cloud", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Melakukan penilaian risiko terhadap infrastruktur cloud dan layanan yang digunakan", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu menjelaskan prinsip-prinsip etika dalam penggunaan dan pengelolaan layanan cloud.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Dapat mengidentifikasi dan menganalisis risiko keamanan yang terkait dengan praktik cloud dan memberikan rekomendasi mitigasi yang sesuai.", "relatedCpmk": "CPMK-7"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi berbagai model layanan cloud (IaaS, PaaS, SaaS) dan karakteristik masing-masing.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menjelaskan komponen utama dalam arsitektur cloud dan bagaimana mereka berinteraksi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Menganalisis dan mendokumentasikan jenis-jenis ancaman yang umum terjadi pada lingkungan cloud.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi dan mengevaluasi kerentanan spesifik yang ada pada layanan cloud yang digunakan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Menganalisis risiko keamanan data di lingkungan cloud dan merancang solusi mitigasi yang sesuai.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Merancang arsitektur jaringan yang aman untuk aplikasi cloud dengan mempertimbangkan segmentasi dan kontrol akses.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Menerapkan kebijakan IAM untuk mengelola akses pengguna dan grup dalam lingkungan cloud.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Melakukan konfigurasi enkripsi data at rest dan in transit menggunakan layanan cloud.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Menganalisis dan mengevaluasi kebijakan keamanan cloud yang sesuai dengan standar ISO 27001", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Mengimplementasikan kontrol keamanan berbasis NIST SP 800-53 dalam arsitektur cloud", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Menganalisis dan mengevaluasi kebijakan keamanan yang diterapkan pada sistem cloud", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Melakukan penilaian risiko terhadap infrastruktur cloud dan layanan yang digunakan", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu menjelaskan prinsip-prinsip etika dalam penggunaan dan pengelolaan layanan cloud.", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Dapat mengidentifikasi dan menganalisis risiko keamanan yang terkait dengan praktik cloud dan memberikan rekomendasi mitigasi yang sesuai.", "relatedCpmk": "CPMK-7"}], "deskripsi": "Mata kuliah Cloud Security Architecture bertujuan untuk memberikan pemahaman mendalam tentang prinsip-prinsip dan praktik keamanan dalam arsitektur sistem cloud. Materi yang dibahas meliputi model keamanan cloud, identitas dan manajemen akses, enkripsi data, serta pemantauan dan respon terhadap insiden. Mahasiswa akan mempelajari berbagai framework dan standar keamanan yang relevan, serta tantangan dan solusi dalam penerapan keamanan di lingkungan cloud. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan mampu merancang dan mengevaluasi arsitektur keamanan yang efektif, sehingga dapat melindungi data dan aplikasi yang berjalan di platform cloud dari ancaman yang ada. Selain itu, mata kuliah ini juga mempersiapkan mahasiswa untuk menghadapi tuntutan industri terkait keamanan informasi di era digital.", "referensi": ["Samia Bouzefrane, Rachida Bouhaddou (2023). Cloud Security Architecture: Principles and Practice. Springer.", "Michael J. Kavis (2021). Architecting Cloud Computing Solutions. Wiley.", "Ben Potter, Scott Ward (2022). Cloud Security and Compliance: A Practical Guide. O'Reilly Media.", "Raghuram Yeluri, Amandeep Kumar (2020). Cloud Security: A Comprehensive Guide to Secure Cloud Computing. CRC Press.", "Stuart Scott (2023). AWS Certified Security - Specialty Exam Guide. Packt Publishing.", "L. D. P. Santos, R. M. D. Silva (2022). Implementing Cloud Security: A Guide for IT Professionals. Springer.", "S. H. Alhassan, A. A. Al-Otaibi (2021). A Survey of Cloud Security Issues and Challenges. International Journal of Computer Science and Information Security.", "S. J. S. H. Ali, K. S. H. Ali (2022). Security in Cloud Computing: A Survey. Journal of Cloud Computing: Advances, Systems and Applications.", "T. A. Al-Ghadhban, M. M. Ahmed (2023). Cloud Security Compliance: A Review. International Journal of Information Security.", "R. B. K. Mohapatra, M. K. Gupta (2023). Cloud Security: Challenges and Solutions. Journal of Cloud Computing."], "bahanKajian": ["Topik 1: Pengantar Arsitektur Cloud dan Prinsip Dasar Keamanan - Memahami konsep arsitektur cloud, model layanan (IaaS, PaaS, SaaS), dan prinsip dasar keamanan yang diperlukan dalam lingkungan cloud.", "Topik 2: Ancaman dan Kerentanan dalam Lingkungan Cloud - Mengidentifikasi berbagai ancaman dan kerentanan yang dapat mempengaruhi keamanan data dan aplikasi dalam cloud.", "Topik 3: Desain Arsitektur Keamanan Cloud - Merancang arsitektur keamanan yang efektif yang mencakup perlindungan data, keamanan jaringan, dan keamanan aplikasi dalam lingkungan cloud.", "Topik 4: Implementasi Kontrol Keamanan di Cloud - Memahami dan menerapkan kontrol keamanan seperti Identity and Access Management (IAM) serta enkripsi untuk melindungi aset cloud.", "Topik 5: Kebijakan Keamanan dan Kepatuhan dalam Cloud - Mempelajari kebijakan keamanan, kepatuhan, dan standar yang berlaku di cloud seperti ISO, NIST, dan CSA.", "Topik 6: Audit dan Monitoring Keamanan Sistem Cloud - Teknik dan alat yang digunakan untuk melakukan audit dan monitoring terhadap keamanan sistem berbasis cloud.", "Topik 7: Etika dan Profesionalisme dalam Keamanan Cloud - Menunjukkan profesionalisme, etika, dan tanggung jawab dalam praktik keamanan cloud serta pentingnya kesadaran akan isu-isu etis.", "Topik 8: Studi Kasus Keamanan Cloud - Analisis studi kasus nyata terkait insiden keamanan di cloud untuk memahami tantangan dan solusi yang efektif."], "description": "Mata kuliah Cloud Security Architecture bertujuan untuk memberikan pemahaman mendalam tentang prinsip-prinsip dan praktik keamanan dalam arsitektur sistem cloud. Materi yang dibahas meliputi model keamanan cloud, identitas dan manajemen akses, enkripsi data, serta pemantauan dan respon terhadap insiden. Mahasiswa akan mempelajari berbagai framework dan standar keamanan yang relevan, serta tantangan dan solusi dalam penerapan keamanan di lingkungan cloud. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan mampu merancang dan mengevaluasi arsitektur keamanan yang efektif, sehingga dapat melindungi data dan aplikasi yang berjalan di platform cloud dari ancaman yang ada. Selain itu, mata kuliah ini juga mempersiapkan mahasiswa untuk menghadapi tuntutan industri terkait keamanan informasi di era digital.", "bahan_kajian": ["Topik 1: Pengantar Arsitektur Cloud dan Prinsip Dasar Keamanan - Memahami konsep arsitektur cloud, model layanan (IaaS, PaaS, SaaS), dan prinsip dasar keamanan yang diperlukan dalam lingkungan cloud.", "Topik 2: Ancaman dan Kerentanan dalam Lingkungan Cloud - Mengidentifikasi berbagai ancaman dan kerentanan yang dapat mempengaruhi keamanan data dan aplikasi dalam cloud.", "Topik 3: Desain Arsitektur Keamanan Cloud - Merancang arsitektur keamanan yang efektif yang mencakup perlindungan data, keamanan jaringan, dan keamanan aplikasi dalam lingkungan cloud.", "Topik 4: Implementasi Kontrol Keamanan di Cloud - Memahami dan menerapkan kontrol keamanan seperti Identity and Access Management (IAM) serta enkripsi untuk melindungi aset cloud.", "Topik 5: Kebijakan Keamanan dan Kepatuhan dalam Cloud - Mempelajari kebijakan keamanan, kepatuhan, dan standar yang berlaku di cloud seperti ISO, NIST, dan CSA.", "Topik 6: Audit dan Monitoring Keamanan Sistem Cloud - Teknik dan alat yang digunakan untuk melakukan audit dan monitoring terhadap keamanan sistem berbasis cloud.", "Topik 7: Etika dan Profesionalisme dalam Keamanan Cloud - Menunjukkan profesionalisme, etika, dan tanggung jawab dalam praktik keamanan cloud serta pentingnya kesadaran akan isu-isu etis.", "Topik 8: Studi Kasus Keamanan Cloud - Analisis studi kasus nyata terkait insiden keamanan di cloud untuk memahami tantangan dan solusi yang efektif."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indik