6feeddc4-2770-41b4-919d-fdcf8aac301b	\N	28d6d116-26ff-4e07-876f-28272095f51a	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep arsitektur cloud dan prinsip dasar keamanan cloud.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-2", "description": "Mengidentifikasi ancaman dan kerentanan (vulnerability) dalam lingkungan cloud.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-3", "description": "Merancang arsitektur keamanan cloud yang mencakup data, jaringan, dan aplikasi.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-4", "description": "Mengimplementasikan kontrol keamanan seperti IAM dan enkripsi.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-5", "description": "Menerapkan kebijakan keamanan, kepatuhan, dan standar cloud (ISO, NIST, CSA).", "selected_cpls": ["CPL-04", "CPL-05"]}, {"code": "CPMK-6", "description": "Melakukan audit dan monitoring keamanan sistem berbasis cloud", "selected_cpls": ["CPL-05"]}, {"code": "CPMK-7", "description": "Menunjukkan profesionalisme, etika, dan tanggung jawab dalam praktik keamanan cloud.", "selected_cpls": ["CPL-04", "CPL-03"]}], "course": {"id": "28d6d116-26ff-4e07-876f-28272095f51a", "code": "CW6552021683", "title": "Praktikum Cloud Security Architecture", "credits": 1, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan berbagai model layanan cloud (IaaS, PaaS, SaaS) serta penerapannya dalam konteks keamanan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis dan mendeskripsikan risiko keamanan yang terkait dengan arsitektur cloud dan cara mitigasinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan mendokumentasikan jenis ancaman yang umum terjadi dalam lingkungan cloud, seperti serangan DDoS dan phising.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu melakukan analisis risiko untuk menilai dampak dari kerentanan yang ditemukan dalam infrastruktur cloud.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan menganalisis risiko keamanan pada data yang disimpan di cloud.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Merancang dan menerapkan kebijakan keamanan jaringan yang efektif untuk infrastruktur cloud.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Menerapkan kebijakan IAM untuk mengelola akses pengguna pada layanan cloud", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Mengonfigurasi dan mengelola grup pengguna dan peran dalam sistem IAM", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Menganalisis dan mendokumentasikan kebijakan keamanan berbasis ISO untuk infrastruktur cloud.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Mengimplementasikan kontrol akses berdasarkan NIST dalam lingkungan cloud.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Melakukan analisis risiko terhadap layanan cloud yang digunakan dalam organisasi.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Mengidentifikasi dan mengevaluasi kontrol keamanan yang ada pada sistem cloud.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu mengidentifikasi dan menerapkan prinsip-prinsip etika dalam pengelolaan data di lingkungan cloud", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Dapat menganalisis dan menilai risiko keamanan dalam arsitektur cloud dan memberikan rekomendasi mitigasi", "relatedCpmk": "CPMK-7"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan berbagai model layanan cloud (IaaS, PaaS, SaaS) serta penerapannya dalam konteks keamanan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis dan mendeskripsikan risiko keamanan yang terkait dengan arsitektur cloud dan cara mitigasinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan mendokumentasikan jenis ancaman yang umum terjadi dalam lingkungan cloud, seperti serangan DDoS dan phising.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu melakukan analisis risiko untuk menilai dampak dari kerentanan yang ditemukan dalam infrastruktur cloud.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan menganalisis risiko keamanan pada data yang disimpan di cloud.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-3", "description": "Merancang dan menerapkan kebijakan keamanan jaringan yang efektif untuk infrastruktur cloud.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-4", "description": "Menerapkan kebijakan IAM untuk mengelola akses pengguna pada layanan cloud", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-4", "description": "Mengonfigurasi dan mengelola grup pengguna dan peran dalam sistem IAM", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-5", "description": "Menganalisis dan mendokumentasikan kebijakan keamanan berbasis ISO untuk infrastruktur cloud.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-5", "description": "Mengimplementasikan kontrol akses berdasarkan NIST dalam lingkungan cloud.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-6", "description": "Melakukan analisis risiko terhadap layanan cloud yang digunakan dalam organisasi.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-6", "description": "Mengidentifikasi dan mengevaluasi kontrol keamanan yang ada pada sistem cloud.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-7", "description": "Mampu mengidentifikasi dan menerapkan prinsip-prinsip etika dalam pengelolaan data di lingkungan cloud", "relatedCpmk": "CPMK-7"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-7", "description": "Dapat menganalisis dan menilai risiko keamanan dalam arsitektur cloud dan memberikan rekomendasi mitigasi", "relatedCpmk": "CPMK-7"}], "deskripsi": "Mata kuliah Praktikum Cloud Security Architecture bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dan praktik arsitektur keamanan dalam lingkungan cloud. Dalam praktikum ini, mahasiswa akan mempelajari berbagai model keamanan, kontrol akses, serta teknik enkripsi yang diterapkan dalam layanan cloud. Materi yang dibahas meliputi penilaian risiko, kepatuhan regulasi, dan implementasi solusi keamanan yang efektif. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan praktis dalam merancang dan mengevaluasi arsitektur keamanan cloud yang dapat melindungi data dan aplikasi dari ancaman siber, serta menyiapkan mereka untuk menghadapi tantangan keamanan di dunia digital yang terus berkembang.", "referensi": ["Raj, P. (2023). Cloud Security Architecture. Springer.", "M. J. Kavis (2021). Architecting the Cloud: Design Decisions for Cloud Computing Service Models. Wiley.", "Ben Potter, et al. (2022). Cloud Security and Compliance: A Practical Guide. Syngress.", "M. G. Raghavan (2020). Cloud Security: A Comprehensive Guide to Secure Cloud Computing. CRC Press.", "R. Buyya, et al. (2021). Cloud Computing Security Issues and Challenges: A Survey. IEEE Transactions on Services Computing.", "S. R. Das, et al. (2022). A Study on Cloud Security Architecture. Journal of Cloud Computing: Advances, Systems and Applications.", "L. C. Smith (2023). The Role of Compliance in Cloud Security. International Journal of Information Security.", "K. K. Sharma, et al. (2020). Risk Assessment Framework for Cloud Computing. Journal of Cyber Security Technology."], "bahanKajian": ["Topik 1: Pengenalan Arsitektur Cloud dan Prinsip Dasar Keamanan Cloud - Membahas konsep dasar arsitektur cloud, model layanan (IaaS, PaaS, SaaS), serta prinsip-prinsip keamanan yang harus dipahami dalam lingkungan cloud.", "Topik 2: Identifikasi Ancaman dan Kerentanan dalam Lingkungan Cloud - Mengkaji berbagai ancaman dan kerentanan yang mungkin terjadi dalam sistem cloud, serta metode untuk menganalisis dan menilai risiko terkait.", "Topik 3: Merancang Arsitektur Keamanan Cloud - Fokus pada perancangan arsitektur keamanan yang mencakup perlindungan data, jaringan, dan aplikasi, serta teknik untuk mengintegrasikan keamanan ke dalam desain sistem.", "Topik 4: Implementasi Kontrol Keamanan - Mempelajari penerapan kontrol keamanan seperti Identity and Access Management (IAM), enkripsi data, dan teknik keamanan lainnya untuk melindungi sumber daya di cloud.", "Topik 5: Kebijakan Keamanan dan Kepatuhan - Membahas pentingnya kebijakan keamanan, kepatuhan, dan standar yang berlaku dalam cloud computing, seperti ISO, NIST, dan CSA, serta cara menerapkannya.", "Topik 6: Audit dan Monitoring Keamanan Sistem Cloud - Menyelidiki teknik dan alat untuk melakukan audit keamanan dan monitoring sistem berbasis cloud untuk memastikan kepatuhan dan deteksi ancaman.", "Topik 7: Profesionalisme dan Etika dalam Keamanan Cloud - Mengedukasi tentang pentingnya profesionalisme, etika, dan tanggung jawab dalam praktik keamanan cloud, serta implikasinya terhadap industri.", "Topik 8: Studi Kasus Keamanan Cloud - Menganalisis berbagai studi kasus terkait insiden keamanan di lingkungan cloud dan bagaimana solusi yang tepat dapat diterapkan untuk menghindari masalah serupa di masa depan."], "description": "Mata kuliah Praktikum Cloud Security Architecture bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dan praktik arsitektur keamanan dalam lingkungan cloud. Dalam praktikum ini, mahasiswa akan mempelajari berbagai model keamanan, kontrol akses, serta teknik enkripsi yang diterapkan dalam layanan cloud. Materi yang dibahas meliputi penilaian risiko, kepatuhan regulasi, dan implementasi solusi keamanan yang efektif. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan praktis dalam merancang dan mengevaluasi arsitektur keamanan cloud yang dapat melindungi data dan aplikasi dari ancaman siber, serta menyiapkan mereka untuk menghadapi tantangan keamanan di dunia digital yang terus berkembang.", "bahan_kajian": ["Topik 1: Pengenalan Arsitektur Cloud dan Prinsip Dasar Keamanan Cloud - Membahas konsep dasar arsitektur cloud, model layanan (IaaS, PaaS, SaaS), serta prinsip-prinsip keamanan yang harus dipahami dalam lingkungan cloud.", "Topik 2: Identifikasi Ancaman dan Kerentanan dalam Lingkungan Cloud - Mengkaji berbagai ancaman dan kerentanan yang mungkin terjadi dalam sistem cloud, serta metode untuk menganalisis dan menilai risiko terkait.", "Topik 3: Merancang Arsitektur Keamanan Cloud - Fokus pada perancangan arsitektur keamanan yang mencakup perlindungan data, jaringan, dan aplikasi, serta teknik untuk mengintegrasikan keamanan ke dalam desain sistem.", "Topik 4: Implementasi Kontrol Keamanan - Mempelajari penerapan kontrol keamanan seperti Identity and Access Management (IAM), enkripsi data, dan teknik keamanan lainnya untuk melindungi sumber daya di cloud.", "Topik 5: Kebijakan Keamanan dan Kepatuhan - Membahas pentingnya kebijakan keamanan, kepatuhan, dan standar yang berlaku dalam cloud computing, seperti ISO, NIST, dan CSA, serta cara menerapkannya.", "Topik 6: Audit dan Monitoring Keamanan Sistem Cloud - Menyelidiki teknik dan alat untuk melakukan audit keamanan dan monitoring sistem berbasis cloud untuk memastikan kepatuhan dan deteksi ancaman.", "Topik 7: Profesionalisme dan Etika dalam Keamanan Cloud - Mengedukasi tentang pentingnya profesionalisme, etika, dan tanggung jawab dalam praktik keamanan cloud, serta implikasinya terhadap industri.", "Topik 8: Studi Kasus Keamanan Cloud - Menganalisis berbagai studi kasus terkait insiden keamanan di lingkungan cloud dan bagaimana solusi yang tepat dapat diterapkan untuk menghindari masalah serupa di masa depan."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "l