7dfc7826-a99f-4d21-a7a9-be770f00079f	\N	8d28a992-5ce8-45dd-bf7c-4a559a5d10e4	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep dasar digital forensics dan siklus respons insiden.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-2", "description": "Mengidentifikasi sumber bukti digital dari berbagai perangkat dan jaringan", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-3", "description": "Melakukan akuisisi, preservasi, dan analisis bukti digital sesuai prosedur forensik.", "selected_cpls": ["CPL-04", "CPL-05"]}, {"code": "CPMK-4", "description": "Menggunakan perangkat forensik (Autopsy, FTK Imager, Volatility, Wireshark) dalam investigasi.", "selected_cpls": ["CPL-05"]}, {"code": "CPMK-5", "description": "Menyusun laporan investigasi digital dengan menjaga rantai bukti (chain of custody).", "selected_cpls": ["CPL-04", "CPL-03"]}, {"code": "CPMK-6", "description": "Menunjukkan sikap profesional, jujur, dan beretika selama proses investigasi forensik.", "selected_cpls": ["CPL-04"]}], "course": {"id": "8d28a992-5ce8-45dd-bf7c-4a559a5d10e4", "code": "CW6552022684", "title": "Digital Forensics and Incident Response", "credits": 2, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan istilah-istilah kunci dalam digital forensics.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis tahap-tahap dalam siklus respons insiden dengan memberikan contoh nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan metodologi pengumpulan bukti digital dan teknik yang digunakan dalam proses forensik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menjelaskan jenis-jenis perangkat yang dapat menjadi sumber bukti digital, seperti komputer, smartphone, dan perangkat IoT.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis dan mendokumentasikan data yang dapat diperoleh dari jaringan lokal dan jaringan internet sebagai sumber bukti digital.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Dapat menggunakan alat forensik digital untuk mengekstrak bukti dari perangkat penyimpanan eksternal, seperti hard drive dan flash drive.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mengidentifikasi dan mengklasifikasikan jenis bukti digital yang relevan dalam kasus forensik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Melakukan proses akuisisi bukti digital menggunakan alat dan teknik yang sesuai untuk menjaga integritas data.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-4", "description": "Mampu menginstall dan mengkonfigurasi perangkat forensik Autopsy untuk analisis digital.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menggunakan FTK Imager untuk membuat salinan forensik dari media penyimpanan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-5", "description": "Mengidentifikasi dan mendokumentasikan setiap langkah dalam proses pengambilan bukti digital untuk memastikan keaslian data.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-5", "description": "Menyusun dan menyimpan dokumen rantai bukti yang mencakup informasi tentang siapa yang mengakses bukti, kapan, dan untuk tujuan apa.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-6", "description": "Menerapkan prinsip-prinsip etika dalam pengumpulan dan analisis bukti digital.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-6", "description": "Menunjukkan integritas dengan tidak memanipulasi data selama proses investigasi.", "relatedCpmk": "CPMK-6"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan menjelaskan istilah-istilah kunci dalam digital forensics.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menganalisis tahap-tahap dalam siklus respons insiden dengan memberikan contoh nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan metodologi pengumpulan bukti digital dan teknik yang digunakan dalam proses forensik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menjelaskan jenis-jenis perangkat yang dapat menjadi sumber bukti digital, seperti komputer, smartphone, dan perangkat IoT.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis dan mendokumentasikan data yang dapat diperoleh dari jaringan lokal dan jaringan internet sebagai sumber bukti digital.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Dapat menggunakan alat forensik digital untuk mengekstrak bukti dari perangkat penyimpanan eksternal, seperti hard drive dan flash drive.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mengidentifikasi dan mengklasifikasikan jenis bukti digital yang relevan dalam kasus forensik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Melakukan proses akuisisi bukti digital menggunakan alat dan teknik yang sesuai untuk menjaga integritas data.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-4", "description": "Mampu menginstall dan mengkonfigurasi perangkat forensik Autopsy untuk analisis digital.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menggunakan FTK Imager untuk membuat salinan forensik dari media penyimpanan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-5", "description": "Mengidentifikasi dan mendokumentasikan setiap langkah dalam proses pengambilan bukti digital untuk memastikan keaslian data.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-5", "description": "Menyusun dan menyimpan dokumen rantai bukti yang mencakup informasi tentang siapa yang mengakses bukti, kapan, dan untuk tujuan apa.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-6", "description": "Menerapkan prinsip-prinsip etika dalam pengumpulan dan analisis bukti digital.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-6", "description": "Menunjukkan integritas dengan tidak memanipulasi data selama proses investigasi.", "relatedCpmk": "CPMK-6"}], "deskripsi": "Mata kuliah Digital Forensics and Incident Response bertujuan untuk memberikan pemahaman mendalam mengenai teknik dan metodologi yang digunakan dalam penyelidikan digital serta respons terhadap insiden keamanan siber. Materi yang akan dibahas mencakup prinsip-prinsip forensik digital, pengumpulan dan analisis bukti digital, serta strategi respon insiden untuk mengidentifikasi, mengelola, dan memulihkan dari insiden keamanan. Melalui pendekatan teoritis dan praktis, mahasiswa diharapkan dapat mengembangkan keterampilan analitis dan teknis yang diperlukan untuk menangani kasus-kasus forensik serta merumuskan rencana respons yang efektif terhadap ancaman siber. Mata kuliah ini memberikan manfaat signifikan bagi mahasiswa yang berminat dalam bidang keamanan informasi dan forensik digital, serta mempersiapkan mereka untuk menghadapi tantangan di industri teknologi informasi.", "referensi": ["Majid Yar (2021). Digital Forensics and Cyber Crime. Springer.", "Bill Nelson, Amelia Phillips, Christopher Steuart (2021). Guide to Computer Forensics and Investigations. Cengage Learning.", "Jason Sachowski (2020). Digital Forensics: Principles and Practices. Wiley.", "Debra S. Smith (2022). Computer Forensics: Investigating Network Intrusions and Cyber Crime. Cengage Learning.", "Brett Shavers (2020). The Basics of Digital Forensics: The Primer for Getting Started in Digital Forensics. Syngress.", "Eoghan Casey (2020). Digital Evidence and Computer Crime: Forensic Science, Computers, and the Internet. Academic Press.", "A. A. Alzahrani, M. A. Alharthi (2023). A Survey on Digital Forensics: Techniques, Tools, and Applications. International Journal of Information Security.", "S. V. Raghavan, D. P. S. Bhandari (2022). Digital Forensics: Challenges and Opportunities. Journal of Information Security and Applications.", "A. M. Al-Hamadi, A. A. Al-Bahadili (2021). Incident Response and Digital Forensics: A Review. Journal of Cybersecurity and Privacy.", "H. J. Lee, J. S. Kim (2023). Forensic Analysis of Network Traffic: A Case Study. Forensic Science International."], "bahanKajian": ["Topik 1: Pengenalan Digital Forensics - Menjelaskan konsep dasar digital forensics, sejarahnya, serta pentingnya dalam konteks keamanan siber dan hukum.", "Topik 2: Siklus Respons Insiden - Menguraikan tahapan dalam siklus respons insiden, mulai dari persiapan, identifikasi, konten, analisis, hingga pemulihan.", "Topik 3: Sumber Bukti Digital - Mengidentifikasi berbagai perangkat dan jaringan yang dapat menjadi sumber bukti digital, termasuk komputer, smartphone, dan perangkat IoT.", "Topik 4: Akuisisi dan Preservasi Bukti Digital - Menjelaskan metode akuisisi dan teknik preservasi yang sesuai dengan prosedur forensik untuk menjaga integritas bukti.", "Topik 5: Analisis Bukti Digital - Menggunakan perangkat forensik seperti Autopsy, FTK Imager, dan Volatility untuk melakukan analisis terhadap bukti digital.", "Topik 6: Analisis Lalu Lintas Jaringan - Menggunakan Wireshark untuk menganalisis lalu lintas jaringan dan mengidentifikasi anomali yang mungkin menunjukkan insiden.", "Topik 7: Penyusunan Laporan Investigasi - Menyusun laporan investigasi digital yang mencakup detail temuan, metodologi, dan menjaga rantai bukti (chain of custody).", "Topik 8: Etika dan Profesionalisme dalam Forensik - Menunjukkan sikap profesional, jujur, dan beretika selama proses investigasi forensik dan dampaknya terhadap hasil."], "description": "Mata kuliah Digital Forensics and Incident Response bertujuan untuk memberikan pemahaman mendalam mengenai teknik dan metodologi yang digunakan dalam penyelidikan digital serta respons terhadap insiden keamanan siber. Materi yang akan dibahas mencakup prinsip-prinsip forensik digital, pengumpulan dan analisis bukti digital, serta strategi respon insiden untuk mengidentifikasi, mengelola, dan memulihkan dari insiden keamanan. Melalui pendekatan teoritis dan praktis, mahasiswa diharapkan dapat mengembangkan keterampilan analitis dan teknis yang diperlukan untuk menangani kasus-kasus forensik serta merumuskan rencana respons yang efektif terhadap ancaman siber. Mata kuliah ini memberikan manfaat signifikan bagi mahasiswa yang berminat dalam bidang keamanan informasi dan forensik digital, serta mempersiapkan mereka untuk menghadapi tantangan di industri teknologi informasi.", "bahan_kajian": ["Topik 1: Pengenalan Digital Forensics - Menjelaskan konsep dasar digital forensics, sejarahnya, serta pentingnya dalam konteks keamanan siber dan hukum.", "Topik 2: Siklus Respons Insiden - Menguraikan tahapan dalam siklus respons insiden, mulai dari persiapan, identifikasi, konten, analisis, hingga pemulihan.", "Topik 3: Sumber Bukti Digital - Mengidentifikasi berbagai perangkat dan jaringan yang dapat menjadi sumber bukti digital, termasuk komputer, smartphone, dan perangkat IoT.", "Topik 4: Akuisisi dan Preservasi Bukti Digital - Menjelaskan metode akuisisi dan teknik preservasi yang sesuai dengan prosedur forensik untuk menjaga integritas bukti.", "Topik 5: Analisis Bukti Digital - Menggunakan perangkat forensik seperti Autopsy, FTK Imager, dan Volatility untuk melakukan analisis terhadap bukti digital.", "Topik 6: Analisis Lalu Lintas Jaringan - Menggunakan Wireshark untuk menganalisis lalu lintas jaringan dan mengidentifikasi anomali yang mungkin menunjukkan insiden.", "Topik 7: Penyusunan Laporan Investigasi - Menyusun laporan investigasi digital yang mencakup detail temuan, metodologi, dan menjaga rantai bukti (chain of custody).", "Topik 8: Etika dan Profesionalisme dalam Forensik - Menunjukkan sikap profesional, jujur, dan beretika selama proses investigasi forensik dan dampaknya terhadap hasil."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWakt