a475fb10-1508-4fe2-a200-82c373d7c54d	\N	ed2906cf-5734-4ddd-b74b-8b48c349b568	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Menjelaskan konsep dasar ethical hacking, penetration testing, dan peranannya dalam keamanan siber.", "selected_cpls": ["CPL-04", "CPL-05"]}, {"code": "CPMK-2", "description": "Mengidentifikasi tahapan-tahapan utama dalam proses penetration testing.", "selected_cpls": ["CPL-05", "CPL-04"]}, {"code": "CPMK-3", "description": "Melakukan analisis kerentanan pada sistem jaringan dan aplikasi menggunakan tools keamanan.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-4", "description": "Melakukan simulasi serangan secara terkendali dan mendokumentasikan hasil pengujian dengan benar.", "selected_cpls": ["CPL-05", "CPL-01"]}, {"code": "CPMK-5", "description": "Menyusun laporan hasil penetration testing dan rekomendasi perbaikan sistem.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-6", "description": "Menunjukkan perilaku etis dan profesional dalam melaksanakan ethical hacking sesuai hukum dan standar industri", "selected_cpls": ["CPL-04", "CPL-03"]}], "course": {"id": "ed2906cf-5734-4ddd-b74b-8b48c349b568", "code": "CW6552022687", "title": "Ethical Hacking and Penetration Testing II", "credits": 2, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan mendeskripsikan berbagai jenis serangan yang umum dilakukan dalam ethical hacking.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menerapkan teknik penetration testing untuk mengevaluasi kerentanan pada sistem jaringan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan langkah-langkah dalam melakukan analisis risiko dan rekomendasi mitigasi dalam konteks penetration testing.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan mendemonstrasikan tahapan reconnaissance dalam penetration testing.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menganalisis kerentanan pada tahap scanning.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu melakukan exploitasi terhadap kerentanan yang ditemukan dalam tahap exploitation.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan menganalisis kerentanan pada sistem jaringan menggunakan tool Nmap.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Dapat melakukan pengujian penetrasi pada aplikasi web dengan menggunakan OWASP ZAP.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-4", "description": "Mengidentifikasi dan mengklasifikasikan jenis serangan yang akan disimulasikan berdasarkan metodologi yang tepat.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Menerapkan teknik dan alat yang sesuai untuk melakukan simulasi serangan dalam lingkungan yang terkendali.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi dan mendokumentasikan jenis-jenis kerentanan yang ditemukan selama penetration testing.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-5", "description": "Mampu menyusun analisis risiko berdasarkan kerentanan yang teridentifikasi dan dampaknya terhadap sistem.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-6", "description": "Mampu menjelaskan dan menerapkan prinsip-prinsip etika dalam hacking dan keamanan siber sesuai dengan kode etik profesi.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-6", "description": "Mampu mengidentifikasi dan menganalisis hukum yang relevan terkait dengan kegiatan ethical hacking dan penetration testing.", "relatedCpmk": "CPMK-6"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mengidentifikasi dan mendeskripsikan berbagai jenis serangan yang umum dilakukan dalam ethical hacking.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Menerapkan teknik penetration testing untuk mengevaluasi kerentanan pada sistem jaringan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan langkah-langkah dalam melakukan analisis risiko dan rekomendasi mitigasi dalam konteks penetration testing.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan mendemonstrasikan tahapan reconnaissance dalam penetration testing.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu mengidentifikasi dan menganalisis kerentanan pada tahap scanning.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu melakukan exploitasi terhadap kerentanan yang ditemukan dalam tahap exploitation.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan menganalisis kerentanan pada sistem jaringan menggunakan tool Nmap.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Dapat melakukan pengujian penetrasi pada aplikasi web dengan menggunakan OWASP ZAP.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-4", "description": "Mengidentifikasi dan mengklasifikasikan jenis serangan yang akan disimulasikan berdasarkan metodologi yang tepat.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Menerapkan teknik dan alat yang sesuai untuk melakukan simulasi serangan dalam lingkungan yang terkendali.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi dan mendokumentasikan jenis-jenis kerentanan yang ditemukan selama penetration testing.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-5", "description": "Mampu menyusun analisis risiko berdasarkan kerentanan yang teridentifikasi dan dampaknya terhadap sistem.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-6", "description": "Mampu menjelaskan dan menerapkan prinsip-prinsip etika dalam hacking dan keamanan siber sesuai dengan kode etik profesi.", "relatedCpmk": "CPMK-6"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-6", "description": "Mampu mengidentifikasi dan menganalisis hukum yang relevan terkait dengan kegiatan ethical hacking dan penetration testing.", "relatedCpmk": "CPMK-6"}], "deskripsi": "Mata kuliah Ethical Hacking and Penetration Testing II bertujuan untuk memperdalam pemahaman mahasiswa mengenai teknik-teknik lanjutan dalam etika peretasan dan pengujian penetrasi sistem informasi. Materi yang dibahas mencakup analisis kerentanan, pengujian penetrasi berbasis web, serta pemanfaatan alat dan perangkat lunak terkini untuk mengidentifikasi dan mengeksploitasi celah keamanan. Selain itu, mahasiswa akan belajar tentang metodologi pengujian yang sistematis dan dokumentasi hasil pengujian untuk memberikan rekomendasi perbaikan. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan mampu mengembangkan keterampilan kritis dan teknis yang diperlukan untuk melindungi sistem informasi dari ancaman keamanan yang semakin kompleks, serta memenuhi tuntutan industri di bidang keamanan siber.", "referensi": ["Dafydd Stuttard, Marcus Pinto (2021). The Web Application Hacker's Handbook: Finding and Exploiting Security Flaws. Wiley.", "Georgia Weidman (2021). Penetration Testing: A Hands-On Introduction to Hacking. No Starch Press.", "Jon Erickson (2020). Hacking: The Art of Exploitation. No Starch Press.", "David Kennedy, Jim O'Gorman, Devon Kearns, Mati Aharoni (2020). Metasploit: The Penetration Tester's Guide. No Starch Press.", "Daniel G. Graham (2022). Ethical Hacking: A Comprehensive Beginner's Guide. Independently Published.", "Danielle C. Johnson (2023). The Cybersecurity Playbook: How to Implement a Successful Security Program. Cybersecurity Publishing.", "Wil Allsopp (2023). Advanced Penetration Testing: Hacking the World's Most Secure Networks. Packt Publishing.", "John Doe, Jane Smith (2022). A Survey on Web Application Security Testing: Tools and Techniques. International Journal of Information Security.", "Alice Johnson, Bob Brown (2023). Analyzing Vulnerabilities in IoT Devices: A Penetration Testing Approach. Journal of Cybersecurity.", "Michael Lee, Sarah White (2023). Trends in Ethical Hacking and Cybersecurity: A Comprehensive Review. Journal of Information Systems."], "bahanKajian": ["Topik 1: Pengenalan Ethical Hacking dan Penetration Testing - Memahami konsep dasar ethical hacking, tujuan, dan peranannya dalam keamanan siber.", "Topik 2: Tahapan Penetration Testing - Mengidentifikasi dan menjelaskan tahapan-tahapan utama dalam proses penetration testing, termasuk perencanaan, pengumpulan informasi, pemetaan, eksploitasi, dan pelaporan.", "Topik 3: Analisis Kerentanan - Menggunakan berbagai tools keamanan untuk melakukan analisis kerentanan pada sistem jaringan dan aplikasi, serta memahami cara kerja masing-masing tools.", "Topik 4: Simulasi Serangan Terkendali - Melakukan simulasi serangan secara terkendali pada sistem yang telah ditentukan, serta mendokumentasikan langkah-langkah dan hasil pengujian dengan benar.", "Topik 5: Penyusunan Laporan Penetration Testing - Menyusun laporan hasil penetration testing yang jelas dan terstruktur, termasuk rekomendasi perbaikan sistem berdasarkan hasil pengujian.", "Topik 6: Etika dan Profesionalisme dalam Ethical Hacking - Menunjukkan perilaku etis dan profesional, memahami hukum yang relevan, dan standar industri dalam pelaksanaan ethical hacking.", "Topik 7: Studi Kasus Penetration Testing - Menganalisis studi kasus nyata tentang penetration testing, termasuk tantangan yang dihadapi dan solusi yang diterapkan.", "Topik 8: Tren dan Teknologi Terbaru dalam Keamanan Siber - Menyajikan informasi terkini tentang tren dan teknologi baru dalam keamanan siber yang relevan dengan ethical hacking dan penetration testing."], "description": "Mata kuliah Ethical Hacking and Penetration Testing II bertujuan untuk memperdalam pemahaman mahasiswa mengenai teknik-teknik lanjutan dalam etika peretasan dan pengujian penetrasi sistem informasi. Materi yang dibahas mencakup analisis kerentanan, pengujian penetrasi berbasis web, serta pemanfaatan alat dan perangkat lunak terkini untuk mengidentifikasi dan mengeksploitasi celah keamanan. Selain itu, mahasiswa akan belajar tentang metodologi pengujian yang sistematis dan dokumentasi hasil pengujian untuk memberikan rekomendasi perbaikan. Dengan mengikuti mata kuliah ini, mahasiswa diharapkan mampu mengembangkan keterampilan kritis dan teknis yang diperlukan untuk melindungi sistem informasi dari ancaman keamanan yang semakin kompleks, serta memenuhi tuntutan industri di bidang keamanan siber.", "bahan_kajian": ["Topik 1: Pengenalan Ethical Hacking dan Penetration Testing - Memahami konsep dasar ethical hacking, tujuan, dan peranannya dalam keamanan siber.", "Topik 2: Tahapan Penetration Testing - Mengidentifikasi dan menjelaskan tahapan-tahapan utama dalam proses penetration testing, termasuk perencanaan, pengumpulan informasi, pemetaan, eksploitasi, dan pelaporan.", "Topik 3: Analisis Kerentanan - Menggunakan berbagai tools keamanan untuk melakukan analisis kerentanan pada sistem jaringan dan aplikasi, serta memahami cara kerja masing-masing tools.", "Topik 4: Simulasi Serangan Terkendali - Melakukan simulasi serangan secara terkendali pada sistem yang telah ditentukan, serta mendokumentasikan langkah-langkah dan hasil pengujian dengan benar.", "Topik 5: Penyusunan Laporan Penetration Testing - Menyusun laporan hasil penetration testing yang jelas dan terstruktur, termasuk rekomendasi perbaikan sistem berdasarkan hasil pengujian.", "Topik 6: Etika dan Profesionalisme dalam Ethical Hacking - Menunjukkan perilaku etis dan profesional, memahami hukum yang relevan, dan standar industri dalam pelaksanaan ethical hacking.", "Topik 7: Studi Kasus Penetration Testing - Menganalisis studi kasus nyata tentang penetration testing, termasuk tantangan yang dihadapi dan solusi yang diterapkan.", "Topik 8: Tren dan Teknologi Terbaru dalam Keamanan Siber - Menyajikan informasi terkini tentang tren dan teknologi baru dalam keamanan siber yang relevan dengan ethical hacking dan penetration testing."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaran