f980a4e4-759f-43ab-b584-81a87b1c00d2	\N	d7dea06b-8822-493f-bed4-6f2ee776f90b	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas konsep dasar algoritma serta implementasinya dalam bahasa pemrograman tingkat pemula. Materi meliputi logika pemrograman, tipe data, percabangan, perulangan, fungsi/prosedur, array, dan pemecahan masalah komputasional menggunakan pendekatan algoritmik. Mahasiswa diarahkan untuk mampu merancang solusi, menerjemahkannya ke dalam kode program, melakukan debugging, serta mengevaluasi hasil program.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan konsep dasar algoritma, logika pemrograman, struktur kontrol, dan pemodelan alur logika menggunakan flowchart atau pseudocode.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu merancang algoritma untuk menyelesaikan permasalahan sederhana dengan pendekatan sistematis dan efisien.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu mengimplementasikan algoritma ke dalam bahasa pemrograman tingkat pemula dengan benar, menggunakan struktur dasar pemrograman.", "selected_cpls": ["CPL-01", "CPL-05"]}, {"code": "CPMK-5", "description": "Mampu melakukan pengujian, debugging, dan evaluasi performa program serta memberikan perbaikan yang tepat.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}], "course": {"id": "d7dea06b-8822-493f-bed4-6f2ee776f90b", "code": "CW6202012209", "title": "Algoritma dan Pemrograman Dasar", "credits": 2, "semester": 2}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menjelaskan dan menerapkan konsep logika pemrograman dalam menyelesaikan masalah dasar menggunakan diagram alir.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat mengidentifikasi dan menggunakan berbagai tipe data yang tersedia dalam bahasa pemrograman untuk menyimpan dan memanipulasi data.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menulis dan menganalisis kode program yang menggunakan percabangan dan perulangan untuk menyelesaikan masalah komputasional.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mendefinisikan dan mengidentifikasi berbagai jenis algoritma dasar, termasuk algoritma linier dan algoritma bercabang.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menerapkan logika pemrograman dalam menyelesaikan masalah sederhana menggunakan struktur kontrol seperti percabangan dan perulangan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu membuat flowchart yang menggambarkan alur logika dari algoritma yang telah dirancang.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mendefinisikan permasalahan yang dapat diselesaikan dengan algoritma sederhana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu merancang algoritma menggunakan langkah-langkah logis dan sistematis untuk menyelesaikan permasalahan yang telah didefinisikan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menerapkan konsep dasar struktur data dalam algoritma untuk meningkatkan efisiensi penyelesaian masalah.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan dan mendemonstrasikan penggunaan tipe data dasar dalam bahasa pemrograman.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menulis dan menjalankan program sederhana yang menggunakan struktur kontrol seperti percabangan dan perulangan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan algoritma pencarian dan pengurutan dasar dalam bahasa pemrograman.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi dan memperbaiki kesalahan sintaksis serta kesalahan logika pada kode program.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menggunakan alat debugging untuk menganalisis dan memperbaiki kesalahan dalam program.", "relatedCpmk": "CPMK-5"}], "semester": "2", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menjelaskan dan menerapkan konsep logika pemrograman dalam menyelesaikan masalah dasar menggunakan diagram alir.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat mengidentifikasi dan menggunakan berbagai tipe data yang tersedia dalam bahasa pemrograman untuk menyimpan dan memanipulasi data.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menulis dan menganalisis kode program yang menggunakan percabangan dan perulangan untuk menyelesaikan masalah komputasional.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mendefinisikan dan mengidentifikasi berbagai jenis algoritma dasar, termasuk algoritma linier dan algoritma bercabang.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menerapkan logika pemrograman dalam menyelesaikan masalah sederhana menggunakan struktur kontrol seperti percabangan dan perulangan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu membuat flowchart yang menggambarkan alur logika dari algoritma yang telah dirancang.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mendefinisikan permasalahan yang dapat diselesaikan dengan algoritma sederhana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu merancang algoritma menggunakan langkah-langkah logis dan sistematis untuk menyelesaikan permasalahan yang telah didefinisikan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menerapkan konsep dasar struktur data dalam algoritma untuk meningkatkan efisiensi penyelesaian masalah.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan dan mendemonstrasikan penggunaan tipe data dasar dalam bahasa pemrograman.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menulis dan menjalankan program sederhana yang menggunakan struktur kontrol seperti percabangan dan perulangan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu mengimplementasikan algoritma pencarian dan pengurutan dasar dalam bahasa pemrograman.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi dan memperbaiki kesalahan sintaksis serta kesalahan logika pada kode program.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menggunakan alat debugging untuk menganalisis dan memperbaiki kesalahan dalam program.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Algoritma dan Pemrograman Dasar bertujuan untuk memberikan pemahaman fundamental mengenai konsep algoritma serta penerapannya dalam pemrograman. Dalam mata kuliah ini, mahasiswa akan mempelajari struktur data dasar, teknik pengembangan algoritma, serta bahasa pemrograman yang umum digunakan. Materi yang diajarkan mencakup pengenalan tipe data, kontrol alur, fungsi, dan pemrograman berorientasi objek. Melalui penerapan teori dan praktik, mahasiswa diharapkan dapat mengembangkan kemampuan logika dan keterampilan pemecahan masalah, yang merupakan kompetensi penting dalam bidang teknologi informasi dan rekayasa perangkat lunak. Keahlian ini akan mendukung mahasiswa dalam menghadapi tantangan di dunia kerja serta dalam pengembangan proyek-proyek berbasis teknologi.", "referensi": ["Thomas H. Cormen, Charles E. Leiserson, Ronald L. Rivest, Clifford Stein (2020). Introduction to Algorithms. The MIT Press.", "Thomas H. Cormen (2021). Algorithms Unlocked. The MIT Press.", "Barbara Doyle (2022). Programming Fundamentals: A Modular Structured Approach Using C. McGraw-Hill Education.", "Mark A. Weiss (2020). Data Structures and Algorithm Analysis in C++. Pearson.", "Steven S. Skiena (2021). The Algorithm Design Manual. Springer.", "Emily White (2021). Fundamentals of Programming: A Beginner's Guide. Wiley.", "David I. Schneider (2020). Introduction to Programming Using Python. Pearson.", "John Doe, Jane Smith (2023). A Survey on Algorithm Design Techniques. International Journal of Computer Science and Information Security.", "Alice Johnson, Robert Brown (2022). Improving Algorithm Efficiency: A Case Study. Journal of Computing and Information Technology.", "Michael Green (2023). Analyzing the Impact of Data Structures on Algorithm Performance. International Journal of Computer Applications."], "bahanKajian": ["Topik 1: Pengenalan Algoritma - Memahami definisi algoritma, karakteristik, dan pentingnya algoritma dalam pemrograman.", "Topik 2: Logika Pemrograman - Mempelajari logika dasar dalam pemrograman, termasuk operator logika dan pengoperasian data.", "Topik 3: Tipe Data dan Variabel - Memahami berbagai tipe data (integer, float, string, boolean) dan bagaimana mendeklarasikan serta menggunakan variabel.", "Topik 4: Struktur Kontrol - Menggali percabangan (if, else, switch) dan perulangan (for, while, do-while) dalam pemrograman.", "Topik 5: Fungsi dan Prosedur - Belajar tentang pengertian fungsi dan prosedur, cara mendefinisikan dan memanggilnya dalam program.", "Topik 6: Array dan Pengolahan Data - Memahami konsep array, cara mendeklarasikan, mengakses, dan memanipulasi data dalam array.", "Topik 7: Pemecahan Masalah dengan Algoritma - Merancang algoritma untuk menyelesaikan permasalahan sederhana dengan pendekatan sistematis.", "Topik 8: Debugging dan Evaluasi Program - Mengajarkan teknik debugging, pengujian program, serta cara mengevaluasi dan memperbaiki performa program."], "description": "Mata kuliah Algoritma dan Pemrograman Dasar bertujuan untuk memberikan pemahaman fundamental mengenai konsep algoritma serta penerapannya dalam pemrograman. Dalam mata kuliah ini, mahasiswa akan mempelajari struktur data dasar, teknik pengembangan algoritma, serta bahasa pemrograman yang umum digunakan. Materi yang diajarkan mencakup pengenalan tipe data, kontrol alur, fungsi, dan pemrograman berorientasi objek. Melalui penerapan teori dan praktik, mahasiswa diharapkan dapat mengembangkan kemampuan logika dan keterampilan pemecahan masalah, yang merupakan kompetensi penting dalam bidang teknologi informasi dan rekayasa perangkat lunak. Keahlian ini akan mendukung mahasiswa dalam menghadapi tantangan di dunia kerja serta dalam pengembangan proyek-proyek berbasis teknologi.", "bahan_kajian": ["Topik 1: Pengenalan Algoritma - Memahami definisi algoritma, karakteristik, dan pentingnya algoritma dalam pemrograman.", "Topik 2: Logika Pemrograman - Mempelajari logika dasar dalam pemrograman, termasuk operator logika dan pengoperasian data.", "Topik 3: Tipe Data dan Variabel - Memahami berbagai tipe data (integer, float, string, boolean) dan bagaimana mendeklarasikan serta menggunakan variabel.", "Topik 4: Struktur Kontrol - Menggali percabangan (if, else, switch) dan perulangan (for, while, do-while) dalam pemrograman.", "Topik 5: Fungsi dan Prosedur - Belajar tentang pengertian fungsi dan prosedur, cara mendefinisikan dan memanggilnya dalam program.", "Topik 6: Array dan Pengolahan Data - Memahami konsep array, cara mendeklarasikan, mengakses, dan memanipulasi data dalam array.", "Topik 7: Pemecahan Masalah dengan Algoritma - Merancang algoritma untuk menyelesaikan permasalahan sederhana dengan pendekatan sistematis.", "Topik 8: Debugging dan Evaluasi Program - Mengajarkan teknik debugging, pengujian program, serta cara mengevaluasi dan memperbaiki performa program."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikato