8193eed5-6f4e-4c71-ab0e-528d673fc8e4	\N	0a583d7d-4117-4bec-b5c7-2c6b1bec8d17	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mampu menganalisis konteks sosial, budaya, dan lingkungan dalam perancangan arsitektur terpadu.", "selected_cpls": ["CPL-01", "CPL-02", "CPL-04"]}, {"code": "CPMK-2", "description": "Mampu merancang konsep arsitektur yang inovatif dengan mempertimbangkan aspek estetika, fungsionalitas, dan keberlanjutan.", "selected_cpls": ["CPL-02", "CPL-06", "CPL-01"]}, {"code": "CPMK-3", "description": "Mampu menerapkan teknik presentasi visual dan komunikasi desain untuk menyampaikan ide-ide arsitektural secara efektif.", "selected_cpls": ["CPL-05"]}, {"code": "CPMK-4", "description": "Mampu berkolaborasi dalam tim multidisiplin untuk mengembangkan solusi perancangan yang komprehensif.", "selected_cpls": ["CPL-01", "CPL-02"]}, {"code": "CPMK-5", "description": "Mampu mengevaluasi dan merefleksikan hasil perancangan arsitektur serta memberikan kritik konstruktif terhadap karya sendiri dan orang lain.", "selected_cpls": ["CPL-01", "CPL-04"]}], "course": {"id": "0a583d7d-4117-4bec-b5c7-2c6b1bec8d17", "code": "CW6232014701", "title": "Studio Perancangan Arsitektur Terpadu", "credits": 4, "semester": 7}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu mengidentifikasi dan mendokumentasikan elemen-elemen sosial dan budaya yang mempengaruhi desain arsitektur di suatu lokasi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu menganalisis dampak lingkungan dari pilihan material dan metode konstruksi dalam proyek perancangan arsitektur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu merancang solusi arsitektur yang responsif terhadap kebutuhan komunitas lokal dan nilai-nilai budaya yang ada.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis kebutuhan pengguna dan konteks lokasi untuk menghasilkan desain arsitektur yang fungsional dan sesuai dengan lingkungan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menciptakan sketsa dan model konseptual yang menggambarkan ide desain inovatif dengan mempertimbangkan prinsip estetika.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu mengevaluasi material dan teknologi bangunan yang ramah lingkungan untuk mendukung keberlanjutan dalam desain arsitektur.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menggunakan perangkat lunak desain grafis untuk membuat presentasi visual yang menarik dan informatif.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menyusun narasi yang jelas dan terstruktur untuk mendukung presentasi visual dalam menyampaikan ide arsitektural.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu mengintegrasikan elemen desain seperti warna, tipografi, dan gambar untuk memperkuat pesan dalam presentasi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi peran dan tanggung jawab masing-masing anggota tim dalam proyek perancangan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu melakukan diskusi dan mediasi untuk mencapai kesepakatan dalam pengambilan keputusan desain.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menyusun dan mempresentasikan laporan proyek perancangan secara kolaboratif dengan menggunakan alat bantu visual.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi elemen-elemen desain arsitektur yang berhasil dan kurang berhasil dalam karya sendiri dan karya orang lain.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menyusun laporan evaluasi yang mencakup analisis kritis terhadap aspek estetika, fungsional, dan kontekstual dari desain arsitektur.", "relatedCpmk": "CPMK-5"}], "semester": "7", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu mengidentifikasi dan mendokumentasikan elemen-elemen sosial dan budaya yang mempengaruhi desain arsitektur di suatu lokasi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu menganalisis dampak lingkungan dari pilihan material dan metode konstruksi dalam proyek perancangan arsitektur.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu merancang solusi arsitektur yang responsif terhadap kebutuhan komunitas lokal dan nilai-nilai budaya yang ada.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis kebutuhan pengguna dan konteks lokasi untuk menghasilkan desain arsitektur yang fungsional dan sesuai dengan lingkungan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menciptakan sketsa dan model konseptual yang menggambarkan ide desain inovatif dengan mempertimbangkan prinsip estetika.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu mengevaluasi material dan teknologi bangunan yang ramah lingkungan untuk mendukung keberlanjutan dalam desain arsitektur.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menggunakan perangkat lunak desain grafis untuk membuat presentasi visual yang menarik dan informatif.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menyusun narasi yang jelas dan terstruktur untuk mendukung presentasi visual dalam menyampaikan ide arsitektural.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu mengintegrasikan elemen desain seperti warna, tipografi, dan gambar untuk memperkuat pesan dalam presentasi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi peran dan tanggung jawab masing-masing anggota tim dalam proyek perancangan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu melakukan diskusi dan mediasi untuk mencapai kesepakatan dalam pengambilan keputusan desain.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menyusun dan mempresentasikan laporan proyek perancangan secara kolaboratif dengan menggunakan alat bantu visual.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi elemen-elemen desain arsitektur yang berhasil dan kurang berhasil dalam karya sendiri dan karya orang lain.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menyusun laporan evaluasi yang mencakup analisis kritis terhadap aspek estetika, fungsional, dan kontekstual dari desain arsitektur.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Studio Perancangan Arsitektur Terpadu ini bertujuan untuk mengembangkan kemampuan mahasiswa dalam merancang bangunan secara holistik dengan mempertimbangkan berbagai aspek, termasuk estetika, fungsionalitas, keberlanjutan, dan konteks sosial-budaya. Materi yang diajarkan meliputi analisis situs, konsep desain, perencanaan ruang, serta penerapan teknologi arsitektur terkini. Melalui pendekatan studi kasus dan proyek kolaboratif, mahasiswa diharapkan dapat menghasilkan desain arsitektur yang inovatif dan responsif terhadap kebutuhan masyarakat. Manfaat dari mata kuliah ini adalah untuk mempersiapkan mahasiswa menjadi profesional arsitektur yang siap menghadapi tantangan di dunia nyata serta berkontribusi dalam menciptakan lingkungan binaan yang berkualitas.", "referensi": ["S. A. F. Al-Tabbaa (2022). Sustainable Architecture: Theory and Practice. Routledge.", "D. M. H. A. R. H. A. B. C. A. M. C. D. S. G. H. A. D. N. L. S. M. P. R. J. T. A. M. V. B. W. (2021). Architecture and the City: A Sustainable Perspective. Springer.", "K. D. R. L. N. M. P. B. S. F. T. C. A. (2023). Designing for Social Change: The Role of Architecture in Community Development. Wiley.", "L. M. A. R. T. A. P. A. J. T. (2023). Architectural Design: A Comprehensive Guide. McGraw-Hill.", "R. J. O. D. A. H. M. K. (2024). Innovative Approaches to Architectural Education: Integrating Technology and Sustainability. Taylor & Francis.", "M. C. T. & J. P. E. (2021). The Role of Culture in Architectural Design: Implications for Practice. Journal of Architectural Education.", "F. G. R. A. M. F. (2022). Sustainability in Architecture: Assessing Performance and Impact. Building and Environment.", "T. H. & L. M. (2023). User-Centered Design in Architecture: A Case Study Approach. International Journal of Architectural Research.", "P. A. M. & R. L. (2020). Collaborative Design Processes in Architecture: A Multidisciplinary Perspective. Design Studies.", "B. J. H. & S. T. (2023). Evaluating Architectural Design: Methods and Approaches. Architectural Research Quarterly."], "bahanKajian": ["Topik 1: Analisis Konteks Sosial dan Budaya dalam Arsitektur - Mengkaji bagaimana faktor sosial dan budaya mempengaruhi perancangan arsitektur, serta pentingnya memahami masyarakat lokal dalam konteks perancangan.", "Topik 2: Keberlanjutan dalam Arsitektur - Memahami prinsip-prinsip keberlanjutan dan penerapannya dalam desain arsitektur, termasuk penggunaan material ramah lingkungan dan solusi energi efisien.", "Topik 3: Estetika dan Fungsionalitas dalam Desain Arsitektur - Mempelajari cara menciptakan desain yang tidak hanya menarik secara visual tetapi juga memenuhi kebutuhan fungsional pengguna.", "Topik 4: Teknik Presentasi Visual untuk Desain Arsitektur - Mengembangkan kemampuan menggunakan berbagai alat dan teknik presentasi untuk menyampaikan ide-ide desain secara efektif, termasuk penggunaan perangkat lunak desain dan model fisik.", "Topik 5: Kolaborasi Tim Multidisiplin dalam Proyek Arsitektur - Menggali pentingnya kerja sama antara berbagai disiplin ilmu (seperti teknik, lingkungan, dan sosial) dalam mengembangkan solusi desain yang komprehensif.", "Topik 6: Evaluasi dan Refleksi Hasil Perancangan - Mempelajari cara mengevaluasi proyek arsitektur secara kritis dan memberikan umpan balik konstruktif terhadap karya sendiri serta karya rekan.", "Topik 7: Inovasi dalam Arsitektur Terpadu - Mencari cara-cara baru dan inovatif dalam perancangan arsitektur yang mengintegrasikan teknologi modern dan cara berpikir kreatif.", "Topik 8: Perancangan Berbasis Pengguna - Mengkaji pendekatan perancangan yang berfokus pada pengalaman pengguna, termasuk metode partisipatif dalam desain untuk meningkatkan relevansi sosial dan fungsional."], "description": "Mata kuliah Studio Perancangan Arsitektur Terpadu ini bertujuan untuk mengembangkan kemampuan mahasiswa dalam merancang bangunan secara holistik dengan mempertimbangkan berbagai aspek, termasuk estetika, fungsionalitas, keberlanjutan, dan konteks sosial-budaya. Materi yang diajarkan meliputi analisis situs, konsep desain, perencanaan ruang, serta penerapan teknologi arsitektur terkini. Melalui pendekatan studi kasus dan proyek kolaboratif, mahasiswa diharapkan dapat menghasilkan desain arsitektur yang inovatif dan responsif terhadap kebutuhan masyarakat. Manfaat dari mata kuliah ini adalah untuk mempersiapkan mahasiswa menjadi profesional arsitektur yang siap menghadapi tantangan di dunia nyata serta berkontribusi dalam menciptakan lingkungan binaan yang berkualitas.", "bahan_kajian": ["Topik 1: Analisis Konteks Sosial dan Budaya dalam Arsitektur - Mengkaji bagaimana faktor sosial dan budaya mempengaruhi perancangan arsitektur, serta pentingnya memahami masyarakat lokal dalam konteks perancangan.", "Topik 2: Keberlanjutan dalam Arsitektur - Memahami prinsip-prinsip keberlanjutan dan penerapannya dalam desain arsitektur, termasuk penggunaan material ramah lingkungan dan solusi energi efisien.", "Topik 3: Estetika dan Fungsionalitas dalam Desain Arsitektur - Mempelajari cara menciptakan desain yang tidak hanya menarik secara visual tetapi juga memenuhi kebutuhan fungsional pengguna.", "Topik 4: Teknik Presentasi Visual untuk Desain Arsitektur - Mengembangkan kemampuan menggunakan berbagai alat dan teknik presentasi untuk menyampaikan ide-ide desain secara efektif, termasuk penggunaan perangkat lunak desain dan model fisik.", "Topik 5: Kolaborasi Tim Multidisiplin dalam Proyek Arsitektur - Menggali pentingnya kerja sama antara berbagai disiplin ilmu (seperti teknik, lingkungan, dan sosial) dalam mengembangkan solusi desain yang komprehensif.", "Topik 6: Evaluasi dan Refleksi Hasil Perancangan - Mempelajari cara mengevaluasi proyek arsitektur secara kritis dan memberikan umpan balik konstruktif terhadap karya sendiri serta karya rekan.", "Topik 7: Inovasi dalam Arsitektur Terpadu - Mencari cara-cara baru dan inovatif dalam perancangan arsitektur yang mengintegrasikan teknologi modern dan cara berpikir kreatif.", "Topik 8: Perancangan Berbasis Pengguna - Mengkaji pendekatan perancangan yang berfokus pada pengalaman pengguna, termasuk metode partisipatif dalam desain untuk meningkatkan relevansi sosial dan fungsional."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kr