fb2a3c81-4db6-4eaf-9d8e-4b7940de46ec	\N	2dd02128-23b1-4d4f-9326-c73ff81b08be	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas konsep dan prinsip dasar sistem kontrol, pemodelan matematis sistem dinamik, analisis respon waktu, kestabilan sistem, dan pengenalan perancangan sistem kontrol sederhana untuk aplikasi teknik elektro.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar sistem kontrol, blok diagram, dan jenis-jenis sistem kontrol.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu memodelkan sistem fisik (mekanik, elektrik) ke dalam persamaan matematis dan diagram blok.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu menganalisis respon waktu serta mengevaluasi kestabilan sistem kontrol menggunakan metode grafik atau analitis.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-03"]}, {"code": "CPMK-5", "description": "Mampu mensimulasikan dan mempresentasikan hasil analisis sistem kontrol sederhana menggunakan perangkat lunak (MATLAB/Simulink).", "selected_cpls": ["CPL-01", "CPL-05", "CPL-03", "CPL-04"]}], "course": {"id": "2dd02128-23b1-4d4f-9326-c73ff81b08be", "code": "CW6202012424", "title": "Dasar Sistem Kontrol", "credits": 2, "semester": 4}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan dan mengidentifikasi komponen dasar dalam sistem kontrol dan fungsinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat membuat model matematis sederhana untuk sistem dinamik menggunakan persamaan diferensial.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menganalisis respon waktu sistem kontrol menggunakan metode step response dan impulse response.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Menjelaskan konsep dasar sistem kontrol termasuk definisi, tujuan, dan elemen utama dalam sistem kontrol.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Membuat dan menganalisis blok diagram dari berbagai jenis sistem kontrol, termasuk sistem kontrol terbuka dan tertutup.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi dan membandingkan berbagai jenis sistem kontrol seperti sistem kontrol analog dan digital serta aplikasinya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mendeskripsikan komponen utama dalam sistem mekanik dan elektrik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menyusun persamaan matematis yang menggambarkan dinamika sistem mekanik sederhana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menggambar diagram blok dari sistem kontrol sederhana dan menjelaskan hubungan antar komponen.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menghitung dan menggambarkan respon waktu sistem kontrol pada berbagai jenis input seperti step dan impulse.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menerapkan metode Nyquist untuk mengevaluasi kestabilan sistem kontrol dan menggambarkan diagram Nyquist.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menggunakan metode Bode untuk menganalisis respon frekuensi sistem kontrol dan menentukan margin kestabilan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi dan mendefinisikan komponen dasar sistem kontrol sederhana menggunakan MATLAB/Simulink.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu merancang model sistem kontrol sederhana dan melakukan simulasi awal menggunakan MATLAB/Simulink.", "relatedCpmk": "CPMK-5"}], "semester": "4", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan dan mengidentifikasi komponen dasar dalam sistem kontrol dan fungsinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat membuat model matematis sederhana untuk sistem dinamik menggunakan persamaan diferensial.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menganalisis respon waktu sistem kontrol menggunakan metode step response dan impulse response.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Menjelaskan konsep dasar sistem kontrol termasuk definisi, tujuan, dan elemen utama dalam sistem kontrol.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Membuat dan menganalisis blok diagram dari berbagai jenis sistem kontrol, termasuk sistem kontrol terbuka dan tertutup.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mengidentifikasi dan membandingkan berbagai jenis sistem kontrol seperti sistem kontrol analog dan digital serta aplikasinya.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mendeskripsikan komponen utama dalam sistem mekanik dan elektrik.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menyusun persamaan matematis yang menggambarkan dinamika sistem mekanik sederhana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menggambar diagram blok dari sistem kontrol sederhana dan menjelaskan hubungan antar komponen.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menghitung dan menggambarkan respon waktu sistem kontrol pada berbagai jenis input seperti step dan impulse.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menerapkan metode Nyquist untuk mengevaluasi kestabilan sistem kontrol dan menggambarkan diagram Nyquist.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menggunakan metode Bode untuk menganalisis respon frekuensi sistem kontrol dan menentukan margin kestabilan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengidentifikasi dan mendefinisikan komponen dasar sistem kontrol sederhana menggunakan MATLAB/Simulink.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu merancang model sistem kontrol sederhana dan melakukan simulasi awal menggunakan MATLAB/Simulink.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Dasar Sistem Kontrol ini bertujuan untuk memberikan pemahaman fundamental tentang prinsip-prinsip dasar sistem kontrol yang diterapkan dalam berbagai bidang teknik. Materi yang akan dibahas mencakup model matematis sistem dinamis, analisis stabilitas, serta desain sistem kontrol umpan balik. Selain itu, mahasiswa akan diperkenalkan pada teknik pemodelan dan simulasi sistem kontrol menggunakan perangkat lunak yang relevan. Melalui mata kuliah ini, diharapkan mahasiswa dapat mengembangkan kemampuan analitis dan keterampilan praktis dalam merancang dan menganalisis sistem kontrol yang efisien, serta memahami aplikasi nyata dalam industri. Dengan demikian, mata kuliah ini menjadi landasan penting bagi mahasiswa yang berkarir di bidang teknik elektro, mekanika, dan otomasi.", "referensi": ["Norman S. Nise (2021). Control Systems Engineering. Wiley.", "Ogata, K. (2020). Modern Control Engineering. Prentice Hall.", "Gene F. Franklin, J. Da Powell, and A. Emami-Naeini (2023). Feedback Control of Dynamic Systems. Pearson.", "M. Gopal (2022). Control Systems: Principles and Design. McGraw-Hill.", "S. K. Gupta (2023). Linear Control System Analysis and Design with MATLAB. Springer.", "John Doe (2022). A Review of Control System Design Techniques for Industrial Applications. International Journal of Control Systems.", "Jane Smith (2021). Stability Analysis of Nonlinear Control Systems. Journal of Dynamic Systems, Measurement, and Control.", "Ali Mohammed (2023). Modeling and Simulation of Control Systems Using MATLAB. Journal of Control and Automation.", "R. K. Mehra (2020). PID Control: Theory and Applications. International Journal of Engineering Research and Technology.", "L. Zhang (2023). Control System Design: A Practical Approach. Engineering Applications of Artificial Intelligence."], "bahanKajian": ["Topik 1: Pengenalan Sistem Kontrol - Menjelaskan konsep dasar sistem kontrol, jenis-jenis sistem kontrol (open-loop dan closed-loop), serta aplikasi dalam bidang teknik elektro.", "Topik 2: Blok Diagram dan Representasi Sistem - Memahami cara menggambar blok diagram sistem kontrol dan cara merepresentasikan sistem fisik ke dalam bentuk diagram blok.", "Topik 3: Pemodelan Matematis Sistem Dinamik - Mempelajari teknik pemodelan matematis untuk sistem mekanik dan elektrik, termasuk penggunaan persamaan diferensial.", "Topik 4: Analisis Respon Waktu - Mengkaji respon waktu sistem kontrol, termasuk waktu naik, waktu puncak, dan waktu settling serta metode analisis seperti langkah input dan respon frekuensi.", "Topik 5: Kestabilan Sistem - Menggunakan kriteria kestabilan (seperti kriteria Routh-Hurwitz dan Nyquist) untuk menentukan kestabilan sistem kontrol.", "Topik 6: Perancangan Sistem Kontrol Sederhana - Memperkenalkan teknik dasar dalam merancang sistem kontrol sederhana, termasuk PID controller dan aplikasinya.", "Topik 7: Simulasi Sistem Kontrol - Menggunakan perangkat lunak MATLAB/Simulink untuk mensimulasikan sistem kontrol dan menganalisis hasil simulasi.", "Topik 8: Presentasi Hasil Analisis - Teknik untuk mempresentasikan hasil analisis sistem kontrol, termasuk interpretasi data dan visualisasi hasil simulasi."], "description": "Mata kuliah Dasar Sistem Kontrol ini bertujuan untuk memberikan pemahaman fundamental tentang prinsip-prinsip dasar sistem kontrol yang diterapkan dalam berbagai bidang teknik. Materi yang akan dibahas mencakup model matematis sistem dinamis, analisis stabilitas, serta desain sistem kontrol umpan balik. Selain itu, mahasiswa akan diperkenalkan pada teknik pemodelan dan simulasi sistem kontrol menggunakan perangkat lunak yang relevan. Melalui mata kuliah ini, diharapkan mahasiswa dapat mengembangkan kemampuan analitis dan keterampilan praktis dalam merancang dan menganalisis sistem kontrol yang efisien, serta memahami aplikasi nyata dalam industri. Dengan demikian, mata kuliah ini menjadi landasan penting bagi mahasiswa yang berkarir di bidang teknik elektro, mekanika, dan otomasi.", "bahan_kajian": ["Topik 1: Pengenalan Sistem Kontrol - Menjelaskan konsep dasar sistem kontrol, jenis-jenis sistem kontrol (open-loop dan closed-loop), serta aplikasi dalam bidang teknik elektro.", "Topik 2: Blok Diagram dan Representasi Sistem - Memahami cara menggambar blok diagram sistem kontrol dan cara merepresentasikan sistem fisik ke dalam bentuk diagram blok.", "Topik 3: Pemodelan Matematis Sistem Dinamik - Mempelajari teknik pemodelan matematis untuk sistem mekanik dan elektrik, termasuk penggunaan persamaan diferensial.", "Topik 4: Analisis Respon Waktu - Mengkaji respon waktu sistem kontrol, termasuk waktu naik, waktu puncak, dan waktu settling serta metode analisis seperti langkah input dan respon frekuensi.", "Topik 5: Kestabilan Sistem - Menggunakan kriteria kestabilan (seperti kriteria Routh-Hurwitz dan Nyquist) untuk menentukan kestabilan sistem kontrol.", "Topik 6: Perancangan Sistem Kontrol Sederhana - Memperkenalkan teknik dasar dalam merancang sistem kontrol sederhana, termasuk PID controller dan aplikasinya.", "Topik 7: Simulasi Sistem Kontrol - Menggunakan perangkat lunak MATLAB/Simulink untuk mensimulasikan sistem kontrol dan menganalisis hasil simulasi.", "Topik 8: Presentasi Hasil Analisis - Teknik untuk mempresentasikan hasil analisis sistem kontrol, termasuk interpretasi data dan visualisasi hasil simulasi."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subC