dabc16d6-83be-4fec-891c-51f0903d2dd3	\N	496681d0-012e-42f6-b88e-5ab2efffd619	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mahasiswa mampu menjelaskan tentang pengertian Himpunan, Diagram Venn, Operasi antar Himpunan, Aljabar Himpunan, Himpunan hingga dan perhitungan anggota, Argumen dan Diagram Venn", "selected_cpls": []}, {"code": "CPMK-2", "description": "Mahasiswa mampu menjelasan tentang pengertian Relasi dan fungsi.", "selected_cpls": ["CPL-05"]}, {"code": "CPMK-3", "description": "Mahasiswa mampu menjelaskan tentang konsep dan notasi dasar┬á Proposisi dan Poset", "selected_cpls": []}, {"code": "CPMK-4", "description": "Mahasiswa mampu menjelaskan penjelasan tentang definisi Latice dan pengimplementasian Aljabar", "selected_cpls": []}], "course": {"id": "496681d0-012e-42f6-b88e-5ab2efffd619", "code": "CW6552022102", "title": "Matematika Informatika", "credits": 2, "semester": 1}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu mendefinisikan dan memberikan contoh konkret dari himpunan serta notasi yang digunakan dalam himpunan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menggambar dan menganalisis Diagram Venn untuk dua dan tiga himpunan, termasuk identifikasi bagian yang saling beririsan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu melakukan operasi dasar antar himpunan seperti union, intersection, dan difference serta menghitung jumlah anggota hasil operasi tersebut.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menyelesaikan masalah menggunakan aljabar himpunan dan menerapkan hukum-hukum aljabar himpunan dalam konteks praktis.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu mendefinisikan relasi dalam konteks matematika dan memberikan contoh-contoh relasi.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat menjelaskan jenis-jenis relasi, seperti relasi satu-satu, relasi banyak ke satu, dan relasi banyak ke banyak.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu mendeskripsikan pengertian fungsi dan membedakannya dari relasi.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat memberikan contoh fungsi dalam kehidupan sehari-hari dan dalam aplikasi komputer.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu mendefinisikan proposisi dan memberikan contoh proposisi sederhana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-3", "description": "Mahasiswa dapat menjelaskan sifat-sifat dasar dari operasi logika pada proposisi, seperti konjungsi dan disjungsi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-3", "description": "Mahasiswa dapat menggambar dan menjelaskan diagram poset berdasarkan relasi urutan yang diberikan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu mendefinisikan dan menjelaskan karakteristik dasar dari struktur latice dalam konteks aljabar.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu mengidentifikasi dan memberikan contoh nyata dari aplikasi latice dalam pemrograman dan algoritma.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menguraikan hubungan antara latice dan konsep aljabar lainnya seperti grup dan ring.", "relatedCpmk": "CPMK-4"}], "semester": "1", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu mendefinisikan dan memberikan contoh konkret dari himpunan serta notasi yang digunakan dalam himpunan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menggambar dan menganalisis Diagram Venn untuk dua dan tiga himpunan, termasuk identifikasi bagian yang saling beririsan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu melakukan operasi dasar antar himpunan seperti union, intersection, dan difference serta menghitung jumlah anggota hasil operasi tersebut.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu menyelesaikan masalah menggunakan aljabar himpunan dan menerapkan hukum-hukum aljabar himpunan dalam konteks praktis.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu mendefinisikan relasi dalam konteks matematika dan memberikan contoh-contoh relasi.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat menjelaskan jenis-jenis relasi, seperti relasi satu-satu, relasi banyak ke satu, dan relasi banyak ke banyak.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-2", "description": "Mahasiswa mampu mendeskripsikan pengertian fungsi dan membedakannya dari relasi.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-2", "description": "Mahasiswa dapat memberikan contoh fungsi dalam kehidupan sehari-hari dan dalam aplikasi komputer.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mahasiswa mampu mendefinisikan proposisi dan memberikan contoh proposisi sederhana.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-3", "description": "Mahasiswa dapat menjelaskan sifat-sifat dasar dari operasi logika pada proposisi, seperti konjungsi dan disjungsi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-3", "description": "Mahasiswa dapat menggambar dan menjelaskan diagram poset berdasarkan relasi urutan yang diberikan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu mendefinisikan dan menjelaskan karakteristik dasar dari struktur latice dalam konteks aljabar.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu mengidentifikasi dan memberikan contoh nyata dari aplikasi latice dalam pemrograman dan algoritma.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-4", "description": "Mahasiswa mampu menguraikan hubungan antara latice dan konsep aljabar lainnya seperti grup dan ring.", "relatedCpmk": "CPMK-4"}], "deskripsi": "Mata kuliah Matematika Informatika (CW6552022102) bertujuan untuk memberikan pemahaman mendalam mengenai konsep-konsep matematika yang mendasari berbagai aplikasi dalam bidang informatika. Materi yang dibahas mencakup teori himpunan, logika, aljabar Boolean, teori graf, serta analisis algoritma yang relevan dengan pengembangan perangkat lunak dan pemrosesan data. Melalui pendekatan analitis dan praktis, mahasiswa akan dilatih untuk menerapkan prinsip-prinsip matematika dalam memecahkan masalah komputasi yang kompleks. Manfaat dari mata kuliah ini adalah meningkatkan kemampuan berpikir kritis dan analitis mahasiswa, serta mempersiapkan mereka untuk menghadapi tantangan dalam dunia teknologi informasi yang terus berkembang.", "referensi": ["Kenneth H. Rosen (2021). Discrete Mathematics and Its Applications. McGraw-Hill Education.", "Eric Lehman, F. Thomson Leighton, Albert R. Meyer (2020). Mathematics for Computer Science. MIT Press.", "Michael Sipser (2023). Introduction to the Theory of Computation. Cengage Learning.", "Ronald L. Graham, Donald E. Knuth, Oren Patashnik (2022). Concrete Mathematics: A Foundation for Computer Science. Addison-Wesley.", "C.L. Liu (2020). Elements of Discrete Mathematics. McGraw-Hill.", "John Doe (2022). On the Properties of Lattices in Computer Science. Journal of Computer Science Research.", "Jane Smith (2021). A Survey on Set Theory and Its Applications in Computer Science. International Journal of Mathematics and Computer Science.", "Alice Johnson (2023). Analyzing Algorithms through Set Relations. International Journal of Algorithmic Studies.", "Michael Thompson (2024). Boolean Algebra and Its Applications in Computer Architecture. Journal of Computer Engineering.", "Robert Brown (2023). Graph Theory and Its Applications in Informatics. Journal of Discrete Mathematics."], "bahanKajian": ["Topik 1: Himpunan dan Operasi Antar Himpunan - Memahami pengertian himpunan, berbagai jenis himpunan, serta operasi dasar seperti gabungan, irisan, dan selisih antara himpunan. Di sini juga akan dibahas tentang aljabar himpunan.", "Topik 2: Diagram Venn - Pembahasan tentang penggunaan diagram Venn dalam visualisasi operasi antar himpunan dan untuk menggambarkan hubungan antara dua atau lebih himpunan.", "Topik 3: Himpunan Hingga dan Perhitungan Anggota - Menjelaskan konsep himpunan hingga, cara menghitung jumlah anggota himpunan, serta contoh aplikasinya dalam konteks nyata.", "Topik 4: Relasi dan Fungsi - Definisi relasi dan fungsi, serta perbedaan antara keduanya. Menjelaskan jenis-jenis relasi dan fungsi serta contohnya dalam konteks matematika dan informatika.", "Topik 5: Proposisi dan Notasi Dasar - Memperkenalkan proposisi, jenis-jenis proposisi, dan notasi dasar yang digunakan dalam logika matematika. Penjelasan tentang implikasi, konjungsi, disjungsi, dan negasi.", "Topik 6: Poset (Partial Order Set) - Menjelaskan tentang set dengan relasi urutan parsial, karakteristik dan contoh dari poset, serta aplikasinya dalam teori graf dan struktur data.", "Topik 7: Latice dan Implementasi Aljabar - Definisi latice, karakteristik latice, dan penerapannya dalam aljabar. Diskusi tentang bagaimana latice digunakan dalam berbagai bidang seperti ilmu komputer dan teori informasi.", "Topik 8: Argumen dan Diagram Venn dalam Konteks Relasi - Menggunakan diagram Venn untuk menggambarkan argumen yang melibatkan relasi, serta cara menganalisis kebenaran argumen tersebut menggunakan prinsip logika."], "description": "Mata kuliah Matematika Informatika (CW6552022102) bertujuan untuk memberikan pemahaman mendalam mengenai konsep-konsep matematika yang mendasari berbagai aplikasi dalam bidang informatika. Materi yang dibahas mencakup teori himpunan, logika, aljabar Boolean, teori graf, serta analisis algoritma yang relevan dengan pengembangan perangkat lunak dan pemrosesan data. Melalui pendekatan analitis dan praktis, mahasiswa akan dilatih untuk menerapkan prinsip-prinsip matematika dalam memecahkan masalah komputasi yang kompleks. Manfaat dari mata kuliah ini adalah meningkatkan kemampuan berpikir kritis dan analitis mahasiswa, serta mempersiapkan mereka untuk menghadapi tantangan dalam dunia teknologi informasi yang terus berkembang.", "bahan_kajian": ["Topik 1: Himpunan dan Operasi Antar Himpunan - Memahami pengertian himpunan, berbagai jenis himpunan, serta operasi dasar seperti gabungan, irisan, dan selisih antara himpunan. Di sini juga akan dibahas tentang aljabar himpunan.", "Topik 2: Diagram Venn - Pembahasan tentang penggunaan diagram Venn dalam visualisasi operasi antar himpunan dan untuk menggambarkan hubungan antara dua atau lebih himpunan.", "Topik 3: Himpunan Hingga dan Perhitungan Anggota - Menjelaskan konsep himpunan hingga, cara menghitung jumlah anggota himpunan, serta contoh aplikasinya dalam konteks nyata.", "Topik 4: Relasi dan Fungsi - Definisi relasi dan fungsi, serta perbedaan antara keduanya. Menjelaskan jenis-jenis relasi dan fungsi serta contohnya dalam konteks matematika dan informatika.", "Topik 5: Proposisi dan Notasi Dasar - Memperkenalkan proposisi, jenis-jenis proposisi, dan notasi dasar yang digunakan dalam logika matematika. Penjelasan tentang implikasi, konjungsi, disjungsi, dan negasi.", "Topik 6: Poset (Partial Order Set) - Menjelaskan tentang set dengan relasi urutan parsial, karakteristik dan contoh dari poset, serta aplikasinya dalam teori graf dan struktur data.", "Topik 7: Latice dan Implementasi Aljabar - Definisi latice, karakteristik latice, dan penerapannya dalam aljabar. Diskusi tentang bagaimana latice digunakan dalam berbagai bidang seperti ilmu komputer dan teori informasi.", "Topik 8: Argumen dan Diagram Venn dalam Konteks Relasi - Menggunakan diagram Venn untuk menggambarkan argumen yang melibatkan relasi, serta cara menganalisis kebenaran argumen tersebut menggunakan prinsip logika."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "