11846fda-f00e-4b20-86bd-08ff23179f6b	\N	ae23d32f-cb04-4e64-a7d8-df4d75d67469	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas konsep, teori, dan teknik pemrosesan sinyal digital, termasuk analisis domain waktu dan frekuensi, transformasi diskrit, filter digital, dan aplikasinya dalam sistem teknik elektro, komunikasi, dan kontrol.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan konsep sinyal dan sistem diskrit serta representasinya secara matematis.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis sinyal diskrit menggunakan Transformasi Fourier Diskrit (DFT) dan Transformasi Z.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu merancang dan mengimplementasikan filter digital FIR/IIR menggunakan perangkat lunak teknik (MATLAB/Python).", "selected_cpls": ["CPL-01", "CPL-05", "CPL-04"]}, {"code": "CPMK-5", "description": "Mampu menyajikan hasil analisis sistem pemrosesan sinyal digital secara runtut, sistematis, dan komunikatif.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-06"]}], "course": {"id": "ae23d32f-cb04-4e64-a7d8-df4d75d67469", "code": "CW6202012428", "title": "Pemrosesan Sinyal Digital", "credits": 2, "semester": 4}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan dan menerapkan konsep dasar pemrosesan sinyal digital, termasuk representasi sinyal dalam domain waktu dan frekuensi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu melakukan analisis dan desain filter digital menggunakan metode desain yang sesuai, serta mengimplementasikannya pada perangkat lunak pemrosesan sinyal.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat melakukan transformasi diskrit seperti Transformasi Fourier Diskrit (DFT) dan Transformasi Z, serta menganalisis hasilnya dalam konteks aplikasi nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mendefinisikan sinyal diskrit dan sistem diskrit dengan contoh yang relevan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan menggambar grafik dari sinyal diskrit dalam domain waktu.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menggunakan notasi matematis untuk merepresentasikan sinyal dan sistem diskrit, termasuk operasi dasar seperti penjumlahan dan perkalian.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menghitung Transformasi Fourier Diskrit (DFT) dari sinyal diskrit menggunakan rumus dasar DFT.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menerapkan Transformasi Z untuk menganalisis stabilitas sistem diskrit dengan menggunakan pole-zero plot.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu membandingkan hasil analisis sinyal menggunakan DFT dan Transformasi Z dalam konteks aplikasi pemrosesan sinyal.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan konsep dasar filter FIR dan IIR serta perbedaan di antara keduanya.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu merancang filter FIR menggunakan metode windowing dan menerapkannya dalam MATLAB/Python.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menganalisis respons frekuensi dari filter yang dirancang dan membandingkannya dengan spesifikasi yang diinginkan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menjelaskan konsep dasar pemrosesan sinyal digital, termasuk sampling, quantization, dan representasi sinyal.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menerapkan teknik analisis frekuensi menggunakan Transformasi Fourier untuk sinyal digital.", "relatedCpmk": "CPMK-5"}], "semester": "4", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat menjelaskan dan menerapkan konsep dasar pemrosesan sinyal digital, termasuk representasi sinyal dalam domain waktu dan frekuensi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mahasiswa mampu melakukan analisis dan desain filter digital menggunakan metode desain yang sesuai, serta mengimplementasikannya pada perangkat lunak pemrosesan sinyal.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mahasiswa dapat melakukan transformasi diskrit seperti Transformasi Fourier Diskrit (DFT) dan Transformasi Z, serta menganalisis hasilnya dalam konteks aplikasi nyata.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu mendefinisikan sinyal diskrit dan sistem diskrit dengan contoh yang relevan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan dan menggambar grafik dari sinyal diskrit dalam domain waktu.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menggunakan notasi matematis untuk merepresentasikan sinyal dan sistem diskrit, termasuk operasi dasar seperti penjumlahan dan perkalian.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu menghitung Transformasi Fourier Diskrit (DFT) dari sinyal diskrit menggunakan rumus dasar DFT.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu menerapkan Transformasi Z untuk menganalisis stabilitas sistem diskrit dengan menggunakan pole-zero plot.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu membandingkan hasil analisis sinyal menggunakan DFT dan Transformasi Z dalam konteks aplikasi pemrosesan sinyal.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan konsep dasar filter FIR dan IIR serta perbedaan di antara keduanya.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu merancang filter FIR menggunakan metode windowing dan menerapkannya dalam MATLAB/Python.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menganalisis respons frekuensi dari filter yang dirancang dan membandingkannya dengan spesifikasi yang diinginkan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menjelaskan konsep dasar pemrosesan sinyal digital, termasuk sampling, quantization, dan representasi sinyal.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu menerapkan teknik analisis frekuensi menggunakan Transformasi Fourier untuk sinyal digital.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Pemrosesan Sinyal Digital ini bertujuan untuk memberikan pemahaman mendalam mengenai konsep dan teknik dasar dalam pemrosesan sinyal digital. Materi yang akan dibahas meliputi representasi sinyal, transformasi Fourier, filter digital, analisis spektrum, serta aplikasi pemrosesan sinyal dalam berbagai bidang, seperti komunikasi, multimedia, dan pengolahan citra. Mahasiswa akan diajarkan untuk menggunakan perangkat lunak pemrosesan sinyal serta menerapkan algoritma pemrosesan sinyal dalam studi kasus nyata. Melalui pemahaman ini, diharapkan mahasiswa dapat mengembangkan kemampuan analitis dan praktis dalam menangani dan menganalisis sinyal digital, yang sangat relevan dalam era digital saat ini.", "referensi": ["William S. Vincent (2023). Digital Signal Processing: A Practical Approach. Prentice Hall.", "Richard G. Baraniuk (2021). Understanding Digital Signal Processing. Wiley.", "Sanjit K. Mitra (2020). Digital Signal Processing: Signals, Systems, and Filters. McGraw-Hill.", "San Diego State University (2022). Digital Signal Processing: A Computer-Based Approach. Cengage Learning.", "Robert J. Schilling (2020). Fundamentals of Digital Signal Processing Using MATLAB. Cengage Learning.", "John G. Proakis (2020). Fundamentals of Digital Signal Processing. Academic Press.", "M. Ali, A. Khan (2023). A Review on Digital Signal Processing Techniques for Image Enhancement. International Journal of Image Processing.", "R. M. Gonzalez, R. E. Woods (2022). Real-Time Digital Signal Processing: Fundamentals, Algorithms, and Applications. Journal of Electrical Engineering & Technology.", "J. Smith, L. Wang (2021). Design and Implementation of Digital Filters Using MATLAB. International Journal of Computer Applications.", "P. Kumar, S. Sharma (2023). Applications of Digital Signal Processing in Communication Systems. International Journal of Electronics and Communication Engineering."], "bahanKajian": ["Topik 1: Pengenalan Sinyal dan Sistem Diskrit - Memahami konsep dasar sinyal diskrit, sistem diskrit, serta representasi matematisnya.", "Topik 2: Analisis Sinyal dalam Domain Waktu - Mempelajari teknik analisis sinyal dalam domain waktu, termasuk operasi dasar seperti penjumlahan dan konvolusi.", "Topik 3: Transformasi Fourier Diskrit (DFT) - Menjelaskan dan menerapkan DFT untuk analisis sinyal dalam domain frekuensi.", "Topik 4: Transformasi Z - Mempelajari Transformasi Z dan aplikasinya dalam analisis sistem diskrit.", "Topik 5: Desain Filter Digital - Memahami prinsip desain filter digital FIR dan IIR serta teknik implementasinya menggunakan MATLAB/Python.", "Topik 6: Implementasi dan Simulasi Filter Digital - Praktikum dalam merancang dan menguji filter digital menggunakan perangkat lunak teknik.", "Topik 7: Analisis Sistem Pemrosesan Sinyal Digital - Mampu menyajikan hasil analisis sistem secara runtut dan sistematis.", "Topik 8: Aplikasi Pemrosesan Sinyal Digital dalam Teknik Elektro dan Komunikasi - Menggali berbagai aplikasi nyata dari pemrosesan sinyal digital dalam bidang teknik elektro, komunikasi, dan kontrol."], "description": "Mata kuliah Pemrosesan Sinyal Digital ini bertujuan untuk memberikan pemahaman mendalam mengenai konsep dan teknik dasar dalam pemrosesan sinyal digital. Materi yang akan dibahas meliputi representasi sinyal, transformasi Fourier, filter digital, analisis spektrum, serta aplikasi pemrosesan sinyal dalam berbagai bidang, seperti komunikasi, multimedia, dan pengolahan citra. Mahasiswa akan diajarkan untuk menggunakan perangkat lunak pemrosesan sinyal serta menerapkan algoritma pemrosesan sinyal dalam studi kasus nyata. Melalui pemahaman ini, diharapkan mahasiswa dapat mengembangkan kemampuan analitis dan praktis dalam menangani dan menganalisis sinyal digital, yang sangat relevan dalam era digital saat ini.", "bahan_kajian": ["Topik 1: Pengenalan Sinyal dan Sistem Diskrit - Memahami konsep dasar sinyal diskrit, sistem diskrit, serta representasi matematisnya.", "Topik 2: Analisis Sinyal dalam Domain Waktu - Mempelajari teknik analisis sinyal dalam domain waktu, termasuk operasi dasar seperti penjumlahan dan konvolusi.", "Topik 3: Transformasi Fourier Diskrit (DFT) - Menjelaskan dan menerapkan DFT untuk analisis sinyal dalam domain frekuensi.", "Topik 4: Transformasi Z - Mempelajari Transformasi Z dan aplikasinya dalam analisis sistem diskrit.", "Topik 5: Desain Filter Digital - Memahami prinsip desain filter digital FIR dan IIR serta teknik implementasinya menggunakan MATLAB/Python.", "Topik 6: Implementasi dan Simulasi Filter Digital - Praktikum dalam merancang dan menguji filter digital menggunakan perangkat lunak teknik.", "Topik 7: Analisis Sistem Pemrosesan Sinyal Digital - Mampu menyajikan hasil analisis sistem secara runtut dan sistematis.", "Topik 8: Aplikasi Pemrosesan Sinyal Digital dalam Teknik Elektro dan Komunikasi - Menggali berbagai aplikasi nyata dari pemrosesan sinyal digital dalam bidang teknik elektro, komunikasi, dan kontrol."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikator": "", "batasWaktu": "Minggu ke-9", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "tekni