e58edb73-42c5-4b06-ac3e-db8fa0898503	\N	7c8fc745-6646-4554-b0c6-51a948d15f04	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas prinsip kerja, karakteristik, dan aplikasi mesin listrik arus searah (DC) dan arus bolak-balik (AC), termasuk transformator, motor, dan generator, serta analisis kinerja dan efisiensinya dalam sistem tenaga listrik.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-05"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar elektromagnetik, konstruksi, dan prinsip kerja mesin listrik DC, AC, serta transformator.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis karakteristik, rugi-rugi daya, dan efisiensi berbagai jenis mesin listrik berdasarkan data pengujian atau simulasi.", "selected_cpls": ["CPL-01", "CPL-03", "CPL-04", "CPL-05"]}, {"code": "CPMK-4", "description": "Mampu melakukan pengujian performa mesin listrik di laboratorium dengan prosedur keselamatan yang tepat.", "selected_cpls": ["CPL-03", "CPL-02"]}], "course": {"id": "7c8fc745-6646-4554-b0c6-51a948d15f04", "code": "CW62020135003L", "title": "Mesin Listrik", "credits": 3, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip kerja dan karakteristik mesin listrik arus searah (DC) dan arus bolak-balik (AC)", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Dapat menganalisis kinerja motor dan generator dalam sistem tenaga listrik berdasarkan data yang diberikan", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu menghitung efisiensi transformator dan motor dalam kondisi operasi yang berbeda", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-1", "description": "Dapat mengidentifikasi aplikasi praktis mesin listrik dalam industri dan sistem tenaga listrik", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Menjelaskan hukum Faraday dan prinsip induksi elektromagnetik dalam konteks mesin listrik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Menganalisis konstruksi dan komponen utama dalam mesin listrik DC dan AC.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-2", "description": "Menjelaskan prinsip kerja dan fungsi dari transformator dalam distribusi energi listrik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-2", "description": "Membandingkan karakteristik dan aplikasi mesin listrik DC dan AC.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan menjelaskan karakteristik dasar dari berbagai jenis mesin listrik, seperti motor induksi, motor DC, dan generator.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-3", "description": "Mampu menghitung rugi-rugi daya yang terjadi pada mesin listrik berdasarkan data pengujian, seperti rugi-rugi tembaga dan rugi-rugi besi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis dan membandingkan efisiensi berbagai jenis mesin listrik menggunakan data simulasi dan pengujian nyata.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mengidentifikasi dan menjelaskan prosedur keselamatan yang diperlukan sebelum melakukan pengujian mesin listrik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-4", "description": "Melakukan pengukuran parameter performa mesin listrik seperti tegangan, arus, dan daya dengan menggunakan alat ukur yang tepat.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-4", "description": "Mampu menganalisis hasil pengujian performa mesin listrik dan menyusun laporan yang mencakup kesimpulan serta rekomendasi perbaikan.", "relatedCpmk": "CPMK-4"}], "semester": "5", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan prinsip kerja dan karakteristik mesin listrik arus searah (DC) dan arus bolak-balik (AC)", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Dapat menganalisis kinerja motor dan generator dalam sistem tenaga listrik berdasarkan data yang diberikan", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu menghitung efisiensi transformator dan motor dalam kondisi operasi yang berbeda", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-1", "description": "Dapat mengidentifikasi aplikasi praktis mesin listrik dalam industri dan sistem tenaga listrik", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Menjelaskan hukum Faraday dan prinsip induksi elektromagnetik dalam konteks mesin listrik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Menganalisis konstruksi dan komponen utama dalam mesin listrik DC dan AC.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-2", "description": "Menjelaskan prinsip kerja dan fungsi dari transformator dalam distribusi energi listrik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-2", "description": "Membandingkan karakteristik dan aplikasi mesin listrik DC dan AC.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan menjelaskan karakteristik dasar dari berbagai jenis mesin listrik, seperti motor induksi, motor DC, dan generator.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-3", "description": "Mampu menghitung rugi-rugi daya yang terjadi pada mesin listrik berdasarkan data pengujian, seperti rugi-rugi tembaga dan rugi-rugi besi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-3", "description": "Mampu menganalisis dan membandingkan efisiensi berbagai jenis mesin listrik menggunakan data simulasi dan pengujian nyata.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mengidentifikasi dan menjelaskan prosedur keselamatan yang diperlukan sebelum melakukan pengujian mesin listrik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-4", "description": "Melakukan pengukuran parameter performa mesin listrik seperti tegangan, arus, dan daya dengan menggunakan alat ukur yang tepat.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-4", "description": "Mampu menganalisis hasil pengujian performa mesin listrik dan menyusun laporan yang mencakup kesimpulan serta rekomendasi perbaikan.", "relatedCpmk": "CPMK-4"}], "deskripsi": "Mata kuliah Mesin Listrik merupakan kajian yang bertujuan untuk memberikan pemahaman mendalam mengenai prinsip kerja, konstruksi, dan aplikasi mesin listrik dalam sistem kelistrikan. Materi yang dibahas mencakup jenis-jenis mesin listrik seperti motor dan generator, karakteristik operasional, serta analisis performa mesin dalam berbagai kondisi beban. Selain itu, mahasiswa akan mempelajari teknik-teknik pengendalian dan pemeliharaan mesin listrik untuk meningkatkan efisiensi dan keandalan. Melalui pembelajaran ini, diharapkan mahasiswa dapat mengembangkan keterampilan praktis dan teoritis yang diperlukan untuk merancang, menganalisis, dan mengoptimalkan sistem mesin listrik, sehingga dapat berkontribusi secara signifikan dalam bidang teknik elektro dan industri terkait.", "referensi": ["Stephen J. Chapman (2021). Electric Machinery Fundamentals. McGraw-Hill Education.", "D. P. Kothari and I. J. Nagrath (2020). Electrical Machines, Drives and Power Systems. McGraw-Hill Education.", "P. S. Bhimbra (2022). Theory of Electric Machines. Khanna Publishers.", "Austin Hughes and Bill Drury (2020). Electric Motors and Drives: Fundamentals, Types and Applications. Newnes.", "B. M. Weedy and B. J. Cory (2023). Electric Power Systems. Wiley.", "A. Z. El-Sharkawy (2021). Performance Analysis of Electrical Machines. IEEE Transactions on Industry Applications.", "M. A. El-Sharkawy and A. S. Al-Salaymeh (2022). Efficiency Optimization of Electric Machines. Journal of Electrical Engineering & Technology.", "L. Huang, Y. Liu, and J. Wang (2023). Recent Advances in Electric Machines. International Journal of Electric Power and Energy Systems.", "R. K. Gupta (2022). Simulation of Electric Machines Using MATLAB. Journal of Simulation and Modeling.", "S. M. M. Ali and R. R. R. Rahman (2023). Advancements in Electric Machine Technologies. Journal of Power Electronics."], "bahanKajian": ["Topik 1: Prinsip Kerja Mesin Listrik DC - Membahas tentang dasar-dasar elektromagnetik, konstruksi, dan prinsip kerja mesin listrik arus searah, termasuk komponen utama dan fungsinya.", "Topik 2: Karakteristik dan Aplikasi Mesin Listrik DC - Mengupas karakteristik operasional mesin listrik DC dan aplikasi praktisnya dalam berbagai bidang industri.", "Topik 3: Prinsip Kerja Mesin Listrik AC - Menjelaskan prinsip dasar dan konstruksi mesin listrik arus bolak-balik, serta perbedaan dengan mesin DC.", "Topik 4: Transformator dan Aplikasinya - Menganalisis cara kerja transformator, jenis-jenisnya, serta perannya dalam sistem tenaga listrik.", "Topik 5: Rugi-rugi Daya dan Efisiensi Mesin Listrik - Mengidentifikasi dan menganalisis rugi-rugi daya pada mesin listrik serta cara mengukur efisiensi dengan data pengujian.", "Topik 6: Pengujian Performa Mesin Listrik - Memahami prosedur pengujian performa mesin listrik di laboratorium, termasuk teknik dan alat yang digunakan, serta prosedur keselamatan.", "Topik 7: Simulasi dan Analisis Kinerja Mesin Listrik - Menggunakan software simulasi untuk menganalisis kinerja dan efisiensi berbagai jenis mesin listrik.", "Topik 8: Tren dan Inovasi dalam Teknologi Mesin Listrik - Membahas perkembangan terbaru dan inovasi dalam teknologi mesin listrik serta dampaknya terhadap efisiensi energi."], "description": "Mata kuliah Mesin Listrik merupakan kajian yang bertujuan untuk memberikan pemahaman mendalam mengenai prinsip kerja, konstruksi, dan aplikasi mesin listrik dalam sistem kelistrikan. Materi yang dibahas mencakup jenis-jenis mesin listrik seperti motor dan generator, karakteristik operasional, serta analisis performa mesin dalam berbagai kondisi beban. Selain itu, mahasiswa akan mempelajari teknik-teknik pengendalian dan pemeliharaan mesin listrik untuk meningkatkan efisiensi dan keandalan. Melalui pembelajaran ini, diharapkan mahasiswa dapat mengembangkan keterampilan praktis dan teoritis yang diperlukan untuk merancang, menganalisis, dan mengoptimalkan sistem mesin listrik, sehingga dapat berkontribusi secara signifikan dalam bidang teknik elektro dan industri terkait.", "bahan_kajian": ["Topik 1: Prinsip Kerja Mesin Listrik DC - Membahas tentang dasar-dasar elektromagnetik, konstruksi, dan prinsip kerja mesin listrik arus searah, termasuk komponen utama dan fungsinya.", "Topik 2: Karakteristik dan Aplikasi Mesin Listrik DC - Mengupas karakteristik operasional mesin listrik DC dan aplikasi praktisnya dalam berbagai bidang industri.", "Topik 3: Prinsip Kerja Mesin Listrik AC - Menjelaskan prinsip dasar dan konstruksi mesin listrik arus bolak-balik, serta perbedaan dengan mesin DC.", "Topik 4: Transformator dan Aplikasinya - Menganalisis cara kerja transformator, jenis-jenisnya, serta perannya dalam sistem tenaga listrik.", "Topik 5: Rugi-rugi Daya dan Efisiensi Mesin Listrik - Mengidentifikasi dan menganalisis rugi-rugi daya pada mesin listrik serta cara mengukur efisiensi dengan data pengujian.", "Topik 6: Pengujian Performa Mesin Listrik - Memahami prosedur pengujian performa mesin listrik di laboratorium, termasuk teknik dan alat yang digunakan, serta prosedur keselamatan.", "Topik 7: Simulasi dan Analisis Kinerja Mesin Listrik - Menggunakan software simulasi untuk menganalisis kinerja dan efisiensi berbagai jenis mesin listrik.", "Topik 8: Tren dan Inovasi dalam Teknologi Mesin Listrik - Membahas perkembangan terbaru dan inovasi dalam teknologi mesin listrik serta dampaknya terhadap efisiensi energi."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikator": "", "batasWaktu": "Minggu ke-9", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", 