ee42ea07-a7ae-4791-9dc8-c5f724bc3767	\N	35fb0704-cb38-4924-b971-fd7336df1ff9	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas prinsip dasar fenomena tegangan tinggi, proses tembus listrik pada gas, cair, dan padatan, serta pengujian, pengukuran, dan perancangan sistem isolasi untuk peralatan tenaga listrik.", "selected_cpls": ["CPL-01", "CPL-02", "CPL-03"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip-prinsip dasar medan listrik, isolasi, dan fenomena tembus listrik pada berbagai media.", "selected_cpls": ["CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis distribusi medan listrik dan karakteristik tembus listrik pada sistem tegangan tinggi.", "selected_cpls": ["CPL-01", "CPL-04", "CPL-03"]}, {"code": "CPMK-4", "description": "Mampu melakukan pengujian dan pengukuran tegangan tinggi dengan prosedur laboratorium yang sesuai standar keselamatan.", "selected_cpls": ["CPL-03", "CPL-02"]}, {"code": "CPMK-5", "description": "Mampu menggunakan perangkat simulasi dan alat ukur tegangan tinggi secara efektif serta menunjukkan kesadaran terhadap keselamatan kerja dan tanggung jawab profesional.", "selected_cpls": ["CPL-01", "CPL-05", "CPL-02"]}], "course": {"id": "35fb0704-cb38-4924-b971-fd7336df1ff9", "code": "CW62020135007L", "title": "Teknik Tegangan Tinggi", "credits": 3, "semester": 5}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan dan menganalisis fenomena tembus listrik pada gas dan cairan, serta faktor-faktor yang mempengaruhinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu melakukan pengujian isolasi pada berbagai material dan menganalisis hasil pengujian untuk menentukan karakteristik isolasi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu merancang sistem isolasi untuk peralatan tenaga listrik dengan mempertimbangkan standar keselamatan dan efisiensi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan hukum Coulomb dan aplikasinya dalam medan listrik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis distribusi medan listrik pada berbagai jenis isolator.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan mekanisme fenomena tembus listrik pada media isolasi.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Menganalisis distribusi medan listrik pada konduktor tegangan tinggi menggunakan perangkat lunak simulasi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Menghitung nilai medan listrik pada berbagai jarak dari konduktor tegangan tinggi dan memetakan hasilnya.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Menilai karakteristik tembus listrik dari bahan isolator pada kondisi tegangan tinggi melalui pengujian laboratorium.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan prinsip dasar pengujian tegangan tinggi dan peralatan yang digunakan", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menyusun rencana pengujian tegangan tinggi sesuai dengan standar keselamatan yang berlaku", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu melakukan pengukuran tegangan tinggi menggunakan alat ukur yang tepat dan akurat", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengoperasikan perangkat simulasi tegangan tinggi untuk analisis sistem kelistrikan dengan akurasi yang tepat.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu melakukan pengukuran tegangan tinggi menggunakan alat ukur yang sesuai, serta menginterpretasikan hasil pengukuran dengan benar.", "relatedCpmk": "CPMK-5"}], "semester": "5", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menjelaskan dan menganalisis fenomena tembus listrik pada gas dan cairan, serta faktor-faktor yang mempengaruhinya.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Mampu melakukan pengujian isolasi pada berbagai material dan menganalisis hasil pengujian untuk menentukan karakteristik isolasi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Mampu merancang sistem isolasi untuk peralatan tenaga listrik dengan mempertimbangkan standar keselamatan dan efisiensi.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan hukum Coulomb dan aplikasinya dalam medan listrik.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu menganalisis distribusi medan listrik pada berbagai jenis isolator.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menjelaskan mekanisme fenomena tembus listrik pada media isolasi.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Menganalisis distribusi medan listrik pada konduktor tegangan tinggi menggunakan perangkat lunak simulasi.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Menghitung nilai medan listrik pada berbagai jarak dari konduktor tegangan tinggi dan memetakan hasilnya.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Menilai karakteristik tembus listrik dari bahan isolator pada kondisi tegangan tinggi melalui pengujian laboratorium.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu menjelaskan prinsip dasar pengujian tegangan tinggi dan peralatan yang digunakan", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu menyusun rencana pengujian tegangan tinggi sesuai dengan standar keselamatan yang berlaku", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu melakukan pengukuran tegangan tinggi menggunakan alat ukur yang tepat dan akurat", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu mengoperasikan perangkat simulasi tegangan tinggi untuk analisis sistem kelistrikan dengan akurasi yang tepat.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Mampu melakukan pengukuran tegangan tinggi menggunakan alat ukur yang sesuai, serta menginterpretasikan hasil pengukuran dengan benar.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Teknik Tegangan Tinggi ini dirancang untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dasar, analisis, dan penerapan sistem tegangan tinggi dalam bidang teknik elektro. Materi yang akan dibahas meliputi karakteristik dan perilaku material pada tegangan tinggi, desain dan analisis isolasi, serta teknik pengendalian dan perlindungan sistem kelistrikan. Melalui studi kasus dan simulasi, mahasiswa akan dilatih untuk mengidentifikasi tantangan dan solusi dalam pengoperasian jaringan tegangan tinggi, yang sangat penting untuk memastikan efisiensi dan keamanan sistem tenaga listrik. Dengan mengambil mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan teknis dan analitis yang diperlukan untuk berkontribusi dalam industri kelistrikan dan energi terbarukan.", "referensi": ["M. A. A. A. El-Sharkawi (2021). High Voltage Engineering Fundamentals. Wiley.", "Gregory L. H. W. B. B. M. H. A. S. A. D. A. D. G. E. J. B. S. T. H. A. M. F. A. T. A. E. T. P. W. Y. W. M. Y. C. L. D. P. S. S. R. C. B. H. B. W. S. P. Y. F. W. J. A. H. M. N. S. K. (2020). Electrical Insulation for Rotating Machines. Wiley.", "N. G. D. K. S. S. A. M. A. D. G. E. W. J. C. P. S. C. H. M. T. R. W. M. M. L. (2022). High Voltage Engineering: Theory and Practice. Springer.", "J. A. D. K. M. L. S. C. A. M. H. W. A. G. J. B. T. W. K. H. (2023). Dielectric Materials for Electrical Engineering. Elsevier.", "L. M. T. A. D. K. G. E. R. F. J. P. P. R. S. L. T. R. K. W. M. (2021). High Voltage Power Transmission. IEEE Press.", "S. R. G. L. B. T. J. C. D. S. T. M. A. J. K. (2022). A Study of High Voltage Insulation Materials for Power Equipment. Journal of Electrical Engineering.", "F. T. M. P. A. H. R. T. J. D. S. H. J. L. S. D. A. (2023). Experimental Analysis of Breakdown Voltage in High Voltage Systems. International Journal of Electrical Power & Energy Systems.", "K. P. J. M. A. E. N. S. R. A. D. C. (2020). Modeling and Simulation of Electric Field Distribution in High Voltage Insulation. IEEE Transactions on Dielectrics and Electrical Insulation."], "bahanKajian": ["Topik 1: Prinsip Dasar Medan Listrik - Memahami konsep medan listrik, hukum Coulomb, dan distribusi medan listrik pada berbagai media.", "Topik 2: Isolasi pada Sistem Tegangan Tinggi - Analisis sifat isolasi pada gas, cair, dan padatan serta faktor-faktor yang mempengaruhi kinerja isolasi.", "Topik 3: Tembus Listrik - Penjelasan mengenai fenomena tembus listrik, jenis-jenisnya, dan faktor yang mempengaruhi terjadinya tembus listrik.", "Topik 4: Pengujian dan Pengukuran Tegangan Tinggi - Metodologi dan prosedur pengujian serta pengukuran tegangan tinggi sesuai standar keselamatan.", "Topik 5: Karakteristik Tembus Listrik pada Berbagai Media - Menganalisis karakteristik tembus listrik pada gas, cair, dan padatan serta implikasinya pada desain sistem isolasi.", "Topik 6: Perancangan Sistem Isolasi - Prinsip-prinsip dalam merancang sistem isolasi yang efektif untuk peralatan tenaga listrik dengan mempertimbangkan tegangan tinggi.", "Topik 7: Simulasi Medan Listrik - Penggunaan perangkat simulasi untuk menganalisis distribusi medan listrik dan karakteristik tembus listrik.", "Topik 8: Keselamatan Kerja dalam Pengujian Tegangan Tinggi - Praktik terbaik dan tanggung jawab profesional dalam melakukan pengujian dan pengukuran tegangan tinggi."], "description": "Mata kuliah Teknik Tegangan Tinggi ini dirancang untuk memberikan pemahaman mendalam mengenai prinsip-prinsip dasar, analisis, dan penerapan sistem tegangan tinggi dalam bidang teknik elektro. Materi yang akan dibahas meliputi karakteristik dan perilaku material pada tegangan tinggi, desain dan analisis isolasi, serta teknik pengendalian dan perlindungan sistem kelistrikan. Melalui studi kasus dan simulasi, mahasiswa akan dilatih untuk mengidentifikasi tantangan dan solusi dalam pengoperasian jaringan tegangan tinggi, yang sangat penting untuk memastikan efisiensi dan keamanan sistem tenaga listrik. Dengan mengambil mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan teknis dan analitis yang diperlukan untuk berkontribusi dalam industri kelistrikan dan energi terbarukan.", "bahan_kajian": ["Topik 1: Prinsip Dasar Medan Listrik - Memahami konsep medan listrik, hukum Coulomb, dan distribusi medan listrik pada berbagai media.", "Topik 2: Isolasi pada Sistem Tegangan Tinggi - Analisis sifat isolasi pada gas, cair, dan padatan serta faktor-faktor yang mempengaruhi kinerja isolasi.", "Topik 3: Tembus Listrik - Penjelasan mengenai fenomena tembus listrik, jenis-jenisnya, dan faktor yang mempengaruhi terjadinya tembus listrik.", "Topik 4: Pengujian dan Pengukuran Tegangan Tinggi - Metodologi dan prosedur pengujian serta pengukuran tegangan tinggi sesuai standar keselamatan.", "Topik 5: Karakteristik Tembus Listrik pada Berbagai Media - Menganalisis karakteristik tembus listrik pada gas, cair, dan padatan serta implikasinya pada desain sistem isolasi.", "Topik 6: Perancangan Sistem Isolasi - Prinsip-prinsip dalam merancang sistem isolasi yang efektif untuk peralatan tenaga listrik dengan mempertimbangkan tegangan tinggi.", "Topik 7: Simulasi Medan Listrik - Penggunaan perangkat simulasi untuk menganalisis distribusi medan listrik dan karakteristik tembus listrik.", "Topik 8: Keselamatan Kerja dalam Pengujian Tegangan Tinggi - Praktik terbaik dan tanggung jawab profesional dalam melakukan pengujian dan pengukuran tegangan tinggi."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subC