80a7a396-e864-4d5b-9489-6a0da5037c4f	\N	c7397c62-a4da-4736-8c00-e9c6e86cdd30	\N	draft	{"cpmk": [{"code": "CPMK-1", "description": "Mata kuliah ini membahas prinsip-prinsip perencanaan, pelaksanaan, dan pengendalian proyek teknik serta penerapan sistem manajemen keselamatan dan kesehatan kerja (K3) untuk menjamin efektivitas, efisiensi, dan keamanan dalam pelaksanaan proyek keteknikan.", "selected_cpls": ["CPL-02", "CPL-07", "CPL-09"]}, {"code": "CPMK-2", "description": "Mampu menjelaskan prinsip dasar manajemen proyek teknik, termasuk perencanaan, penjadwalan, pengendalian, serta evaluasi proyek.", "selected_cpls": ["CPL-07", "CPL-01", "CPL-04"]}, {"code": "CPMK-3", "description": "Mampu menganalisis kebutuhan sumber daya, risiko, serta jadwal proyek menggunakan metode manajemen.", "selected_cpls": ["CPL-07", "CPL-04"]}, {"code": "CPMK-4", "description": "Mampu menerapkan prinsip keselamatan dan kesehatan kerja (K3) serta standar/peraturan terkait dalam perencanaan dan pelaksanaan proyek teknik.", "selected_cpls": ["CPL-02", "CPL-09"]}, {"code": "CPMK-5", "description": "Mampu berkomunikasi efektif, bekerja dalam tim multidisiplin, serta menunjukkan etika profesi, tanggung jawab sosial, dan sikap profesional dalam penyelesaian tugas proyek.", "selected_cpls": ["CPL-06", "CPL-08", "CPL-09"]}], "course": {"id": "c7397c62-a4da-4736-8c00-e9c6e86cdd30", "code": "CW6202012632", "title": "Manajemen Proyek dan Keselamatan Kerja", "credits": 2, "semester": 6}, "subCpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menganalisis dan merancang rencana proyek teknik yang mencakup estimasi biaya, waktu, dan sumber daya yang dibutuhkan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Dapat mengimplementasikan teknik pengendalian proyek untuk memastikan jadwal dan anggaran proyek tetap sesuai rencana.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan dan menerapkan prosedur manajemen keselamatan kerja (K3) dalam setiap tahap pelaksanaan proyek teknik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menyusun rencana proyek yang mencakup tujuan, ruang lingkup, dan sumber daya yang diperlukan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu membuat diagram Gantt untuk penjadwalan aktivitas dalam proyek.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menerapkan teknik pengendalian proyek untuk memantau kemajuan dan biaya secara efektif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mendokumentasikan sumber daya yang diperlukan untuk proyek, termasuk tenaga kerja, material, dan peralatan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu melakukan analisis risiko proyek dengan menggunakan metode SWOT dan matriks risiko untuk mengidentifikasi potensi masalah.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menyusun jadwal proyek menggunakan teknik PERT dan CPM untuk mengoptimalkan waktu penyelesaian.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menganalisis risiko K3 dalam setiap tahap perencanaan proyek teknik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu merancang rencana mitigasi risiko K3 yang sesuai dengan standar dan peraturan yang berlaku.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menerapkan prosedur keselamatan kerja di lokasi proyek sesuai dengan regulasi K3 yang relevan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menyusun dan menyampaikan presentasi proyek secara jelas dan sistematis kepada tim dan stakeholder.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Berpartisipasi aktif dalam diskusi kelompok dengan memberikan masukan konstruktif dan mendengarkan pendapat anggota tim lainnya.", "relatedCpmk": "CPMK-5"}], "semester": "6", "sub_cpmk": [{"code": "Sub-CPMK-1", "cpmk_id": "CPMK-1", "description": "Mampu menganalisis dan merancang rencana proyek teknik yang mencakup estimasi biaya, waktu, dan sumber daya yang dibutuhkan.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-2", "cpmk_id": "CPMK-1", "description": "Dapat mengimplementasikan teknik pengendalian proyek untuk memastikan jadwal dan anggaran proyek tetap sesuai rencana.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-3", "cpmk_id": "CPMK-1", "description": "Menjelaskan dan menerapkan prosedur manajemen keselamatan kerja (K3) dalam setiap tahap pelaksanaan proyek teknik.", "relatedCpmk": "CPMK-1"}, {"code": "Sub-CPMK-4", "cpmk_id": "CPMK-2", "description": "Mampu menyusun rencana proyek yang mencakup tujuan, ruang lingkup, dan sumber daya yang diperlukan.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-5", "cpmk_id": "CPMK-2", "description": "Mampu membuat diagram Gantt untuk penjadwalan aktivitas dalam proyek.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-6", "cpmk_id": "CPMK-2", "description": "Mampu menerapkan teknik pengendalian proyek untuk memantau kemajuan dan biaya secara efektif.", "relatedCpmk": "CPMK-2"}, {"code": "Sub-CPMK-7", "cpmk_id": "CPMK-3", "description": "Mampu mengidentifikasi dan mendokumentasikan sumber daya yang diperlukan untuk proyek, termasuk tenaga kerja, material, dan peralatan.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-8", "cpmk_id": "CPMK-3", "description": "Mampu melakukan analisis risiko proyek dengan menggunakan metode SWOT dan matriks risiko untuk mengidentifikasi potensi masalah.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-9", "cpmk_id": "CPMK-3", "description": "Mampu menyusun jadwal proyek menggunakan teknik PERT dan CPM untuk mengoptimalkan waktu penyelesaian.", "relatedCpmk": "CPMK-3"}, {"code": "Sub-CPMK-10", "cpmk_id": "CPMK-4", "description": "Mampu mengidentifikasi dan menganalisis risiko K3 dalam setiap tahap perencanaan proyek teknik.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-11", "cpmk_id": "CPMK-4", "description": "Mampu merancang rencana mitigasi risiko K3 yang sesuai dengan standar dan peraturan yang berlaku.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-12", "cpmk_id": "CPMK-4", "description": "Mampu menerapkan prosedur keselamatan kerja di lokasi proyek sesuai dengan regulasi K3 yang relevan.", "relatedCpmk": "CPMK-4"}, {"code": "Sub-CPMK-13", "cpmk_id": "CPMK-5", "description": "Mampu menyusun dan menyampaikan presentasi proyek secara jelas dan sistematis kepada tim dan stakeholder.", "relatedCpmk": "CPMK-5"}, {"code": "Sub-CPMK-14", "cpmk_id": "CPMK-5", "description": "Berpartisipasi aktif dalam diskusi kelompok dengan memberikan masukan konstruktif dan mendengarkan pendapat anggota tim lainnya.", "relatedCpmk": "CPMK-5"}], "deskripsi": "Mata kuliah Manajemen Proyek dan Keselamatan Kerja bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip manajemen proyek serta penerapan aspek keselamatan kerja dalam berbagai konteks industri. Materi yang dibahas mencakup perencanaan, pelaksanaan, pengendalian, dan penutupan proyek, serta analisis risiko dan kebijakan keselamatan kerja yang relevan. Dengan mempelajari mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan dalam merencanakan dan mengelola proyek secara efektif sambil mengutamakan keselamatan dan kesehatan kerja, sehingga mampu berkontribusi secara signifikan dalam menciptakan lingkungan kerja yang aman dan produktif di dunia profesional.", "referensi": ["Harold Kerzner (2022). Project Management: A Systems Approach to Planning, Scheduling, and Controlling. Wiley.", "G. Michael Campbell (2021). Project Management for Engineering and Technology. Elsevier.", "Joseph Heagney (2020). Fundamentals of Project Management. AMACOM.", "David Hillson (2023). Managing Risk in Projects. Routledge.", "John P. R. Howard (2023). Construction Safety Management and Engineering. Springer.", "Alice Smith (2022). Risk Analysis in Project Management: A Case Study. International Journal of Project Management.", "Robert J. Smith (2021). Effectiveness of Safety Management Systems in Construction Projects. Journal of Safety Research.", "Emily Johnson (2023). The Role of Communication in Project Success: A Review. International Journal of Project Management.", "Michael Brown (2020). Safety Culture in Construction Projects: A Review of Literature. Safety Science.", "Peter M. C. Smith (2022). Managing Health and Safety in Projects: A Comprehensive Guide. Construction Management and Economics."], "bahanKajian": ["Topik 1: Prinsip Dasar Manajemen Proyek - Memahami konsep dasar manajemen proyek, termasuk fase perencanaan, pelaksanaan, pengendalian, dan evaluasi proyek teknik.", "Topik 2: Perencanaan dan Penjadwalan Proyek - Teknik dan alat yang digunakan dalam perencanaan dan penjadwalan proyek, termasuk diagram Gantt dan metode jalur kritis.", "Topik 3: Analisis Risiko dalam Proyek - Identifikasi, analisis, dan mitigasi risiko proyek untuk meningkatkan keberhasilan dan keamanan proyek.", "Topik 4: Kebutuhan Sumber Daya Proyek - Mengidentifikasi dan merencanakan kebutuhan sumber daya manusia, material, dan finansial untuk proyek teknik.", "Topik 5: Sistem Manajemen Keselamatan dan Kesehatan Kerja (K3) - Penerapan prinsip dan standar K3 dalam perencanaan dan pelaksanaan proyek untuk menjamin keselamatan kerja.", "Topik 6: Regulasi dan Standar K3 dalam Proyek - Memahami peraturan dan standar terkait keselamatan dan kesehatan kerja yang harus dipatuhi dalam proyek teknik.", "Topik 7: Komunikasi Efektif dan Kerja Tim Multidisiplin - Pentingnya komunikasi dan kolaborasi dalam tim untuk suksesnya pelaksanaan proyek teknik.", "Topik 8: Etika Profesi dan Tanggung Jawab Sosial dalam Manajemen Proyek - Memahami etika profesi, tanggung jawab sosial, dan sikap profesional dalam manajemen proyek."], "description": "Mata kuliah Manajemen Proyek dan Keselamatan Kerja bertujuan untuk memberikan pemahaman mendalam mengenai prinsip-prinsip manajemen proyek serta penerapan aspek keselamatan kerja dalam berbagai konteks industri. Materi yang dibahas mencakup perencanaan, pelaksanaan, pengendalian, dan penutupan proyek, serta analisis risiko dan kebijakan keselamatan kerja yang relevan. Dengan mempelajari mata kuliah ini, mahasiswa diharapkan dapat mengembangkan keterampilan dalam merencanakan dan mengelola proyek secara efektif sambil mengutamakan keselamatan dan kesehatan kerja, sehingga mampu berkontribusi secara signifikan dalam menciptakan lingkungan kerja yang aman dan produktif di dunia profesional.", "bahan_kajian": ["Topik 1: Prinsip Dasar Manajemen Proyek - Memahami konsep dasar manajemen proyek, termasuk fase perencanaan, pelaksanaan, pengendalian, dan evaluasi proyek teknik.", "Topik 2: Perencanaan dan Penjadwalan Proyek - Teknik dan alat yang digunakan dalam perencanaan dan penjadwalan proyek, termasuk diagram Gantt dan metode jalur kritis.", "Topik 3: Analisis Risiko dalam Proyek - Identifikasi, analisis, dan mitigasi risiko proyek untuk meningkatkan keberhasilan dan keamanan proyek.", "Topik 4: Kebutuhan Sumber Daya Proyek - Mengidentifikasi dan merencanakan kebutuhan sumber daya manusia, material, dan finansial untuk proyek teknik.", "Topik 5: Sistem Manajemen Keselamatan dan Kesehatan Kerja (K3) - Penerapan prinsip dan standar K3 dalam perencanaan dan pelaksanaan proyek untuk menjamin keselamatan kerja.", "Topik 6: Regulasi dan Standar K3 dalam Proyek - Memahami peraturan dan standar terkait keselamatan dan kesehatan kerja yang harus dipatuhi dalam proyek teknik.", "Topik 7: Komunikasi Efektif dan Kerja Tim Multidisiplin - Pentingnya komunikasi dan kolaborasi dalam tim untuk suksesnya pelaksanaan proyek teknik.", "Topik 8: Etika Profesi dan Tanggung Jawab Sosial dalam Manajemen Proyek - Memahami etika profesi, tanggung jawab sosial, dan sikap profesional dalam manajemen proyek."], "rencanaTugas": [{"subCpmk": "Sub-CPMK-1", "tugasKe": 1, "indikator": "", "batasWaktu": "Minggu ke-1", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-2", "tugasKe": 2, "indikator": "", "batasWaktu": "Minggu ke-2", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-3", "tugasKe": 3, "indikator": "", "batasWaktu": "Minggu ke-3", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-4", "tugasKe": 4, "indikator": "", "batasWaktu": "Minggu ke-4", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-5", "tugasKe": 5, "indikator": "", "batasWaktu": "Minggu ke-5", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-6", "tugasKe": 6, "indikator": "", "batasWaktu": "Minggu ke-6", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-7", "tugasKe": 7, "indikator": "", "batasWaktu": "Minggu ke-7", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-8", "tugasKe": 8, "indikator": "", "batasWaktu": "Minggu ke-8", "judulTugas": "", "bobotPersen": "7", "luaranTugas": "", "teknikPenilaian": "", "kriteriaPenilaian": "", "petunjukPengerjaan": ""}, {"subCpmk": "Sub-CPMK-9", "tugasKe": 9, "indikator": "", "batasWaktu": "Minggu ke-9", "judulTugas": "",